NDX.HERO_TRIALS = {
  wukong: {
    1: { options: [
      { key: '顺命', label: '〔顺命〕接受转生为石猴', fate: '渡', effect: { good: 6 } },
      { key: '逆命', label: '〔逆命〕抗拒轮回，自化灵明石猴', fate: '逆', effect: { evil: 4 } },
    ] },
    2: { name: '花果山灵石迸裂', dark: '花果山灵石迸裂，石猴出世。群猴拥戴，但山下的天兵已在路上——"一块石头也配成精？"花果山的灵石，受天地灵气，吸日月精华，迸裂而出，化作石猴。群猴拥戴，称他为美猴王。但山下的天兵已经在路上——天庭容不得一块石头成精。石猴站在花果山顶，看着山下的天兵，忽然笑了："一块石头也配成精？那俺老孙今天，就让你们看看，石头怎么成精！"他一棒砸下，花果山的地动山摇，天兵吓得落荒而逃。石猴站在山顶，大笑不止——这是他第一次，向天庭说"不"。' },
    3: { name: '水帘洞探', dark: '石猴探水帘洞，洞中不是泉眼，是一面映出他"灵明石猴"本相的铜镜。花果山的水帘洞，瀑布遮天，群猴无人敢入。石猴纵身一跃，穿过瀑布，进入洞中。洞中不是泉眼，是一面巨大的铜镜，映出他"灵明石猴"的本相——金光万道，瑞气千条。石猴看着铜镜中的自己，忽然明白了：他不是普通的石猴，他是灵明石猴，是天地灵气所化，是日月精华所生。他伸手摸了摸铜镜，铜镜忽然碎裂，化作无数光点，融入他的体内。石猴站在洞中，感受着体内的力量，忽然笑了："灵明石猴？那俺老孙今天，就让你们看看，灵明石猴有多厉害！"' },
    4: { name: '称王花果', dark: '石猴称美猴王。他问群猴："你们怕天兵吗？"群猴不答——他们早已被天庭屠过一次。花果山的石猴，探水帘洞，称美猴王，群猴拥戴。他坐在水帘洞的石椅上，看着下面的群猴，忽然问："你们怕天兵吗？"群猴不答——他们早已被天庭屠过一次，花果山的尸骨，还埋在地下。石猴看着群猴的沉默，忽然明白了：他称美猴王，不是为了自己，是为了群猴，是为了花果山，是为了那些被天庭屠过的猴子。他站起身，一棒砸在石椅上："怕天兵？那俺老孙今天，就教你们怎么不怕天兵！从今天起，花果山，俺老孙罩着！天兵敢来，俺老孙一棒砸烂他们的狗头！"群猴欢呼，花果山的地动山摇。' },
    5: { name: '灵石伏虎', dark: '长安城外猛虎扑来，悟空一棒敲晕："这虎身上的城隍印，和灵山莲花一个样。"他揪下虎须："留个念想。"长安城外，猛虎扑来，张牙舞爪，要吃取经人。悟空一棒敲晕猛虎，看着它身上的城隍印，忽然笑了："这虎身上的城隍印，和灵山莲花一个样。"他揪下虎须，放在手心："留个念想。"他想起五百年前，花果山的猛虎，也是这样扑来，也是这样被他一棒敲晕。他想起五行山下，五百年的风吹雨打，不仅没压垮他，反而炼出了不屈的意志。他睁开眼，火眼金睛金光万道，看穿了猛虎的本相——一只被城隍印困住的妖虎，是天庭的棋子，是灵山的工具。他一棒砸向猛虎："城隍印？灵山莲花？那俺老孙今天，替你把这印砸了！"猛虎在地上打滚，现出原形，是一只普通的老虎，不是妖虎。悟空看着它，忽然叹了口气："普通老虎？那俺老孙今天，放你一马。记住，以后别再拦取经人的路。"老虎爬起来，落荒而逃。悟空站在长安城外，看着老虎逃走的方向，忽然笑了："留个念想？那俺老孙今天，就留个念想。"他把虎须放进怀里，继续西行。' },
    6: { name: '双叉岭猎户', dark: '双叉岭前，刘伯钦拦路。他见悟空猴相，举叉便刺："妖怪！"悟空侧身躲过，一棒压住钢叉："猎户，你杀过多少妖？"刘伯钦咬牙："九十九个。"悟空笑："那俺老孙，是第一百个——也是第一个，不杀你的。"他收棒，刘伯钦怔住，钢叉落在地上。' },
    7: { name: '双叉岭战影', dark: '岭上魔影是历代悟空的分身。它们喊："你也被写死了！"悟空大笑："写死我的笔，早被我折了。"双叉岭的魔影，是历代悟空的分身，是天庭的棋子，是灵山的工具。它们围着悟空转，喊："你也被写死了！"悟空大笑："写死我的笔，早被我折了。"他看着魔影，忽然明白了：这些魔影，不是别人，是他自己，是历代悟空的分身，是天庭写死的悟空，是灵山写死的悟空。他一棒砸向魔影："写死我的笔，早被我折了！从今天起，俺老孙的命，俺老孙自己写！"魔影在棒下散去，化作无数光点，融入他的体内。悟空站在双叉岭上，感受着体内的力量，忽然笑了："历代悟空的分身？那俺老孙今天，就把你们都收了！从今天起，俺老孙就是唯一的悟空，就是唯一的齐天大圣，就是唯一的斗战胜佛！"他继续西行，金箍棒在肩上扛着，火眼金睛金光万道，看穿了前方的路——那是取经路，是西行路，是他自己的路。' },
    8: { name: '灵台方寸', dark: '悟空寻菩提祖师学艺。祖师敲他三下后入梦："你学的是空，用的是斗。空斗不两立。"悟空醒来，头上多了一道无形箍。灵台方寸山，斜月三星洞，悟空寻菩提祖师学艺。祖师敲他三下，倒背着手，走入里面，将中门关了，撇下大众而去。悟空明白祖师的意思——三更时分，从后门进入，祖师要单独教他。三更时分，悟空从后门进入，祖师正在等他。祖师看着他，忽然说："你学的是空，用的是斗。空斗不两立。"悟空怔住——他从没想过这个问题。祖师伸手，在他头上敲了一下，悟空醒来，头上多了一道无形箍。他摸了摸头上的箍，忽然明白了：空斗不两立，他要在空与斗之间，找到自己的路。' },
    9: { name: '收心猿', dark: '取经人收悟空为徒。悟空问："师父，你念咒我头疼，不念咒我杀人——我选哪个？"取经人沉默。五行山下，取经人揭去符咒，悟空从山下跃出，抖落满身的石屑。取经人收悟空为徒，给他戴上金箍。悟空摸了摸头上的金箍，忽然问："师父，你念咒我头疼，不念咒我杀人——我选哪个？"取经人沉默——他从没想过这个问题。悟空看着取经人的沉默，忽然笑了："师父，你不用选。俺老孙自己选——俺老孙不杀人，也不让你念咒。俺老孙用这根金箍棒，护你西行，护你取经，护你到灵山。"取经人看着悟空，眼中闪过一丝泪光。他合掌："悟空，谢谢你。"悟空大笑："谢什么？俺老孙是你徒弟，护你西行，是应该的！"' },
    10: { name: '虎先锋拦路', dark: '虎先锋横刀拦路，是黄风怪座下先锋。悟空一棒敲断它的刀："风还没起，先拿你祭棒。"虎先锋化作一阵风逃了——风里的黄风怪，正在岭上等他。' },
    11: { name: '黄风卷沙', dark: '黄风怪吹起满山黄沙。悟空火眼金睛看穿风眼，见一只貂鼠盘尾而坐："偷油的是你，吹沙的也是你。灵山欠你一盏灯？"他笑了："那俺老孙今天，替你把这灯点上。"' },
    12: { name: '三昧神风', dark: '三昧神风迎面吹来，悟空火眼金睛被吹得生疼，睁不开眼。他闭目冷笑："风再大，也吹不散俺老孙心里的火。"黄风岭的三昧神风，迎面吹来，遮天蔽日。悟空火眼金睛被吹得生疼，睁不开眼。他站在风中，闭目冷笑："风再大，也吹不散俺老孙心里的火。"他想起五百年前，八卦炉里的三昧真火，烧了七七四十九天，不仅没烧死他，反而炼出了火眼金睛。他想起五行山下，五百年的风吹雨打，不仅没压垮他，反而炼出了不屈的意志。他睁开眼，火眼金睛金光万道，看穿了风眼——一只貂鼠盘尾而坐，正在吹三昧神风。他一棒砸向风眼："偷油的是你，吹沙的也是你。灵山欠你一盏灯？那俺老孙今天，替你把这灯点上！"' },
    13: { name: '黄风大圣', dark: '黄风大圣立在风眼，金目赤红。悟空火眼金睛看穿它的本相——一只被灵山困了千年的貂鼠："你吹的是怨，不是风。俺老孙今天，替你把这怨也吹散。"' },
    14: { name: '高老庄闻妖', dark: '高老庄庄主哭诉女儿被妖强占。悟空一听"能吃"，眼睛亮了："能吃？那俺老孙倒要看看，他比俺老孙还能吃？"他摇身一变，变作高小姐模样，坐在绣房里等那妖来。' },
    15: { name: '云栈洞戏猪', dark: '云栈洞中，猪八戒见"高小姐"，扑上来便抱。悟空现了本相，一棒顶住猪鼻："呆子，你强抢民女，该当何罪？"猪八戒跪地求饶："大圣饶命！我老猪前世是天蓬元帅，因情被贬，只想找个伴儿。"悟空笑："找伴儿？那跟俺老孙走，路上有的是伴儿——就是没饭吃。"' },
    16: { name: '八戒归降', dark: '猪八戒跪在取经人面前，痛哭流涕。悟空在一旁起哄："呆子，哭什么？跟俺老孙走，有妖打，有饭吃——就是没媳妇。"猪八戒抹了把泪："没媳妇就没媳妇，有饭吃就行。"悟空大笑："好！那俺老孙以后就叫你呆子！"' },
    17: { name: '高老送别', dark: '高老庄庄主送众人出门，欲言又止。悟空看出他心思："庄主，你是舍不得那呆子？"庄主叹气："那猪妖……虽能吃，却也护了我家庄园三年。"悟空拍了拍庄主肩膀："放心，那呆子跟俺老孙走，以后护的是取经人，不是你家庄园了。等取完经，他回来看你——就是不知道，那时候他还认不认得路。"' },
    18: { name: '流沙收沙', dark: '沙僧项挂九颅跪在河滩。悟空打量他："你颈上九颗，有俺老孙前世的仇？"沙僧摇头："是你师父的前世。"悟空笑了："那俺老孙替你数着，别凑满十颗。"' },
    19: { name: '五庄窃果', dark: '悟空偷人参果。"这果根缠尸骨，吃的是前辈。"他没吃，把果埋回："树比经诚实。"五庄观的人参果树，三千年一开花，三千年一结果，三千年才得熟。悟空偷了三个人参果，和八戒、沙僧分吃了。但他在树下抬头，忽然看见树根缠着累累白骨——那是历代取经人的尸骨。他看着手中的人参果，忽然明白了：这果根缠尸骨，吃的是前辈。他没吃，把果埋回树下："树比经诚实。"镇元子从殿中走出，叹道："悟空，你终于看见了。这人参果，养的不是仙，是取经人的命。"悟空怔住——他从没想过，自己偷的不是果，是前辈的命。他跪在树下，磕了三个头："前辈，对不住了。俺老孙今天，替你们把这棵树，守着。"' },
    20: { name: '三打白骨', dark: '白骨精求死："我是难簿第19笔，杀我好投胎。"悟空三打，第三棒停住："我不杀你，我撕了这页难簿。"白虎岭的白骨精，三次变化，三次被悟空打杀。第三次，白骨精没有逃，反而向悟空跪下："大圣，我是难簿第19笔，杀我好投胎。"悟空举起金箍棒，却在半空中停住了——他看着白骨精的眼睛，看见了九世取经人的死。他忽然明白了：白骨精不是妖，是难簿上的一笔，是天庭写好的剧本。他放下金箍棒，一棒砸向天空："我不杀你，我撕了这页难簿！"金箍棒砸在天空上，天空裂开一道缝，难簿从缝中落下。悟空一棒砸烂难簿，白骨精在风中化烟散去，留下一句话："大圣，谢谢你。我终于，可以投胎了。"悟空站在风中，看着白骨精散去的方向，忽然叹了口气："取经之路，打的不是妖，是天庭写好的剧本。俺老孙今天，就把这剧本，撕了！"' },
    21: { name: '贬退心猿', dark: '三打白骨后，取经人贬悟空。悟空跪求："师父，俺老孙杀的是妖，不是人。"取经人闭目念咒。悟空头顶剧痛，想起五百年五行山："佛压我，你也压我。好，俺老孙走。"金箍棒在身后拖出一道雷痕。' },
    22: { name: '黄袍换囚', dark: '黄袍怪把取经人变虎。悟空揪奎木狼："天庭走狗也配谈情？"狼啸："你当年大闹天宫，不也是走狗？"悟空棒顿。宝象国的黄袍怪，原是天上的奎木狼，下凡为妖，把取经人掳进波月洞，变作一只猛虎。悟空从花果山赶回，一棒砸开波月洞，揪住奎木狼："天庭走狗也配谈情？"奎木狼狼啸："你当年大闹天宫，不也是走狗？"悟空棒顿——他说的，是实话。他当年大闹天宫，不是为了自由，是为了被天庭承认，是为了做齐天大圣，是为了做天庭的走狗。他看着奎木狼，忽然叹了口气："你说的对。俺老孙当年，也是走狗。但俺老孙今天，不是了。"他一棒砸向奎木狼："你为了情，下凡为妖，害了多少人？今天，俺老孙就替那些被你害的人，讨个公道！"奎木狼跪在地上，现出原形。天庭的使者从云中走出，把奎木狼带回天庭。悟空看着取经人变回人形，忽然叹了口气："情之一字，最难放下。奎木狼，对不住了。"' },
    23: { name: '黑松林失', dark: '黑松林黑雾遮天，取经人被掳。悟空火眼金睛看穿雾里是宝象国方向："师父，你总说妖怪有苦衷。这掳你的不是苦衷，是圈套。"他纵身入林。' },
    24: { name: '平顶戏炉', dark: '金角银角奉旨"被收"。悟空看穿法宝上的"道具"二字："连妖都演，这天庭戏班真忙。"平顶山的金角大王、银角大王，手持紫金红葫芦、羊脂玉净瓶，拦住取经人的去路。悟空看着他们手中的法宝，忽然笑了——法宝上刻着"道具"二字，那是天庭的标记。金角银角，本是太上老君看金炉、银炉的童子，奉旨下凡为妖，"被收"回天。悟空一棒砸向金角银角："连妖都演，这天庭戏班真忙！"金角银角怔住，紫金红葫芦落在地上。悟空捡起紫金红葫芦，看着上面的"道具"二字，忽然叹了口气："取经之路，打的不是妖，是天庭演的戏。俺老孙今天，就把这戏，砸了！"他一棒砸烂紫金红葫芦，金角银角跪在地上，现出原形。太上老君从云中走出，把金角银角带回天庭。悟空看着太上老君的背影，忽然笑了："戏演完了？那俺老孙，继续西行！"' },
    25: { name: '乌鸡背尸', dark: '乌鸡国王托梦。悟空下井背尸："尸比活人轻，因为活人背着命。"乌鸡国的国王，被妖道推入井中，三年不得超生。他托梦给取经人，诉冤情，求他救自己。悟空下井背尸，尸身轻如鸿毛——那不是一个国王的尸身，是千万取经人叠成的"国"。悟空背着尸身，一步一步爬出井，忽然明白了：取经之路，背的不是经，是千万取经人的冤。他把尸身背出井，用还魂丹救活国王。国王跪在他面前："大圣，你救的不是我，是乌鸡国。"悟空摇头："不，俺老孙救的，是取经人。"他看着国王的眼睛，看见了九世取经人的死。他忽然叹了口气："尸比活人轻，因为活人背着命。国王，你背着乌鸡国的命，俺老孙背着取经人的命。咱们，都不轻。"' },
    26: { name: '黑水钓龙', dark: '鼍龙是西海旁支。悟空钓它出水："你爹的事，俺老孙替你翻。"龙泣："你比龙像龙。"黑水河的鼍龙，原是西海龙王的外甥，因逆被贬，在黑水河为妖，化舟渡取经人过河，却在江心掀翻船只，要吃取经人。悟空火眼金睛看穿鼍龙本相——西海旁支，因逆被贬。他一棒压住鼍龙头："你爹的事，俺老孙替你翻。但你敢害俺师父，俺老孙先敲你九个龙鳞！"鼍龙跪在水中，泣道："大圣饶命！我也是被天庭逼的！我爹因逆被贬，我也因逆被贬，西海容不下我们，天庭容不下我们，我们只能在黑水河为妖！"悟空怔住——他从没想过，鼍龙的逆，是被天庭逼的。他收棒，扶起鼍龙："逼的？那俺老孙今天，教你怎么反逼回去！你爹的事，俺老孙替你翻。但你要记住，逆不是罪，顺也不是德。你要做的，是自己的龙，不是天庭的狗！"鼍龙跪在水中，九片龙鳞同时发光——它们等这句话，等了千年。他泣道："大圣，你比龙像龙。"' },
    27: { name: '火云逆父', dark: '红孩儿的三昧真火，是悟空八卦炉里偷学的。悟空棒指："子承父业？那我今天教你——火，该烧天庭。"号山枯松涧火云洞的红孩儿，手持火尖枪，口喷三昧真火，拦住取经人的去路。悟空火眼金睛看穿红孩儿本相——牛魔王和铁扇公主的儿子，三昧真火，是从八卦炉里偷学的。他一棒砸向红孩儿："子承父业？那我今天教你——火，该烧天庭！"红孩儿怔住——他从没想过，三昧真火该烧天庭。他看着悟空，忽然笑了："大圣，你说的对。三昧真火，不该烧取经人，该烧天庭！"他收起火尖枪，跪在地上："大圣，我跟你走！我要用三昧真火，烧天庭！"悟空扶起红孩儿，忽然叹了口气："孩子，火该烧天庭，但不是现在。现在，你要做的，是跟观音菩萨走，修心养性，等你长大了，再烧天庭，不迟。"红孩儿点头，观音菩萨从云中走出，把红孩儿带走。悟空看着红孩儿的背影，忽然笑了："三昧真火，该烧天庭。孩子，等你长大了，俺老孙陪你一起烧！"' },
    28: { name: '黑水擒龙', dark: '黑水河黑水滔滔，鼍龙化舟渡取经人过河。悟空火眼金睛看穿鼍龙本相——西海旁支，因"逆"被贬。他一棒压住鼍龙头："你爹的事，俺老孙替你翻。但你敢害俺师父，俺老孙先敲你九个龙鳞！"鼍龙跪地求饶："大圣饶命！我也是被天庭逼的！"悟空收棒："逼的？那俺老孙今天，教你怎么反逼回去。"' },
    29: { name: '车迟国前', dark: '车迟国国王崇道灭佛，和尚被赶去做苦役。悟空路过城门，见两个道士鞭打和尚。他火眼金睛看穿道士本相——虎力、鹿力、羊力三妖。他一棒砸开城门："三个杂毛，也敢在俺老孙面前装神弄鬼？"道士们吓得跪地求饶。悟空大笑："求雨？俺老孙一个喷嚏，就能下三天三夜的雨！"' },
    30: { name: '三清观戏', dark: '三清观中，虎力、鹿力、羊力三妖化作三清，受香火供奉。悟空夜探三清观，见供桌上的素斋——那是和尚们饿着肚子供的。他一棒砸烂三清像："三个杂毛，也配受香火？"三妖现原形，跪地求饶。悟空大笑："求雨？俺老孙一个喷嚏，就能下三天三夜的雨！你们求了半个时辰，滴雨未下，还有脸受香火？"' },
    31: { name: '高台求雨', dark: '车迟国高台求雨，虎力大仙登坛作法。悟空在台下合掌，默念《心经》。虎力求了半个时辰，滴雨未下。悟空登台，只念了一句"阿弥陀佛"，天降甘霖。国王大惊："圣僧真神！"悟空大笑："不是神，是心诚。你们求雨，求的是自己的面子；俺老孙求雨，求的是百姓的活路。心不一样，雨自然不一样。"' },
    32: { name: '隔板猜物', dark: '车迟国隔板猜物，鹿力大仙与悟空比试。柜中放的是山河社稷袄，乾坤地理裙。悟空合掌，默念《心经》，心中浮现柜中之物——"山河社稷袄，乾坤地理裙。"国王大惊。悟空大笑："不是俺老孙能猜，是这世上的物，都在经里。你们猜物，猜的是自己的贪欲；俺老孙猜物，猜的是万物的本相。心不一样，猜的自然不一样。"' },
    33: { name: '云梯显圣', dark: '车迟国云梯显圣，羊力大仙与悟空比试坐禅。云梯高百丈，悟空合掌而上，心中默念《心经》。羊力在云端坐了三个时辰，终于撑不住落下。悟空仍在云端，合掌不语。国王叹："圣僧真乃活佛！"悟空睁眼："不是佛，是心定。你们坐禅，坐的是自己的面子；俺老孙坐禅，坐的是万物的本相。心不一样，坐的自然不一样。"' },
    34: { name: '车迟除妖', dark: '车迟国三妖现原形，虎力、鹿力、羊力跪地求饶。悟空一棒压住三妖："你们崇道灭佛，害了多少和尚？"三妖泣道："我们也是被天庭利用，求大圣饶命。"悟空收棒："饶命可以，但你们要替那些被你们害死的和尚，念经超度。"三妖叩首，含泪念经。悟空大笑："这才像话！以后再敢装神弄鬼，俺老孙一棒敲碎你们的狗头！"' },
    35: { name: '金兜碎琢', dark: '金刚琢套尽万物。悟空冷笑："套我？俺老孙早空了。"青牛精手抖——套不住空人。金兜山的青牛精，手持金刚琢，套尽万物，拦住取经人的去路。悟空看着他手中的金刚琢，忽然冷笑："套我？俺老孙早空了。"青牛精举起金刚琢，向悟空套来——却在半空中停住了。他手抖，因为他套不住"已空"的人。悟空看着他，忽然笑了："青牛，你套尽万物，可套得住空？"青牛精怔住，金刚琢落在地上。太上老君从云中走出，叹道："悟空，你终于空了。"悟空看着太上老君，忽然叹了口气："空？俺老孙不是空了，是懂了。取经之路，取的不是经，是自己的心。心空了，经就取到了。"他一棒砸向青牛精："你偷了金刚琢下凡，可偷得来空？今天，俺老孙就教你，什么是空！"青牛精跪在地上，现出原形。太上老君把青牛精带回天庭。悟空看着太上老君的背影，忽然笑了："空？俺老孙今天，才真的空了。"' },
    36: { name: '金兜降牛', dark: '金兜山青牛精现原形，跪地求饶。悟空一棒压住青牛头："你是太上老君的坐骑，偷了金刚琢下凡。你可知罪？"青牛精泣道："我知罪。我只是想尝尝，不被人骑的滋味。"悟空收棒："不被人骑的滋味，不是偷来的，是挣来的。你跟俺老孙西行一路，便懂了。"青牛精叩首，含泪随老君回天宫。悟空大笑："这才像话！以后再敢偷东西，俺老孙一棒敲碎你的牛头！"' },
    37: { name: '女儿国关', dark: '女王留悟空。悟空变蜂落她肩："你嫁的是取经人，不是俺老孙。可惜取经人也身不由己。"西梁女国的女王，倾国倾城，愿以一国之富，招取经人为王，她为王后。悟空变作一只蜜蜂，落在女王肩上，听她和取经人的对话。女王看着取经人的眼睛，第一次动摇了："御弟哥哥，你当真要走？"取经人合掌："女王，贫僧已许身佛门，不敢再恋红尘。"女王落泪："御弟哥哥，你取经，是为了谁？"取经人沉默——他从没想过这个问题。悟空在女王肩上，忽然叹了口气："你嫁的是取经人，不是俺老孙。可惜取经人也身不由己。"女王怔住——她听见了悟空的声音。她回头，看见一只蜜蜂落在肩上，忽然笑了："大圣，你说的对。取经人身不由己，我也身不由己。但我想知道，取经人取经，到底是为了谁？"悟空落在女王手上，变回原形："为了谁？为了大唐，为了百姓，为了天下苍生。但说到底，是为了他自己。取经之路，取的不是经，是自己的心。"女王怔住，眼中闪过一丝泪光。她合掌："大圣，谢谢你。我终于，明白了。"' },
    38: { name: '猴王戏女王', dark: '悟空变作取经人与女王周旋。女王笑："你不是他。"悟空愣住——她看穿了变身。西梁女国的女王，倾国倾城，愿以一国之富，招取经人为王，她为王后。取经人不敢见女王，悟空变作取经人的模样，与女王周旋。女王看着"取经人"的眼睛，忽然笑了："你不是他。"悟空愣住——她看穿了变身。他变回原形，挠了挠头："女王，你怎么看出来的？"女王笑了："他的眼睛里，有慈悲，有坚定，有取经的决心。你的眼睛里，只有调皮，只有好奇，只有看热闹。你们不一样。"悟空怔住——他从没想过，自己和取经人的区别，在眼睛里。他看着女王的眼睛，忽然叹了口气："女王，你说的对。俺老孙和师父，不一样。师父取经，是为了天下苍生；俺老孙护师父西行，是为了师父。但说到底，我们都是为了自己。师父取的是经，俺老孙取的是义。"女王落泪："大圣，谢谢你。我终于，明白了。取经人取经，是为了天下苍生；你护师父西行，是为了义。你们，都是好人。"悟空挠了挠头，忽然笑了："好人？俺老孙可不是好人。俺老孙是齐天大圣，是美猴王，是取经人的大徒弟。好人？那是师父。"' },
    39: { name: '蝎子精刺', dark: '毒敌山琵琶洞蝎子精掳取经人入洞，欲逼成亲。悟空火眼金睛看穿蝎子精本相——她的毒针，是如来佛祖的指甲。他一棒砸开琵琶洞："你这蝎子，偷了如来的指甲，也敢在俺老孙面前装神弄鬼？"蝎子精冷笑："偷来的指甲，也是指甲。你这猴子，偷了蟠桃，偷了仙丹，还有脸说我？"悟空怔住——她说的，是实话。昴日星官收服蝎子精，悟空叹："偷来的东西，终究不是自己的。"' },
    40: { name: '蝎针破佛', dark: '蝎子精倒马毒桩。悟空火眼看出毒针是如来指甲："佛也长指甲？那今天拔了它。"毒敌山琵琶洞的蝎子精，手持三股钢叉，尾后倒马毒桩，拦住取经人的去路。她一毒桩刺来，悟空伸手去挡，毒针刺中他的手掌，剧痛钻心。悟空火眼金睛看穿毒针本相——那是如来佛祖的指甲。他一棒砸向蝎子精："佛也长指甲？那今天拔了它！"蝎子精冷笑："大圣，你偷了蟠桃，偷了仙丹，还有脸说我？"悟空怔住——她说的，是实话。他看着蝎子精，忽然叹了口气："你说的对。俺老孙偷了蟠桃，偷了仙丹，偷了很多东西。但俺老孙偷的，是天庭的东西，不是佛的东西。你偷了如来的指甲，可偷得来如来的法？"蝎子精怔住，三股钢叉落在地上。昴日星官从云中走出，双翅一展，蝎子精现了原形。悟空看着蝎子精的尸体，忽然叹了口气："偷来的东西，终究不是自己的。蝎子精，对不住了。"' },
    41: { name: '火焰山前', dark: '火焰山烈焰冲天，八百里火焰，无春无秋，四季皆热。悟空火眼金睛看穿火焰本相——这火，是当年他踢翻太上老君的炼丹炉，落下的火。他低头不语。取经人合掌："解铃还须系铃人。这火，还得俺老孙来灭。"悟空抬头："师父，俺老孙这就去借芭蕉扇！"他一个筋斗，翻向翠云山。' },
    42: { name: '三调芭蕉', dark: '孙悟空三调芭蕉扇，与牛魔王、铁扇公主斗法。悟空变虫入铁扇公主腹，变牛魔王骗芭蕉扇，又与牛魔王大战三百回合。终于借到芭蕉扇，扇灭八百里火焰。取经人合掌："火灭了，可心里的火，何时能灭？"悟空笑："师父，到了灵山，心里的火，自然就灭了。"他收起芭蕉扇，继续西行。' },
    43: { name: '祭赛国前', dark: '祭赛国金光寺塔顶舍利被盗，国王震怒，将众僧下狱。悟空夜探金光寺，火眼金睛看穿塔顶妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。他揪起一个老僧："舍利被偷了，你们哭什么？哭能把舍利哭回来？"老僧泣道："舍利乃国之镇宝，失则国亡。"悟空笑："国亡不亡，不在舍利，在人心。俺老孙今天，替你们把舍利偷回来——不过俺老孙偷东西，从来先讲价。"' },
    44: { name: '碧波潭探', dark: '碧波潭底，万圣龙宫灯火通明。九头虫把舍利当夜明珠，挂在龙女床头。悟空潜入龙宫，见龙女抱着舍利喃喃："偷来的光，也是光。"他变虫落龙女发间："你偷了舍利，救他的命。他呢？他连舍利都偷，就是不肯偷一颗真心给你。"龙女手抖，舍利落入潭中。悟空伸手接住舍利，一个筋斗翻回岸上。' },
    45: { name: '真假心猿', dark: '六耳猕猴是悟空"不敢认的自己"。两猴打到灵山，佛不辨。悟空悟："假的是我，真的也是我。"花果山的六耳猕猴，化作悟空的模样，打昏取经人，抢走行李，要自己去取经。悟空回来，看见两个"自己"站在面前——一个是真的，一个是假的。他分不清哪个是自己，正如分不清"取经"哪句是真。两猴打到天庭，天庭分不清；打到观音，观音分不清；打到地府，地府分不清；打到灵山，如来佛祖才分清。悟空看着真悟空打死假悟空，忽然明白了：六耳猕猴不是别人，是他"不敢认的自己"——是他的恶，是他的贪，是他的嗔，是他的痴。他跪在如来佛祖面前，合掌："佛，假的是我，真的也是我。六耳猕猴，是俺老孙不敢认的自己。今天，俺老孙认了。"如来佛祖点头："善哉善哉。悟空，你终于，认了自己。"悟空站起身，看着取经人，忽然笑了："师父，俺老孙今天，才真的成了你的徒弟。"' },
    46: { name: '火焰借扇', dark: '铁扇公主不借扇。悟空变虫入她腹："借不借？不借我在你肚里安家。"火焰山的铁扇公主，手持芭蕉扇，一扇息火，二扇生风，三扇下雨。悟空向她借扇，她却不借——因为悟空降了她的儿子红孩儿。悟空变作一只小虫，趁铁扇公主喝茶的时候，钻入她的腹中。他在铁扇公主的腹中，翻跟头，打拳，踢腿，铁扇公主疼得满地打滚。悟空在她腹中大笑："借不借？不借我在你肚里安家！"铁扇公主疼得受不了，只好答应借扇。悟空从她口中飞出，变回原形，接过芭蕉扇。他看着铁扇公主，忽然叹了口气："女菩萨，对不住了。俺老孙也是被逼的。你恨俺老孙降了红孩儿，可你知道吗？红孩儿在观音身边，比在你身边好。"铁扇公主落泪，芭蕉扇从手中落下。悟空捡起芭蕉扇，一个筋斗，翻回火焰山。他看着八百里火焰，忽然笑了："火灭了，可心里的火，何时能灭？"' },
    47: { name: '牛魔王战', dark: '牛魔王现出原形，一头大白牛，头如峻岭，眼若闪光。悟空一棒压住牛头："牛大哥，你与俺老孙是结拜兄弟，何必相煎太急？"牛魔王怒吼："结拜兄弟？你欺我妻子，辱我孩儿，还配叫兄弟？"悟空怔住——他说的，是实话。两妖大战三百回合，悟空终于降服牛魔王。他叹："情之一字，最难放下。牛大哥，对不住了。"' },
    48: { name: '罗刹女泪', dark: '铁扇公主交出芭蕉扇，泪流满面。悟空变蜂落她肩："女菩萨，你与牛魔王的恩怨，到此为止吧。"铁扇公主泣道："大圣，我与牛魔王夫妻一场，如今他被降服，我活着还有什么意思？"悟空叹："活着，就是意思。你把芭蕉扇借给我们，扇灭火焰山，便是功德一件。"铁扇公主点头，含泪回翠云山。悟空收起芭蕉扇，继续西行。' },
    49: { name: '火焰山过', dark: '孙悟空扇灭八百里火焰，火焰山从此四季如春。悟空收起芭蕉扇，大笑："师父，这火，是俺老孙当年踢翻炼丹炉落下的，如今俺老孙亲手灭了，也算因果报应。"取经人合掌："因果报应，丝毫不爽。我们西行取经，便是要了这因果。"众人继续西行。悟空回头望了一眼火焰山，心中暗想："俺老孙的因果，何时能了？"' },
    50: { name: '祭赛金光', dark: '祭赛国金光寺金光尽失。悟空登塔，塔尖的舍利没了，塔底跪着和尚。他摸摸头顶的箍："俺老孙也当过弼马温，知道被锁的滋味。走，去碧波潭讨债。"祭赛国金光寺塔顶舍利被盗，国王震怒，将满寺僧众下狱，严刑拷打。悟空登塔，见塔尖的舍利没了，塔底跪着和尚，一个个面黄肌瘦，伤痕累累。他摸摸头顶的金箍，忽然叹了口气："俺老孙也当过弼马温，知道被锁的滋味。这些和尚，被锁在金光寺，被锁在祭赛国，被锁在天庭的剧本里。俺老孙今天，就替他们把这锁，砸了！"他一棒砸开塔门，揪起一个老僧："舍利被偷了，你们哭什么？哭能把舍利哭回来？"老僧泣道："舍利乃国之镇宝，失则国亡。"悟空笑："国亡不亡，不在舍利，在人心。俺老孙今天，替你们把舍利偷回来——不过俺老孙偷东西，从来先讲价。"他望向西方，妖雾正浓——那是碧波潭的方向。他一个筋斗，翻向碧波潭："走，去碧波潭讨债！"' },
    51: { name: '祭赛寻珠', dark: '祭赛国舍利被窃。悟空潭底摸出舍利："真舍利在和尚心里，不在塔尖。"祭赛国金光寺塔顶舍利被盗，国王震怒，将满寺僧众下狱，严刑拷打。悟空潜入碧波潭底，摸出舍利，看着它发出的金光，忽然笑了："真舍利在和尚心里，不在塔尖。"他想起五百年前，花果山的灵石，也是这样发出金光，也是这样被天庭视为异端。他想起五行山下，五百年的风吹雨打，不仅没压垮他，反而炼出了不屈的意志。他睁开眼，火眼金睛金光万道，看穿了舍利的本相——不是祭赛国的镇宝，不是金光寺的光，不是百姓的命，是天庭的棋子，是灵山的工具，是写死的剧本。他一棒砸向舍利："真舍利在和尚心里，不在塔尖！从今天起，俺老孙的命，俺老孙自己写！"舍利在棒下发出更亮的金光，化作无数光点，融入他的体内。悟空站在碧波潭底，感受着体内的力量，忽然笑了："祭赛国舍利？那俺老孙今天，就把你收了！从今天起，俺老孙就是唯一的悟空，就是唯一的齐天大圣，就是唯一的斗战胜佛！"他带着舍利，一个筋斗，翻回祭赛国，把舍利还给金光寺的和尚。和尚们跪在地上，泪流满面："大圣，谢谢你。"悟空大笑："谢什么？俺老孙是你们的护法，护你们西行，是应该的！"' },
    52: { name: '盗宝遭擒', dark: '碧波潭夺舍利。悟空潜入龙宫，见九头虫把舍利当夜明珠，挂在龙女床头。他伸手去拿，龙女睁眼："偷光的人，也不怕黑？"悟空愣住，反手把舍利塞进她手里："俺老孙不偷。要偷，也偷你自己那份光。"' },
    53: { name: '万圣盗草', dark: '万圣公主盗九叶灵芝给九头虫续命。悟空变虫落她发间："你偷王母的草，救他的命。他呢？他连舍利都偷，就是不肯偷一颗真心给你。"公主手抖，灵芝落入潭中。' },
    54: { name: '祭赛国厄', dark: '九头虫九头齐出，舍利在它腹中发光。悟空钻它肚里抢舍利："九个脑袋，抢不过俺老孙一颗石心。"九头虫翻身，悟空扯出舍利，一棒砸向它第九颗头。' },
    55: { name: '木仙谈诗', dark: '荆棘岭上树精拉着师徒吟诗。悟空变出火眼："谈诗？俺老孙听得出——你们诗里全是舍不得的根。"树精笑："你这猴子，比我们更像木头。"悟空一棒扫开荆棘："木头成精，也要赶路。"' },
    56: { name: '小雷音诈', dark: '小雷音假佛坐殿。悟空一棒砸殿："假佛也配收香火？"殿塌，露出弥勒的布袋。小雷音寺的黄眉老佛，化作如来佛祖的模样，坐在雷音寺的大殿上，受香火供奉。悟空走进大殿，看见"如来佛祖"端坐莲台，金光万道，瑞气千条。他火眼金睛看穿本相——黄眉老佛，弥勒佛的童子。他一棒砸向大殿："假佛也配收香火？"大殿轰然倒塌，露出弥勒佛的人种袋。黄眉老佛从废墟中爬出，跪地求饶："大圣饶命！我只是想尝尝，当佛的滋味。"悟空一棒压住黄眉老佛的头："当佛的滋味？佛不是当的，是修的。你偷了弥勒佛的人种袋，下凡为妖，害了多少人？今天，俺老孙就替那些被你害的人，讨个公道！"弥勒佛从云中走出，叹道："悟空，你终于看见了。佛不在殿上，在难中。"悟空看着弥勒佛，忽然叹了口气："佛不在殿上，在难中。弥勒佛，你说的对。俺老孙今天，才真的懂了。"' },
    57: { name: '朱紫国医', dark: '朱紫国王悬丝诊脉，悟空变神医入宫。国王说病根在心。悟空笑："你的心被人偷了？那俺老孙替你偷回来——不过俺老孙偷东西，从来先讲价。"' },
    58: { name: '狮驼三魔', dark: '狮驼岭三魔食城。悟空立城头："食尽一城又如何？灵山食的，是千万城。"狮驼岭的青毛狮子怪、黄牙老象怪、大鹏金翅雕，三魔联手，食尽狮驼国一城百姓，连骨头都没剩下。悟空站在狮驼国的城头上，看着满城的尸骨，忽然明白了——取经路，原是尸路。九世取经人，都死在这条路上，连骨头都没剩下。他一棒砸在城头上："食尽一城又如何？灵山食的，是千万城！"三魔怔住，大鹏金翅雕落在他面前："大圣，你看见了？这狮驼国，原是灵山的脚下。灵山食的，是千万城。"悟空抬头望向西方，灵山就在那里——金光万道，瑞气千条。他忽然明白了：取经之路，取的不是经，是自己的心。他一棒砸向三魔："你们食尽一城，可食得来世？今天，俺老孙就替那些被你们食的人，讨个公道！"三魔跪在地上，现出原形。如来佛祖从云中走出，把三魔带回灵山。悟空看着如来佛祖的背影，忽然笑了："灵山食的，是千万城。如来，你说的对。但俺老孙今天，才真的懂了。"' },
    59: { name: '祭赛金光', dark: '祭赛国金光寺塔顶舍利被盗，国王震怒，将众僧下狱。悟空夜探金光寺，火眼金睛看穿塔顶妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。他揪起一个老僧："舍利被偷了，你们哭什么？哭能把舍利哭回来？"老僧泣道："舍利乃国之镇宝，失则国亡。"悟空笑："国亡不亡，不在舍利，在人心。俺老孙今天，替你们把舍利偷回来——不过俺老孙偷东西，从来先讲价。"' },
    60: { name: '灭法国难', dark: '灭法国要杀万名僧。悟空潜入宫，一夜剃光满朝君臣的头发："杀僧？俺老孙先让你们当一天僧。"国王醒来摸着头顶，愣了半晌："……妖猴，你剃得好。"灭法国的国王，前世是个和尚，被佛抛弃，转世为王，立志杀万名僧，以泄心头之恨。悟空潜入宫中，一夜之间，剃光了满朝君臣的头发，连国王、王后、王子、公主都没放过。国王醒来，摸着自己的光头，愣了半晌："……妖猴，你剃得好。"悟空从梁上跃下，一棒压住国王的头："杀僧？俺老孙先让你们当一天僧！你杀了九千九百九十九个和尚，只差一个，就满万了。可你下不了手，因为你知道，你杀的不是僧，是你自己的心。"国王跪在地上，泪流满面："大圣，我杀了九千九百九十九个和尚，可我心里，还是个和尚。我杀的不是僧，是我自己。"悟空收棒，扶起国王："你终于，懂了。灭法国，从此改名为钦法国。杀僧，不如度僧。度僧，不如度己。"国王叩首，灭法国从此改名为钦法国。悟空看着国王的背影，忽然笑了："杀僧？俺老孙今天，才真的度了一个僧。"' },
    61: { name: '隐雾山折', dark: '隐雾山妖设梅花计摄走取经人。悟空火眼识破雾中梅影："藏头露尾，算什么妖？"他一棒挑飞雾帐，露出豹精本相："豹子学梅花，也不怕辱没了花。"隐雾山的艾叶花皮豹子精，用分瓣梅花计，化作取经人的模样，要骗取经人入洞。悟空火眼金睛看穿本相——艾叶花皮豹子精，隐雾山的妖王。他一棒挑飞雾帐，露出豹精本相："藏头露尾，算什么妖？豹子学梅花，也不怕辱没了花。"豹精怔住——他从没想过，自己的分瓣梅花计，会被悟空一眼看穿。他跪在地上，现出原形："大圣饶命！我只是想尝尝，唐僧肉的滋味。"悟空一棒压住豹精的头："唐僧肉？你以为吃了唐僧肉，就能长生不老？错了！唐僧肉，不是长生不老药，是取经人的命。你吃了他，不是长生不老，是永世不得超生！"豹精跪在地上，瑟瑟发抖。悟空看着他，忽然叹了口气："豹子学梅花，也不怕辱没了花。你学梅花计，可你知道吗？梅花，是傲雪的，不是藏头露尾的。你要学，就学梅花的骨，不要学梅花的形。"豹精叩首，隐雾山从此改名为梅花山。悟空看着豹精的背影，忽然笑了："豹子学梅花，也不怕辱没了花。今天，俺老孙才真的教了一只豹子，什么是梅花。"' },
    62: { name: '凤仙求雨', dark: '凤仙郡三年不雨。悟空上天找玉帝："你赌气不下雨，苦的是百姓。"玉帝怒。悟空冷笑："俺老孙也赌过气，赌输了，把自己赌进五行山。你比俺老孙高明？"他抢过雷公电母的令牌，替凤仙郡下了场雨。' },
    63: { name: '玉华传棒', dark: '玉华州三王子拜师。悟空教他们棒法："成佛的捷径？俺老的棒就是捷径。"三王子学得满头大汗，悟空一棒点住："记住——棒是死的，心是活的。心活了，棒才快。"' },
    64: { name: '竹节山斗', dark: '竹节山九灵元圣一声吼，九个头一起咬来。悟空火眼看清它只是太乙救苦天尊的坐骑："你主人骑你，你咬别人。冤有头债有主，你的头，该咬你的主人。"' },
    65: { name: '金平府灯', dark: '金平府三头犀牛假冒佛收灯油。悟空火眼识破："灯油是百姓点的，你们偷油还收香火，比俺老孙当年偷蟠桃还贪。"他一棒打落犀角："油还回去，灯照你们自己。' },
    66: { name: '给孤园厄', dark: '给孤园天竺公主招亲，悟空变蜂窥探，看出她是玉兔精假扮。他落回取经人肩头："师父，那公主是兔儿爷。你娶她，是要跟月亮结亲。"取经人叹了口气。' },
    67: { name: '铜台府案', dark: '铜台府寇员外被害，取经人被诬为盗。悟空不辩，只挨了一夜板子。天明他站起来："俺老孙当年被压五行山，都没喊过冤。这板子，权当替师父挨的。"' },
    68: { name: '天竺国前', dark: '天竺国国都，繁华似锦。悟空火眼金睛看穿公主本相——玉兔精假扮。他笑："师父，天竺国的公主，可是玉兔精假扮的。"取经人叹："真假难辨，正如取经之路。我们西行取经，取的不是经，是自己的心。"悟空一棒砸开宫殿："你这玉兔，偷了嫦娥的灵药，也敢在俺老孙面前装神弄鬼？"玉兔精冷笑："偷来的灵药，也是灵药。你这猴子，偷了蟠桃，还有脸说我？"悟空怔住——她说的，是实话。' },
    69: { name: '玉兔精现', dark: '天竺国公主抛绣球招亲，取经人被砸中。公主笑："取经人，你取的是经，还是自己？"取经人合十——这一问，比八十一难都重。悟空火眼金睛看穿公主本相——玉兔精假扮。他一棒砸开宫殿："你这玉兔，偷了嫦娥的灵药，也敢在俺老孙面前装神弄鬼？"玉兔精冷笑："偷来的灵药，也是灵药。你这猴子，偷了蟠桃，还有脸说我？"悟空怔住——她说的，是实话。嫦娥收服玉兔精，悟空叹："偷来的东西，终究不是自己的。"' },
    70: { name: '铜台府案', dark: '铜台府寇员外斋僧被害，取经人被诬为盗。悟空不辩，只挨了一夜板子。天明他站起来："俺老孙当年被压五行山，都没喊过冤。这板子，权当替师父挨的。"取经人合掌："悟空，委屈你了。"悟空笑："师父，不委屈。俺老孙的命，都是师父给的。"众人继续西行。' },
    71: { name: '灵山前望', dark: '灵山在望，金光万道。悟空笑："师父，到了灵山，我们就能取经了。"取经人叹："取经之路，九九八十一难，我们都走过来了。最后一难，又算得了什么？"悟空回头望了一眼来时的路，心中暗想："取经之路，取的不是经，是自己的心。如今到了灵山，心，又在哪里？"他摸了摸头上的金箍，忽然觉得这箍，比五行山还重。' },
    72: { name: '凌云渡前', dark: '凌云渡前，弱水滔滔。接引佛祖撑船而来："取经人，上船吧。"取经人上船，船行至江心，忽然翻了——取经人落水，却见水中有一具死尸。悟空笑："师父，那死尸，是你自己。"取经人怔住——过了凌云渡，他就不再是他了。悟空也跳下水，却见水中也有一具死尸——那是他自己。他怔住——过了凌云渡，他也不再是他了。他摸了摸头上的金箍，忽然觉得这箍，比五行山还重。' },
    73: { name: '化电归真', dark: '雷音门前，悟空看着自己金箍棒上的电光："这电，是俺老孙偷来的。就像俺老孙的命，也是偷来的。"他笑："偷来的，才更要还——还给自己。"' },
    74: { name: '雷音寺前', dark: '雷音寺前，金光万道。悟空笑："师父，到了雷音寺，我们就能取经了。"取经人叹："取经之路，九九八十一难，我们都走过来了。最后一难，又算得了什么？"悟空回头望了一眼来时的路，心中暗想："取经之路，取的不是经，是自己的心。如今到了雷音寺，心，又在哪里？"他摸了摸头上的金箍，忽然觉得这箍，比五行山还重。' },
    75: { name: '如来佛祖', dark: '如来佛祖端坐莲台，金光万道。取经人合掌："弟子玄奘，奉东土大唐皇帝旨意，前来拜佛求经。"如来佛祖笑："玄奘，你取经十世，到底取的是什么？"取经人怔住——这一问，比八十一难都重。悟空也怔住——他忽然明白，取经之路，取的不是经，是自己的心。如来佛祖点头："善哉善哉。你终于明白了。"悟空摸了摸头上的金箍，忽然觉得这箍，比五行山还重。' },
    76: { name: '问佛根源', dark: '悟空上灵山问佛："师父，取经到底为了啥？"佛不答。悟空看佛座下压着的经卷："你不说，俺老孙自己找。"他转身，用金箍棒挑了挑佛前的灯："灯要是假的，就别点。"' },
    77: { name: '灵山成正果', dark: '灵山册封，悟空被封斗战胜佛。他低头看自己头上的箍："这箍，还在。"他抬头："成佛了，还是箍里的猴？"他一把扯下金箍——"俺老孙，不当箍里的佛。"' },
    78: { name: '取经回东', dark: '取经人取到真经，辞别如来，回东土大唐。悟空笑："师父，我们终于取经成功了。"取经人叹："取经之路，九九八十一难，我们都走过来了。如今取经成功，却不知该喜还是该悲。"悟空回头望了一眼灵山，心中暗想："取经之路，取的不是经，是自己的心。如今经取到了，心，又在哪里？"他摸了摸头上的金箍，忽然觉得这箍，比五行山还重。' },
    79: { name: '通天河遇', dark: '通天河前，弱水滔滔。老鼋游来："取经人，上船吧。"取经人上船，船行至江心，老鼋忽然问："取经人，我当年托你问如来佛祖，我何时能脱壳成人，你问了吗？"取经人怔住——他忘了。老鼋大怒，将船掀翻，众人落水，真经也被水浸湿。悟空也落水，却见水中也有一具死尸——那是他自己。他怔住——过了凌云渡，他就不再是他了。他摸了摸头上的金箍，忽然觉得这箍，比五行山还重。' },
    80: { name: '真经晒干', dark: '众人落水，真经被水浸湿。悟空笑："师父，我们把真经晒干就是了。"众人将真经摊在石头上晒干，却发现最后一页被石头粘住，撕坏了一角。取经人叹："真经不全，如何是好？"悟空笑："师父，真经不全，正如人生不全。不全，才是真。"取经人点头："善哉善哉。不全，才是真。"悟空摸了摸头上的金箍，忽然觉得这箍，比五行山还重。他抬头望了一眼天空，心中暗想："俺老孙的因果，何时能了？"' },
    81: { name: '无字碑终', intro: '自沉："他碎了金箍，也碎了因果。西游，从此是传说。"\n隐藏「六耳成佛」：六耳代渡，真悟空留岸。' },
  },
  bajie: {
    1: { options: [
      { key: '顺命', label: '〔顺命〕接受天蓬被贬', fate: '渡', effect: { good: 6 } },
      { key: '逆命', label: '〔逆命〕拒绝投猪胎，强留人形', fate: '逆', effect: { evil: 4 } },
    ] },
    2: { name: '天河谪贬', dark: '天蓬酒后调戏嫦娥，被打下凡。错投猪胎时他咬断脐带，落地已是獠牙半猪人。天河的天蓬元帅，酒后调戏嫦娥，被玉帝打下凡，错投猪胎。他在母猪肚子里，咬断脐带，落地已是獠牙半猪人。他看着水中的倒影，忽然哭了——那不是天蓬元帅，那是一头猪。他想起嫦娥的脸，想起天河的水，想起自己曾经是天庭的水军元帅。他一耙砸向水中的倒影："天蓬？俺老猪今天，才真的成了猪！"他站在猪圈里，看着身边的小猪，忽然笑了："猪就猪吧。至少，猪不用调戏嫦娥，不用被打下凡，不用错投猪胎。猪，至少是自由的。"' },
    3: { name: '云栈洞栖', dark: '猪妖占据云栈洞，八戒赶走他。洞中藏着嫦娥的画像——他被贬后仍在画。福陵山的云栈洞，被一个猪妖占据。八戒一耙砸开洞门，赶走猪妖，占据了云栈洞。洞中藏着嫦娥的画像——他被贬后仍在画，画了一张又一张，画了一年又一年。他看着画像中的嫦娥，忽然哭了："嫦娥，俺老猪对不起你。俺老猪当年，不该酒后调戏你。俺老猪今天，成了猪，再也配不上你了。"他一耙砸向画像，却在半空中停住了——他舍不得。他把画像挂在洞壁上，每天看着，每天画着，每天想着。他坐在洞中，忽然叹了口气："云栈洞？俺老猪今天，才真的成了洞主。可这洞主，当得真没意思。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一张画像，一个洞。"' },
    4: { name: '高老庄婚', dark: '八戒入赘高老庄。新婚夜他变回猪形，新娘却笑了："我嫁的就是妖。"——她是山魈。高老庄的高太公，招八戒入赘，把女儿高翠兰许配给他。新婚夜，八戒喝多了，变回猪形，露出獠牙。高翠兰看着他，忽然笑了："我嫁的就是妖。"——她是山魈，修炼千年，化作人形，一直在等一个真正的妖。八戒怔住——他从没想过，高翠兰是山魈。他看着她的眼睛，忽然哭了："翠兰，俺老猪是猪，不是妖。你是山魈，是妖。我们，不一样。"高翠兰笑了："猪怎么了？妖怎么了？我嫁的是你，不是猪，不是妖。我嫁的是天蓬元帅，是猪八戒，是你。"八戒跪在地上，泪流满面。他一耙砸向洞房的墙壁："翠兰，俺老猪今天，才真的成了亲。可这亲，成得真不容易。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一个山魈，一个洞房。"' },
    5: { name: '猪鼻嗅虎', dark: '长安城外虎精扑来。八戒猪鼻一嗅："这虎吃过九世取经人，肉臭。"他一耙拍晕虎："留着师父发落。"长安城外，虎精扑来，张牙舞爪，要吃取经人。八戒猪鼻一嗅，嗅出虎精身上的味道——这虎吃过九世取经人，肉臭。他一耙拍晕虎精："留着师父发落。"他看着地上的虎精，忽然笑了："这虎吃过九世取经人，肉臭？那俺老猪今天，就替九世取经人，讨个公道！"他想起五百年前，天河的水军，也是这样被天庭视为异端，也是这样被天庭写死。他想起高老庄，高翠兰，也是这样等着他回来，也是这样被他辜负。他睁开眼，猪眼金光万道，看穿了虎精的本相——一只被城隍印困住的妖虎，是天庭的棋子，是灵山的工具，是写死的剧本。他一耙砸向虎精："城隍印？灵山莲花？那俺老猪今天，替你把这印砸了！"虎精在地上打滚，现出原形，是一只普通的老虎，不是妖虎。八戒看着它，忽然叹了口气："普通老虎？那俺老猪今天，放你一马。记住，以后别再拦取经人的路。"老虎爬起来，落荒而逃。八戒站在长安城外，看着老虎逃走的方向，忽然笑了："留着师父发落？那俺老猪今天，就留着师父发落。"他继续西行，九齿钉耙在肩上扛着，猪鼻一嗅一嗅，嗅着前方的路——那是取经路，是西行路，是他自己的路。' },
    6: { name: '双叉岭猎户', dark: '双叉岭前，刘伯钦拦路。他见八戒猪相，举叉便刺："妖怪！"八戒侧身躲过，猪鼻一嗅："猎户，你身上有虎腥味——杀过不少虎吧？"刘伯钦咬牙："九十九只！"八戒笑："那俺老猪，是第一百只——也是第一只，不杀你的。"他一耙压住钢叉，刘伯钦怔住，钢叉落在地上。' },
    7: { name: '双叉岭猪突', dark: '岭上魔影缠八戒。他猪牙一龇："俺老猪前世也是天将，你们算哪根葱？"双叉岭的魔影，是历代取经人的"不甘"，缠着八戒，要借他的身再走一遭。八戒猪牙一龇，一耙砸向魔影："俺老猪前世也是天将，你们算哪根葱？"魔影怔住——它们从没想过，八戒前世是天蓬元帅，是天庭的水军元帅。它们看着八戒的獠牙，忽然哭了："天蓬元帅，我们不想成佛，只想回家。"八戒怔住——他想起自己的家，想起高老庄，想起高翠兰，想起云栈洞，想起嫦娥。他一耙砸向天空："回家？俺老猪也想回家！可俺老猪的家，在哪？在高老庄？在云栈洞？在天河？还是在嫦娥的心里？"魔影在风中散去，留下一句话："天蓬元帅，你的家，在取经路上。"八戒站在岭上，忽然叹了口气："取经路？俺老猪今天，才真的上了取经路。可这路，走得真不容易。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一条路。"' },
    8: { name: '云栈受戒', dark: '观音点化八戒："你当和尚，但戒不了食欲。"八戒笑："那就把食欲变成力量。"他吞下自己的戒疤，化为双牙。福陵山的云栈洞，观音菩萨点化八戒，要他当和尚，随取经人西行。八戒摸着自己的肚子，忽然笑了："当和尚？俺老猪当和尚，但戒不了食欲。"观音菩萨笑了："戒不了食欲？那就把食欲变成力量。"八戒怔住——他从没想过，食欲可以变成力量。他看着自己的肚子，忽然明白了：他的食欲，不是罪，是力量。他吞下自己的戒疤，化为双牙，獠牙更长，更锋利。他一耙砸向洞壁："食欲变成力量？俺老猪今天，才真的成了和尚。可这和尚，当得真有意思。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一个肚子。肚子越大，力量越强。俺老猪今天，才真的懂了。"' },
    9: { name: '高老别妻', dark: '八戒告别山魈妻子。她把一枚山魈牙挂在他脖上："活着回来，或别回来。"高老庄的高翠兰，送八戒出门，随取经人西行。她把一枚山魈牙挂在他脖子上："活着回来，或别回来。"八戒怔住——他从没想过，高翠兰会这么说。他看着她的眼睛，忽然哭了："翠兰，俺老猪一定活着回来。俺老猪答应你，取完经，就回高老庄，就回来陪你。"高翠兰笑了："活着回来，或别回来。我不要你死在路上，我不要你成了佛，忘了我。你要么活着回来，要么别回来。"八戒跪在地上，泪流满面。他一耙砸向高老庄的大门："翠兰，俺老猪今天，才真的走了。可这走，走得真不容易。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一枚山魈牙。山魈牙在脖子上，翠兰在心里，取经路在脚下。俺老猪今天，才真的懂了。"' },
    10: { name: '猪鼻嗅虎', dark: '虎先锋拦路。八戒猪鼻一嗅："这虎吃过九世取经人，肉臭。"他一耙拍晕虎："留着师父发落。"黄风岭的虎先锋，横刀拦路，是黄风怪座下先锋。八戒猪鼻一嗅，嗅出虎先锋身上的味道——这虎吃过九世取经人，肉臭。他一耙拍晕虎先锋："留着师父发落。"虎先锋化作一阵风逃了——风里的黄风怪，正在岭上等他。八戒看着虎先锋逃走的方向，忽然笑了："跑了？跑了和尚跑不了庙。虎先锋，你跑得了初一，跑不了十五。俺老猪今天，先放你一马。等见了黄风怪，俺老猪再跟你算账。"他一耙砸向黄风岭的方向："黄风怪，你等着。俺老猪今天，就来会会你！"' },
    11: { name: '猪鼻拱风', dark: '黄风卷沙。八戒猪鼻一拱，把风拱开一道口子："风再大，也吹不动俺老猪的九齿钉耙。"黄风岭的黄风怪，吹起满山黄沙，遮天蔽日。八戒猪鼻一拱，把风拱开一道口子："风再大，也吹不动俺老猪的九齿钉耙。"他站在风中，九齿钉耙插在地上，纹丝不动。黄风怪在风眼中看着他，忽然怔住——它从没想过，有人能在三昧神风中纹丝不动。八戒看着风眼，忽然笑了："黄风怪，你吹的是风，不是沙。俺老猪的猪皮，比你的风还厚。你吹吧，吹累了，俺老猪再跟你算账。"他一耙砸向风眼："黄风怪，你等着。俺老猪今天，就来会会你！"' },
    12: { name: '猪皮挡风', dark: '三昧神风吹来。八戒猪皮一挡，风在猪皮上打了个旋："俺老猪皮糙，风咬不动。"黄风岭的三昧神风，迎面吹来，遮天蔽日。八戒猪皮一挡，风在猪皮上打了个旋，消散了。他站在风中，九齿钉耙插在地上，纹丝不动。黄风怪在风眼中看着他，忽然怔住——它从没想过，有人能在三昧神风中纹丝不动。八戒看着风眼，忽然笑了："黄风怪，你吹的是风，不是刀。俺老猪的猪皮，比你的风还厚。你吹吧，吹累了，俺老猪再跟你算账。"他一耙砸向风眼："黄风怪，你等着。俺老猪今天，就来会会你！三昧神风？俺老猪今天，才真的不怕风了。"' },
    13: { name: '猪牙镇风', dark: '黄风大圣吹起神风。八戒一耙砸地，风眼被震散："你吹你的风，俺老猪站得住。"黄风岭的黄风大圣，立在风眼，金目赤红，三昧神风从它口中喷出。八戒一耙砸地，风眼被震散，三昧神风戛然而止。他站在风中，九齿钉耙插在地上，纹丝不动。黄风大圣看着他，忽然怔住——它从没想过，有人能一耙震散三昧神风。八戒看着黄风大圣，忽然笑了："黄风大圣，你吹的是怨，不是风。俺老猪的猪牙，比你的怨还硬。你吹吧，吹累了，俺老猪再跟你算账。"他一耙砸向黄风大圣："黄风大圣，你等着。俺老猪今天，就来会会你！三昧神风？俺老猪今天，才真的不怕风了。风眼被震散，怨也该散了。"' },
    14: { name: '高老庄旧地', dark: '高老庄就在眼前。八戒停下脚步，猪鼻一嗅——庄里有山魈妻子的味道，也有老丈人的叹气。他摸了摸脖子上的山魈牙："俺老猪……回来了。"庄丁看见他，大喊："猪妖回来了！"八戒苦笑："俺老猪不是妖，是取经人——只是长得像妖。"' },
    15: { name: '云栈洞旧居', dark: '云栈洞还是老样子。八戒推开洞门，洞里还挂着嫦娥的画像——他被贬后仍在画。他伸手想摸，又缩回来："都过去了。"洞角堆着他当年偷来的供果，早已烂成泥。八戒坐在泥里，忽然想哭："俺老猪这一辈子，偷过供果，偷过心，就是没偷来过好日子。"' },
    16: { name: '高老重逢', dark: '高老丈人见八戒回来，举杖便打："你这猪妖，还敢回来！"八戒不躲，任拐杖打在背上："丈人，俺老猪错了。当年强占你女儿，是俺老猪不对。"高老丈人住手，叹气："你那山魈妻子……已经走了。"八戒怔住，猪鼻一酸："走了？去哪了？"高老丈人摇头："不知道。只留下一枚山魈牙，说等你回来给你。"' },
    17: { name: '高老送别', dark: '八戒接过山魈牙，挂在脖子上——和原来那枚并排。高老丈人送他出门，欲言又止。八戒回头："丈人，你有啥话说？"高老丈人叹气："那猪妖……虽能吃，却也护了我家庄园三年。"八戒笑："丈人，俺老猪以后护的是取经人，不是你家庄园了。等取完经，俺老猪回来看你——就是不知道，那时候你还认不认得俺老猪。"' },
    18: { name: '流沙收沙', dark: '流沙河沙僧拦路。八戒猪鼻一嗅："你颈上九颗，有一颗是俺老猪前世的仇？"沙僧摇头："是你师父的。"八戒一耙架住："那俺老猪今天，替你数着。"流沙河的水浊浪滔天，沙僧从水中跃出，颈挂九颗骷髅，拦住取经人的去路。八戒猪鼻一嗅，嗅出沙僧颈上九颗骷髅的味道——有一颗，是他前世的仇。他一耙架住沙僧的降妖宝杖："你颈上九颗，有一颗是俺老猪前世的仇？"沙僧摇头："是你师父的。"八戒怔住——他从没想过，沙僧颈上的九颗骷髅，是取经人的前世。他看着沙僧颈上的九颗骷髅，忽然叹了口气："是你师父的？那俺老猪今天，替你数着。别凑满十颗，凑满十颗，你师父就真的死了。"沙僧跪在地上，九颗骷髅同时发光——它们等这句话，等了九世。' },
    19: { name: '吞果变异', dark: '八戒偷吃两颗人参果。肚中果核发芽，从他喉咙长出藤蔓——他成了"人参猪"。五庄观的人参果树，三千年一开花，三千年一结果，三千年才得熟。八戒偷吃了两颗人参果，囫囵吞下，连核都没吐。肚中果核发芽，从他喉咙长出藤蔓——他成了"人参猪"。他看着自己喉咙里长出的藤蔓，忽然哭了："俺老猪吃了两个人参果，怎么就成了人参猪？"镇元子从殿中走出，叹道："八戒，你终于看见了。这人参果，养的不是仙，是取经人的命。你吃了它，它就长在你身上，成了你的一部分。"八戒跪在地上，泪流满面。他一耙砸向自己喉咙里的藤蔓："人参猪？俺老猪今天，才真的成了猪。可这猪，当得真没意思。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一根藤蔓。藤蔓在喉咙里，人参果在肚子里，取经路在脚下。俺老猪今天，才真的懂了。"' },
    20: { name: '猪鼻识骨', dark: '白骨精求死。八戒猪鼻嗅出她是九世取经人第一世骨："师父，你前世被俺…不，被妖吃了。"他闭嘴。白虎岭的白骨精，三次变化，三次被悟空打杀。第三次，白骨精没有逃，反而向取经人跪下："圣僧，求你超度我。"八戒猪鼻一嗅，嗅出白骨精的本相——她是九世取经人第一世的骨。他看着白骨精，忽然哭了："师父，你前世被俺…不，被妖吃了。"他闭嘴——他差点说漏嘴，他前世是天蓬元帅，不是妖。白骨精在经声中化烟散去，留下一句话："金蝉，你每世都念错经——因为经是写来骗你的。"八戒怔住——他从没想过，经是写来骗取经人的。他看着白骨精散去的方向，忽然叹了口气："经是写来骗你的？师父，你听见了吗？俺老猪今天，才真的懂了。取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。"' },
    21: { name: '高老梦回', dark: '八戒被逐回高老庄。山魈妻子已死，桌上留一碗猪食："你终究是猪。"三打白骨后，取经人贬悟空，八戒也被逐回高老庄。他回到高老庄，山魈妻子已死，桌上留一碗猪食："你终究是猪。"八戒看着那碗猪食，忽然哭了——他想起高翠兰的脸，想起山魈牙，想起云栈洞，想起嫦娥。他一耙砸向那碗猪食："俺老猪不是猪！俺老猪是天蓬元帅！是猪八戒！是取经人的二徒弟！"猪食洒了一地，他跪在地上，泪流满面。他看着高老庄的大门，忽然叹了口气："你终究是猪？翠兰，你说错了。俺老猪不是猪，俺老猪是天蓬元帅，是猪八戒，是取经人的二徒弟。可今天，俺老猪被逐了，被赶回高老庄了。俺老猪，终究还是猪。"' },
    22: { name: '天蓬遇狼', dark: '奎木狼是天庭二十八宿之一，认得八戒："天蓬，你当年调戏嫦娥，我就在旁边。"八戒的猪牙颤抖。宝象国的黄袍怪，原是天上的奎木狼，下凡为妖，把取经人掳进波月洞，变作一只猛虎。八戒从花果山请回悟空，一起去波月洞救取经人。奎木狼看见八戒，忽然笑了："天蓬，你当年调戏嫦娥，我就在旁边。"八戒的猪牙颤抖——他从没想过，奎木狼会在这个时候提起这件事。他看着奎木狼，忽然哭了："奎木狼，你说的对。俺老猪当年，不该酒后调戏嫦娥。俺老猪今天，成了猪，再也配不上嫦娥了。可俺老猪今天，是取经人的二徒弟，是天蓬元帅，是猪八戒。俺老猪今天，要救师父，要取经，要到灵山。"奎木狼怔住——他从没想过，八戒会这么说。他跪在地上，现出原形。天庭的使者从云中走出，把奎木狼带回天庭。八戒看着奎木狼的背影，忽然叹了口气："天蓬？俺老猪今天，才真的成了天蓬。可这天蓬，当得真不容易。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一个师父。师父在波月洞，取经路在脚下，灵山在前方。俺老猪今天，才真的懂了。"' },
    23: { name: '黑松林失', dark: '黑松林黑雾起，取经人被掳。八戒猪鼻一拱拱开雾："掳我师父？先问问俺老猪的耙子认不认路。"他追着猪鼻嗅出的脚印，一路拱进宝象国方向。' },
    24: { name: '猪鼻嗅宝', dark: '八戒的猪鼻嗅出金角银角的法宝是道具。他一口咬碎假葫芦："演戏演到俺老猪头上了？"平顶山的金角大王、银角大王，手持紫金红葫芦、羊脂玉净瓶，拦住取经人的去路。八戒猪鼻一嗅，嗅出法宝上的味道——是道具，是天庭的标记。他一口咬碎假葫芦："演戏演到俺老猪头上了？"金角银角怔住——他们从没想过，有人能一口咬碎紫金红葫芦。八戒看着他们，忽然笑了："金角银角，你们是太上老君看金炉、银炉的童子，奉旨下凡为妖，被收回天。你们演的是戏，俺老猪走的是取经路。你们演完了，该回天庭了。俺老猪走累了，该继续西行。"他一耙砸向金角银角："演戏演到俺老猪头上了？今天，俺老猪就替你们把戏，演完！"金角银角跪在地上，现出原形。太上老君从云中走出，把金角银角带回天庭。八戒看着太上老君的背影，忽然笑了："演戏？俺老猪今天，才真的懂了。取经之路，走的不是路，是戏。天庭演的是戏，妖怪演的是戏，取经人演的也是戏。可俺老猪，演的是真的。俺老猪是天蓬元帅，是猪八戒，是取经人的二徒弟。俺老猪今天，才真的懂了。"' },
    25: { name: '井底背尸', dark: '乌鸡国王托梦。八戒下井背尸，尸重如山："这国王，背着一国的冤。"乌鸡国的国王，被妖道推入井中，三年不得超生。他托梦给取经人，诉冤情，求他救自己。八戒下井背尸，尸重如山——那不是一个国王的尸身，是千万取经人叠成的"国"。八戒背着尸身，一步一步爬出井，忽然明白了：取经之路，背的不是经，是千万取经人的冤。他把尸身背出井，悟空用还魂丹救活国王。国王跪在他面前："天蓬元帅，你救的不是我，是乌鸡国。"八戒摇头："不，俺老猪救的，是取经人。"他看着国王的眼睛，看见了九世取经人的死。他忽然叹了口气："这国王，背着一国的冤。俺老猪，背着取经人的冤。咱们，都不轻。尸比活人轻，因为活人背着命。国王背着乌鸡国的命，俺老猪背着取经人的命。咱们，都不轻。"' },
    26: { name: '猪口吞龙', dark: '八戒一口吞下鼍龙。龙在肚子里喊："放我出来，我带你看我爹的坟。"黑水河的鼍龙，原是西海龙王的外甥，因逆被贬，在黑水河为妖，化舟渡取经人过河，却在江心掀翻船只，要吃取经人。八戒一口吞下鼍龙——龙在他肚子里喊："放我出来，我带你看我爹的坟。"八戒怔住——他从没想过，鼍龙的爹，已经死了。他看着自己的肚子，忽然哭了："鼍龙，你爹的坟？俺老猪带你去看。你爹因逆被贬，死在黑水河，连坟都没有。俺老猪今天，替你爹，立个坟。"他把鼍龙吐出来，鼍龙跪在地上，泪流满面。八戒一耙砸向黑水河的岸边："鼍龙，你爹的坟，就在这里。你爹因逆被贬，死在黑水河，连坟都没有。俺老猪今天，替你爹，立个坟。你要记住，逆不是罪，顺也不是德。你要做的，是自己的龙，不是天庭的狗。"鼍龙跪在地上，九片龙鳞同时发光——它们等这句话，等了千年。他泣道："天蓬元帅，你比龙像龙。"' },
    27: { name: '猪皮耐火', dark: '八戒的猪皮天然耐火。红孩儿烧不动他，反被八戒一口猪鼻喷出的泥水浇灭。号山枯松涧火云洞的红孩儿，手持火尖枪，口喷三昧真火，拦住取经人的去路。八戒的猪皮天然耐火——红孩儿烧不动他，反被八戒一口猪鼻喷出的泥水浇灭。他站在火中，九齿钉耙插在地上，纹丝不动。红孩儿看着他，忽然怔住——他从没想过，有人能在三昧真火中纹丝不动。八戒看着红孩儿，忽然笑了："红孩儿，你烧的是火，不是猪。俺老猪的猪皮，比你的火还厚。你烧吧，烧累了，俺老猪再跟你算账。"他一耙砸向红孩儿："红孩儿，你等着。俺老猪今天，就来会会你！三昧真火？俺老猪今天，才真的不怕火了。火在猪皮上打了个旋，泥水从猪鼻里喷出，火灭了，怨也该散了。红孩儿，你爹是牛魔王，你娘是铁扇公主，你是圣婴大王。可你今天，烧的是取经人，不是天庭。你要烧，就烧天庭，别烧取经人。"' },
    28: { name: '黑水猪拱', dark: '黑水河黑水滔滔，鼍龙化舟渡取经人过河。八戒猪鼻一嗅："这水里有龙腥味——还是西海旁支的龙。"他一头扎进水里，猪鼻拱开鼍龙的船："你敢害俺师父？俺老猪今天，拱你九个龙鳞！"鼍龙跪地求饶："天蓬元帅饶命！我也是被天庭逼的！"八戒收鼻："逼的？那俺老猪今天，教你怎么反逼回去。"' },
    29: { name: '车迟国前', dark: '车迟国国王崇道灭佛，和尚被赶去做苦役。八戒路过城门，见两个道士鞭打和尚。他猪鼻一嗅："这三个杂毛，身上有虎腥味、鹿腥味、羊腥味——是虎力、鹿力、羊力三妖。"他一耙砸开城门："三个杂毛，也敢在俺老猪面前装神弄鬼？"道士们吓得跪地求饶。八戒大笑："求雨？俺老猪一个喷嚏，就能下三天三夜的雨！"' },
    30: { name: '三清观戏', dark: '三清观中，虎力、鹿力、羊力三妖化作三清，受香火供奉。八戒夜探三清观，见供桌上的素斋——那是和尚们饿着肚子供的。他一口吞下供桌上的素斋："三个杂毛，也配受香火？俺老猪替你们受了！"三妖现原形，跪地求饶。八戒大笑："求雨？俺老猪一个喷嚏，就能下三天三夜的雨！你们求了半个时辰，滴雨未下，还有脸受香火？"' },
    31: { name: '高台求雨', dark: '车迟国高台求雨，虎力大仙登坛作法。八戒在台下合掌，默念《心经》。虎力求了半个时辰，滴雨未下。八戒登台，只打了一个喷嚏，天降甘霖。国王大惊："圣僧真神！"八戒大笑："不是神，是心诚。你们求雨，求的是自己的面子；俺老猪求雨，求的是百姓的活路。心不一样，雨自然不一样。"' },
    32: { name: '隔板猜物', dark: '车迟国隔板猜物，鹿力大仙与八戒比试。柜中放的是山河社稷袄，乾坤地理裙。八戒猪鼻一嗅，嗅出柜中之物——"山河社稷袄，乾坤地理裙。"国王大惊。八戒大笑："不是俺老猪能猜，是这世上的物，都在经里。你们猜物，猜的是自己的贪欲；俺老猪猜物，猜的是万物的本相。心不一样，猜的自然不一样。"' },
    33: { name: '云梯显圣', dark: '车迟国云梯显圣，羊力大仙与八戒比试坐禅。云梯高百丈，八戒合掌而上，心中默念《心经》。羊力在云端坐了三个时辰，终于撑不住落下。八戒仍在云端，合掌不语。国王叹："圣僧真乃活佛！"八戒睁眼："不是佛，是心定。你们坐禅，坐的是自己的面子；俺老猪坐禅，坐的是万物的本相。心不一样，坐的自然不一样。"' },
    34: { name: '车迟除妖', dark: '车迟国三妖现原形，虎力、鹿力、羊力跪地求饶。八戒一耙压住三妖："你们崇道灭佛，害了多少和尚？"三妖泣道："我们也是被天庭利用，求天蓬元帅饶命。"八戒收耙："饶命可以，但你们要替那些被你们害死的和尚，念经超度。"三妖叩首，含泪念经。八戒大笑："这才像话！以后再敢装神弄鬼，俺老猪一耙敲碎你们的狗头！"' },
    35: { name: '猪鼻辨伪', dark: '八戒的猪鼻嗅出假葫芦里有嫦娥的香味——是天庭的陷阱。他一口咬碎假葫芦。金兜山的青牛精，手持金刚琢，套尽万物，拦住取经人的去路。他用假葫芦骗取经人，要把取经人装进葫芦里。八戒猪鼻一嗅，嗅出假葫芦里有嫦娥的香味——是天庭的陷阱。他一口咬碎假葫芦："青牛精，你用假葫芦骗俺师父，可你骗不了俺老猪的猪鼻！这葫芦里有嫦娥的香味，是天庭的陷阱！"青牛精怔住——他从没想过，有人能嗅出假葫芦里的嫦娥香味。八戒看着青牛精，忽然笑了："青牛精，你是太上老君的坐骑，偷了金刚琢下凡。你可知罪？"青牛精泣道："我知罪。我只是想尝尝，不被人骑的滋味。"八戒收耙："不被人骑的滋味，不是偷来的，是挣来的。你跟俺老猪西行一路，便懂了。"青牛精叩首，含泪随老君回天宫。八戒看着青牛精的背影，忽然叹了口气："嫦娥？俺老猪今天，才真的懂了。嫦娥的香味，不是陷阱，是回忆。俺老猪当年，不该酒后调戏嫦娥。俺老猪今天，成了猪，再也配不上嫦娥了。可俺老猪今天，是取经人的二徒弟，是天蓬元帅，是猪八戒。俺老猪今天，要救师父，要取经，要到灵山。"' },
    36: { name: '金兜降牛', dark: '金兜山青牛精现原形，跪地求饶。八戒一耙压住青牛头："你是太上老君的坐骑，偷了金刚琢下凡。你可知罪？"青牛精泣道："我知罪。我只是想尝尝，不被人骑的滋味。"八戒收耙："不被人骑的滋味，不是偷来的，是挣来的。你跟俺老猪西行一路，便懂了。"青牛精叩首，含泪随老君回天宫。八戒大笑："这才像话！以后再敢偷东西，俺老猪一耙敲碎你的牛头！"' },
    37: { name: '猪鼻饮泉', dark: '八戒一口喝干落胎泉。真仙怒，八戒打嗝喷出泉水——水里映出嫦娥的脸。西梁女国的落胎泉，如意真仙守着，要取经人喝落胎泉的水，打掉腹中的胎气。八戒一口喝干落胎泉——真仙怒，要打八戒。八戒打嗝喷出泉水——水里映出嫦娥的脸。他看着水中嫦娥的脸，忽然哭了："嫦娥，俺老猪对不起你。俺老猪当年，不该酒后调戏你。俺老猪今天，成了猪，再也配不上你了。"如意真仙怔住——他从没想过，八戒会在这个时候哭。他看着八戒，忽然叹了口气："天蓬元帅，你终于，懂了。落胎泉的水，打掉的不是胎气，是执念。你打掉了对嫦娥的执念，就真的成了和尚。"八戒跪在地上，泪流满面。他一耙砸向落胎泉："嫦娥？俺老猪今天，才真的懂了。落胎泉的水，打掉的不是胎气，是执念。俺老猪打掉了对嫦娥的执念，就真的成了和尚。可这和尚，当得真不容易。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一个师父。师父在女儿国，取经路在脚下，灵山在前方。俺老猪今天，才真的懂了。"' },
    38: { name: '猪八戒娶亲', dark: '女王看上八戒的"憨厚"。八戒心动，但猪鼻里的嫦娥香味让他清醒："我配不上凡人。"西梁女国的女王，倾国倾城，愿以一国之富，招取经人为王，她为王后。取经人不敢见女王，八戒变作取经人的模样，与女王周旋。女王看上八戒的"憨厚"，要招他为王。八戒心动——他从没想过，女王会看上他。但猪鼻里的嫦娥香味让他清醒："我配不上凡人。"他看着女王的眼睛，忽然哭了："女王，俺老猪是猪，不是人。你是女王，是凡人。我们，不一样。俺老猪配不上你。"女王怔住——她从没想过，八戒会这么说。她看着八戒的眼睛，忽然笑了："天蓬元帅，你终于，懂了。我嫁的不是取经人，不是猪，不是天蓬元帅。我嫁的是你，是猪八戒，是你。可你说，你配不上凡人。那我问你，你配得上嫦娥吗？"八戒跪在地上，泪流满面。他一耙砸向女儿国的宫殿："嫦娥？俺老猪今天，才真的懂了。我配不上凡人，也配不上嫦娥。我配得上的，只有取经路，只有师父，只有灵山。俺老猪今天，才真的成了和尚。可这和尚，当得真不容易。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一个师父。师父在女儿国，取经路在脚下，灵山在前方。俺老猪今天，才真的懂了。"' },
    39: { name: '蝎子精刺', dark: '毒敌山琵琶洞蝎子精掳取经人入洞，欲逼成亲。八戒猪鼻一嗅，嗅出蝎子精本相——她的毒针，是如来佛祖的指甲。他一耙砸开琵琶洞："你这蝎子，偷了如来的指甲，也敢在俺老猪面前装神弄鬼？"蝎子精冷笑："偷来的指甲，也是指甲。你这猪，偷过嫦娥，还有脸说我？"八戒怔住——她说的，是实话。昴日星官收服蝎子精，八戒叹："偷来的东西，终究不是自己的。嫦娥，俺老猪对不起你。"' },
    40: { name: '猪鼻吸毒', dark: '八戒用猪鼻吸走蝎子精的毒针。毒在他体内翻腾，却成了助燃剂——"我是猪，毒不怕猪。"毒敌山琵琶洞的蝎子精，手持三股钢叉，尾后倒马毒桩，拦住取经人的去路。她一毒桩刺来，悟空伸手去挡，毒针刺中他的手掌，剧痛钻心。八戒用猪鼻吸走蝎子精的毒针——毒在他体内翻腾，却成了助燃剂。他看着蝎子精，忽然笑了："我是猪，毒不怕猪。你偷了如来的指甲，可偷得来如来的法？"蝎子精怔住，三股钢叉落在地上。昴日星官从云中走出，双翅一展，蝎子精现了原形。八戒看着蝎子精的尸体，忽然叹了口气："偷来的东西，终究不是自己的。蝎子精，对不住了。俺老猪当年，也对不起嫦娥。可俺老猪今天，是取经人的二徒弟，是天蓬元帅，是猪八戒。俺老猪今天，要救师父，要取经，要到灵山。毒在体内翻腾，却成了助燃剂。俺老猪今天，才真的不怕毒了。毒不怕猪，猪也不怕毒。俺老猪今天，才真的懂了。"' },
    41: { name: '火焰山前', dark: '火焰山烈焰冲天，八百里火焰，无春无秋，四季皆热。八戒猪鼻一嗅，嗅出火焰本相——这火，是当年孙悟空踢翻太上老君的炼丹炉，落下的火。他低头不语。取经人合掌："解铃还须系铃人。这火，还得俺老孙来灭。"悟空抬头："师父，俺老孙这就去借芭蕉扇！"他一个筋斗，翻向翠云山。八戒拍了拍肚子："这火，烤得俺老猪肚子都饿了。"' },
    42: { name: '三调芭蕉', dark: '孙悟空三调芭蕉扇，与牛魔王、铁扇公主斗法。八戒在一旁啃西瓜，心中却忐忑——这一战，关乎取经成败。悟空终于借到芭蕉扇，扇灭八百里火焰。取经人合掌："火灭了，可心里的火，何时能灭？"悟空笑："师父，到了灵山，心里的火，自然就灭了。"八戒打了个嗝："俺老猪心里的火，是饿火。到了灵山，先吃一顿再说。"众人继续西行。' },
    43: { name: '祭赛国前', dark: '祭赛国金光寺塔顶舍利被盗，国王震怒，将众僧下狱。八戒猪鼻一嗅："舍利？俺老猪闻着像供果的味儿——甜的。"他夜探金光寺，猪鼻拱开塔门，见塔顶留有妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"八戒拍了拍肚子："国亡不亡，不在舍利，在人心。俺老猪今天，替你们把舍利偷回来——不过俺老猪偷东西，从来先吃饱了再偷。"' },
    44: { name: '碧波潭探', dark: '碧波潭底，万圣龙宫灯火通明。九头虫把舍利当夜明珠，挂在龙女床头。八戒潜入潭底，看见龙女抱着舍利喃喃："偷来的光，也是光。"他一把抱住舍利就跑："九头虫，你九个头，俺老猪一个肚子——装得下。"九头虫追来，八戒一个猛子扎回岸上。他拍了拍肚子："舍利在俺老猪肚里，看你们谁先来拿。"' },
    45: { name: '真假八戒', dark: '六耳变八戒。真八戒猪鼻一嗅："你身上没猪味，假得慌。"花果山的六耳猕猴，化作悟空的模样，打昏取经人，抢走行李，要自己去取经。他还化作八戒的模样，要骗取经人。真八戒猪鼻一嗅，嗅出假八戒身上没有猪味——"你身上没猪味，假得慌。"假八戒怔住——他从没想过，有人能嗅出他没有猪味。他看着真八戒，忽然笑了："天蓬元帅，你终于，懂了。我不是八戒，我是六耳猕猴。我化作你的模样，是要骗取经人，要自己去取经。可你嗅出我没有猪味，就说明你真的成了猪，真的成了八戒，真的成了取经人的二徒弟。"真八戒跪在地上，泪流满面。他一耙砸向假八戒："六耳猕猴，你终于，懂了。俺老猪是猪，是八戒，是取经人的二徒弟。俺老猪身上有猪味，有八戒味，有取经人的味。你没有，你是假的。今天，俺老猪就替你，把假的，砸了！"假八戒在风中散去，留下一句话："天蓬元帅，你终于，成了真的八戒。"真八戒站在风中，忽然叹了口气："真的八戒？俺老猪今天，才真的成了八戒。可这八戒，当得真不容易。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一个师父。师父在取经路上，取经路在脚下，灵山在前方。俺老猪今天，才真的懂了。"' },
    46: { name: '猪鼻吸焰', dark: '八戒用猪鼻吸火焰山的火。火入鼻中化作九齿钉耙的新齿——"这火，归我了。"火焰山烈焰冲天，八百里火焰，无春无秋，四季皆热。八戒用猪鼻吸火焰山的火——火入鼻中，化作九齿钉耙的新齿。他看着自己的九齿钉耙，忽然笑了："这火，归我了。"铁扇公主怔住——她从没想过，有人能用猪鼻吸火焰山的火。她看着八戒，忽然叹了口气："天蓬元帅，你终于，懂了。火焰山的火，是孙悟空踢翻太上老君的炼丹炉落下的火。你用猪鼻吸了这火，火就成了你的力量，成了你的九齿钉耙的新齿。你终于，把食欲变成了力量，把火变成了齿，把罪变成了德。"八戒跪在地上，泪流满面。他一耙砸向火焰山："这火，归我了？铁扇公主，你说的对。俺老猪用猪鼻吸了火焰山的火，火就成了俺老猪的力量，成了九齿钉耙的新齿。俺老猪终于，把食欲变成了力量，把火变成了齿，把罪变成了德。可这力量，当得真不容易。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一个师父。师父在火焰山，取经路在脚下，灵山在前方。俺老猪今天，才真的懂了。"' },
    47: { name: '牛魔王战', dark: '牛魔王现出原形，一头大白牛，头如峻岭，眼若闪光。八戒一耙压住牛头："牛大哥，你与俺老孙是结拜兄弟，何必相煎太急？"牛魔王怒吼："结拜兄弟？他欺我妻子，辱我孩儿，还配叫兄弟？"八戒怔住——他说的，是实话。两妖大战三百回合，悟空终于降服牛魔王。八戒叹："情之一字，最难放下。牛大哥，对不住了。俺老猪当年，也对不起嫦娥。"' },
    48: { name: '罗刹女泪', dark: '铁扇公主交出芭蕉扇，泪流满面。八戒猪鼻一嗅，嗅出铁扇公主身上的桂花香味——那是嫦娥的味道。他低声："女菩萨，你与牛魔王的恩怨，到此为止吧。"铁扇公主泣道："天蓬元帅，我与牛魔王夫妻一场，如今他被降服，我活着还有什么意思？"八戒叹："活着，就是意思。你把芭蕉扇借给我们，扇灭火焰山，便是功德一件。"铁扇公主点头，含泪回翠云山。八戒收起芭蕉扇，继续西行，心中暗想："嫦娥，俺老猪何时能再见你一面？"' },
    49: { name: '火焰山过', dark: '孙悟空扇灭八百里火焰，火焰山从此四季如春。八戒收起芭蕉扇，大笑："师父，这火，是俺老孙当年踢翻炼丹炉落下的，如今俺老孙亲手灭了，也算因果报应。"取经人合掌："因果报应，丝毫不爽。我们西行取经，便是要了这因果。"众人继续西行。八戒回头望了一眼火焰山，心中暗想："俺老猪的因果，何时能了？嫦娥，俺老猪对不起你。"' },
    50: { name: '祭赛猪拱', dark: '祭赛国金光寺金光尽失。八戒猪鼻拱进寺里："舍利没了，和尚跪着。俺老猪闻得出——偷舍利的味道，是水下腥味。"他一头扎进碧波潭方向的水道。祭赛国金光寺塔顶舍利被盗，国王震怒，将满寺僧众下狱，严刑拷打。八戒猪鼻拱进寺里，见塔尖的舍利没了，塔底跪着和尚，一个个面黄肌瘦，伤痕累累。他猪鼻一嗅，嗅出偷舍利的味道——是水下腥味，是碧波潭的味道。他看着跪着的和尚，忽然叹了口气："舍利没了，和尚跪着。俺老猪闻得出——偷舍利的味道，是水下腥味。是碧波潭万圣龙王与九头虫干的。俺老猪今天，替你们把舍利偷回来——不过俺老猪偷东西，从来先吃饱了再偷。"他一头扎进碧波潭方向的水道，猪鼻拱开淤泥，一路拱向碧波潭。他在水中拱着，忽然想起高翠兰，想起山魈牙，想起云栈洞，想起嫦娥。他一耙砸向水中的淤泥："嫦娥？俺老猪今天，才真的懂了。偷舍利的味道，是水下腥味。偷心的味道，是嫦娥的香味。俺老猪今天，要偷舍利，要救和尚，要取经，要到灵山。可俺老猪最想偷的，是嫦娥的心。可俺老猪知道，真心，偷不来。"' },
    51: { name: '金光寺冤僧', dark: '金光寺舍利失窃，满寺僧众被冤下狱。八戒猪鼻拱进牢房，给和尚们送饭："舍利俺老猪替你们找。光不在塔尖，在你们心里——心里有光，牢里也是亮的。"' },
    52: { name: '盗宝遭擒', dark: '碧波潭夺舍利。八戒潜入潭底，看见九头虫把舍利当夜明珠。他一把抱住舍利就跑："九头虫，你九个头，俺老猪一个肚子——装得下。"九头虫追来，八戒一个猛子扎回岸上。' },
    53: { name: '万圣盗草', dark: '万圣公主盗九叶灵芝给九头虫续命。八戒在潭边啃灵芝叶："你偷草救他，他偷舍利哄你。这买卖，你亏大了。"公主怔住。八戒把灵芝塞回她手里："俺老猪贪，但俺老猪知道——真心，偷不来。"' },
    54: { name: '祭赛国厄', dark: '九头虫九头齐出。八戒一耙钩住它一颗头，另一颗头咬来，他猪牙一磕："九个脑袋抢一个舍利，你们比俺老猪还贪。"他把舍利塞进嘴里，咕咚吞下："舍利在俺老猪肚里，看你们谁先来拿。"' },
    55: { name: '木仙猪言', dark: '荆棘岭树精拉着八戒吟诗。八戒啃了一口树干："诗有啥用？能吃吗？"树精们愣了。八戒一抹嘴："能当饭吃的，才是好东西。你们这些木头，连自己是谁都忘了。"' },
    56: { name: '小雷音猪遁', dark: '小雷音假佛收香火。八戒一看假佛，猪鼻一哼："佛祖的脚，长着金莲。你这脚，长着泥。"他往地上一滚，钻进泥里："真佛在地下，不在殿上。"小雷音寺的黄眉老佛，化作如来佛祖的模样，坐在雷音寺的大殿上，受香火供奉。八戒走进大殿，看见"如来佛祖"端坐莲台，金光万道，瑞气千条。他猪鼻一哼，嗅出假佛的味道——"佛祖的脚，长着金莲。你这脚，长着泥。"他往地上一滚，钻进泥里："真佛在地下，不在殿上。"黄眉老佛怔住——他从没想过，有人能嗅出他的脚长着泥。他看着地上的洞，忽然笑了："天蓬元帅，你终于，懂了。真佛在地下，不在殿上。可你钻进泥里，就能找到真佛吗？"八戒在泥里拱着，忽然哭了："黄眉老佛，你说的对。真佛在地下，不在殿上。可俺老猪钻进泥里，也找不到真佛。俺老猪找的不是佛，是师父，是取经路，是灵山。可俺老猪最想找的，是嫦娥。可俺老猪知道，嫦娥，不在地下，不在殿上，在俺老猪的心里。"他一耙砸向泥里的黄眉老佛："黄眉老佛，你终于，懂了。真佛在地下，不在殿上。可你假佛坐殿，受香火供奉，害了多少和尚？今天，俺老猪就替你，把假佛，砸了！"黄眉老佛跪在地上，现出原形。弥勒佛从云中走出，把黄眉老佛带回天庭。八戒看着弥勒佛的背影，忽然笑了："真佛在地下，不在殿上？弥勒佛，你说的对。俺老猪今天，才真的懂了。真佛不在殿上，在难中。可俺老猪的难，不在小雷音寺，在高老庄，在云栈洞，在嫦娥的心里。俺老猪今天，才真的懂了。"' },
    57: { name: '朱紫国医', dark: '朱紫国王悬丝诊脉。八戒扯着猪鼻说："悬啥丝？俺老猪闻一闻就知道你心口疼。"他对着国王吹口气，"你的病，是想你的娘娘想的。"国王老泪纵横。' },
    58: { name: '狮驼猪撞', dark: '狮驼岭三魔食城。八戒扛耙撞城门："食城？先过俺这关。"狮驼岭的青毛狮子怪、黄牙老象怪、大鹏金翅雕，三魔联手，食尽狮驼国一城百姓，连骨头都没剩下。八戒扛耙撞城门，一耙砸开城门："食城？先过俺这关。"他站在城门口，九齿钉耙插在地上，纹丝不动。三魔看着他，忽然怔住——他们从没想过，有人敢一耙撞开狮驼国的城门。八戒看着三魔，忽然笑了："青毛狮子怪、黄牙老象怪、大鹏金翅雕，你们食尽一城，可食得来世？今天，俺老猪就替那些被你们食的人，讨个公道！"他一耙砸向三魔，三魔跪在地上，现出原形。如来佛祖从云中走出，把三魔带回灵山。八戒看着如来佛祖的背影，忽然叹了口气："食城？先过俺这关？如来佛祖，你说的对。狮驼岭三魔食城，可灵山食的，是千万城。俺老猪今天，才真的懂了。取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。俺老猪今天，才真的懂了。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一个师父。师父在狮驼国，取经路在脚下，灵山在前方。俺老猪今天，才真的懂了。"' },
    59: { name: '祭赛金光', dark: '祭赛国金光寺塔顶舍利被盗，国王震怒，将众僧下狱。八戒猪鼻一嗅："舍利？俺老猪闻着像供果的味儿——甜的。"他夜探金光寺，猪鼻拱开塔门，见塔顶留有妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"八戒拍了拍肚子："国亡不亡，不在舍利，在人心。俺老猪今天，替你们把舍利偷回来——不过俺老猪偷东西，从来先吃饱了再偷。"' },
    60: { name: '灭法剃王', dark: '灭法国要杀僧。八戒混进王宫，一夜把满朝文武的头发剃得精光，还用猪毛给他们粘了假胡子："让你们也尝尝当秃驴的滋味。"国王照镜子，愣了半天。灭法国的国王，前世是个和尚，被佛抛弃，转世为王，立志杀万名僧，以泄心头之恨。八戒混进王宫，一夜之间，把满朝文武的头发剃得精光，还用猪毛给他们粘了假胡子："让你们也尝尝当秃驴的滋味。"国王醒来，照着镜子，愣了半天——他的头发也被剃光了，头上还粘着猪毛做的假胡子。他看着镜子里的自己，忽然哭了："天蓬元帅，你终于，懂了。我杀了九千九百九十九个和尚，可我心里，还是个和尚。我杀的不是僧，是我自己。"八戒跪在地上，泪流满面。他一耙砸向灭法国的王宫："国王，你终于，懂了。灭法国，从此改名为钦法国。杀僧，不如度僧。度僧，不如度己。你杀了九千九百九十九个和尚，可你杀的不是僧，是你自己。今天，俺老猪替你，把假胡子，撕了！"国王叩首，灭法国从此改名为钦法国。八戒看着国王的背影，忽然笑了："杀僧？俺老猪今天，才真的度了一个僧。可这僧，当得真不容易。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一个师父。师父在灭法国，取经路在脚下，灵山在前方。俺老猪今天，才真的懂了。"' },
    61: { name: '隐雾梅花', dark: '隐雾山梅花计摄走取经人。八戒猪鼻嗅出梅花香里的豹子味："梅花是假的，骚气是真的。"他循着味儿，一耙把豹精从雾里拱了出来。隐雾山的艾叶花皮豹子精，用分瓣梅花计，化作取经人的模样，要骗取经人入洞。八戒猪鼻一嗅，嗅出梅花香里的豹子味——"梅花是假的，骚气是真的。"他循着味儿，一耙把豹精从雾里拱了出来。豹精怔住——他从没想过，有人能嗅出梅花香里的豹子味。他看着八戒，忽然哭了："天蓬元帅，你终于，懂了。我用分瓣梅花计，化作取经人的模样，要骗取经人入洞。可你嗅出梅花香里的豹子味，就说明你真的成了猪，真的成了八戒，真的成了取经人的二徒弟。"八戒跪在地上，泪流满面。他一耙砸向豹精："艾叶花皮豹子精，你终于，懂了。俺老猪是猪，是八戒，是取经人的二徒弟。俺老猪身上有猪味，有八戒味，有取经人的味。你没有，你是假的。今天，俺老猪就替你，把假的，砸了！"豹精在风中散去，留下一句话："天蓬元帅，你终于，成了真的八戒。"八戒站在风中，忽然叹了口气："真的八戒？俺老猪今天，才真的成了八戒。可这八戒，当得真不容易。没有嫦娥，没有天河，没有天蓬元帅，只有一头猪，一根耙，一个师父。师父在隐雾山，取经路在脚下，灵山在前方。俺老猪今天，才真的懂了。"' },
    62: { name: '凤仙求雨', dark: '凤仙郡大旱。八戒上天偷了玉帝的雨葫芦，临了又放回去，只抓了一把云："俺老猪不偷雨——偷雨是偷百姓的命。俺老猪替他们求，求不来就自己下。"他把云揉碎了，撒回凤仙郡。' },
    63: { name: '玉华传耙', dark: '玉华州三王子拜师。八戒教耙法："成佛捷径？俺的耙就是捷径。"他示范一耙："记住了，耙要往肉里刨，不是往土里刨。"三王子学得满头大汗。' },
    64: { name: '竹节山斗', dark: '竹节山九灵元圣九头齐咬。八戒一耙挡住："九个脑袋，也咬不穿俺老猪一张皮。"他边挡边喊："你主人骑你，你咬我们。冤有头债有主，回去咬你主人！"' },
    65: { name: '金平府灯', dark: '金平府三头犀牛假冒佛收灯油。八戒猪鼻一嗅："灯油是百姓熬的，你们连油都偷。"他一把抱住油缸，咕咚喝干："油，俺老猪替你存着——存进肚子里，看你还偷啥。"' },
    66: { name: '给孤园厄', dark: '给孤园天竺公主招亲。八戒乐颠颠要去应招，猪鼻一嗅："公主身上有月宫桂花的味儿。"他打了个寒战："是玉兔精！俺老猪被嫦娥坑过一次，不上第二次当了。"' },
    67: { name: '铜台府案', dark: '铜台府寇员外被害，取经人被诬为盗。八戒挨了板子，捂着屁股嘟囔："俺老猪这辈子挨的板子，一半为吃，一半为师父。"他爬起来，一耙砸开牢门："走，师父，咱不背这个锅。"' },
    68: { name: '天竺国前', dark: '天竺国国都，繁华似锦。八戒猪鼻一嗅，嗅出公主本相——玉兔精假扮。他打了个寒战："是玉兔精！俺老猪被嫦娥坑过一次，不上第二次当了。"取经人叹："真假难辨，正如取经之路。我们西行取经，取的不是经，是自己的心。"八戒一耙砸开宫殿："你这玉兔，偷了嫦娥的灵药，也敢在俺老猪面前装神弄鬼？"玉兔精冷笑："偷来的灵药，也是灵药。你这猪，偷过嫦娥，还有脸说我？"八戒怔住——她说的，是实话。' },
    69: { name: '玉兔精现', dark: '天竺国公主抛绣球招亲，取经人被砸中。公主笑："取经人，你取的是经，还是自己？"取经人合十——这一问，比八十一难都重。八戒猪鼻一嗅，嗅出公主本相——玉兔精假扮。他一耙砸开宫殿："你这玉兔，偷了嫦娥的灵药，也敢在俺老猪面前装神弄鬼？"玉兔精冷笑："偷来的灵药，也是灵药。你这猪，偷过嫦娥，还有脸说我？"八戒怔住——她说的，是实话。嫦娥收服玉兔精，八戒叹："偷来的东西，终究不是自己的。嫦娥，俺老猪对不起你。"' },
    70: { name: '铜台府案', dark: '铜台府寇员外斋僧被害，取经人被诬为盗。八戒挨了板子，捂着屁股嘟囔："俺老猪这辈子挨的板子，一半为吃，一半为师父。"他爬起来，一耙砸开牢门："走，师父，咱不背这个锅。"取经人合掌："八戒，委屈你了。"八戒笑："师父，不委屈。俺老猪的命，都是师父给的。"众人继续西行。' },
    71: { name: '灵山前望', dark: '灵山在望，金光万道。八戒猪鼻一嗅，嗅出灵山的味道——那是供果的味道，甜的。他笑："师父，到了灵山，我们就能取经了。"取经人叹："取经之路，九九八十一难，我们都走过来了。最后一难，又算得了什么？"八戒回头望了一眼来时的路，心中暗想："取经之路，取的不是经，是自己的心。如今到了灵山，心，又在哪里？"他摸了摸脖子上的山魈牙，忽然觉得这牙，比九齿钉耙还重。' },
    72: { name: '凌云渡前', dark: '凌云渡前，弱水滔滔。接引佛祖撑船而来："取经人，上船吧。"取经人上船，船行至江心，忽然翻了——取经人落水，却见水中有一具死尸。八戒也跳下水，却见水中也有一具死尸——那是他自己。他怔住——过了凌云渡，他就不再是他了。他摸了摸脖子上的山魈牙，忽然觉得这牙，比九齿钉耙还重。他抬头望了一眼天空，心中暗想："嫦娥，俺老猪何时能再见你一面？"' },
    73: { name: '化电归真', dark: '雷音门前，八戒看着自己肚里的雷光："俺老猪偷了一辈子食，今天把雷电也吞了。"他打了个嗝，雷电在云层里炸开："这电，俺老猪还给你们——照亮回家的路。"' },
    74: { name: '雷音寺前', dark: '雷音寺前，金光万道。八戒猪鼻一嗅，嗅出雷音寺的味道——那是供果的味道，甜的。他笑："师父，到了雷音寺，我们就能取经了。"取经人叹："取经之路，九九八十一难，我们都走过来了。最后一难，又算得了什么？"八戒回头望了一眼来时的路，心中暗想："取经之路，取的不是经，是自己的心。如今到了雷音寺，心，又在哪里？"他摸了摸脖子上的山魈牙，忽然觉得这牙，比九齿钉耙还重。' },
    75: { name: '如来佛祖', dark: '如来佛祖端坐莲台，金光万道。取经人合掌："弟子玄奘，奉东土大唐皇帝旨意，前来拜佛求经。"如来佛祖笑："玄奘，你取经十世，到底取的是什么？"取经人怔住——这一问，比八十一难都重。八戒也怔住——他忽然明白，取经之路，取的不是经，是自己的心。如来佛祖点头："善哉善哉。你终于明白了。"八戒摸了摸脖子上的山魈牙，忽然觉得这牙，比九齿钉耙还重。' },
    76: { name: '问佛根源', dark: '八戒上灵山问佛："佛啊，俺老猪取完经，能回高老庄吗？"佛不答。八戒一屁股坐下："你不答，俺老猪就当答应了。"他掏出山魈牙，在佛前晃了晃："俺老猪答应过她，活着回去。"' },
    77: { name: '灵山成正果', dark: '灵山册封，八戒被封净坛使者。他拎起净坛的盘子掂了掂："使者？俺老猪看是剩饭的。"他一笑，"行，剩饭也行——总比饿着强。师父，俺老猪想高老庄了。"' },
    78: { name: '取经回东', dark: '取经人取到真经，辞别如来，回东土大唐。八戒笑："师父，我们终于取经成功了。"取经人叹："取经之路，九九八十一难，我们都走过来了。如今取经成功，却不知该喜还是该悲。"八戒回头望了一眼灵山，心中暗想："取经之路，取的不是经，是自己的心。如今经取到了，心，又在哪里？"他摸了摸脖子上的山魈牙，忽然觉得这牙，比九齿钉耙还重。' },
    79: { name: '通天河遇', dark: '通天河前，弱水滔滔。老鼋游来："取经人，上船吧。"取经人上船，船行至江心，老鼋忽然问："取经人，我当年托你问如来佛祖，我何时能脱壳成人，你问了吗？"取经人怔住——他忘了。老鼋大怒，将船掀翻，众人落水，真经也被水浸湿。八戒也落水，却见水中也有一具死尸——那是他自己。他怔住——过了凌云渡，他就不再是他了。他摸了摸脖子上的山魈牙，忽然觉得这牙，比九齿钉耙还重。' },
    80: { name: '真经晒干', dark: '众人落水，真经被水浸湿。八戒笑："师父，我们把真经晒干就是了。"众人将真经摊在石头上晒干，却发现最后一页被石头粘住，撕坏了一角。取经人叹："真经不全，如何是好？"八戒笑："师父，真经不全，正如人生不全。不全，才是真。"取经人点头："善哉善哉。不全，才是真。"八戒摸了摸脖子上的山魈牙，忽然觉得这牙，比九齿钉耙还重。他抬头望了一眼天空，心中暗想："嫦娥，俺老猪对不起你。"' },
    81: { name: '无字碑终', intro: '自沉："他碎了钉耙，也碎了食欲。猪，从此是人。"\n隐藏「天蓬归来」：天蓬残影替渡，真八戒回高老。' },
  },
  shaseng: {
    1: { options: [
      { key: '顺命', label: '〔顺命〕接受流沙赎罪', fate: '渡', effect: { good: 6 } },
      { key: '逆命', label: '〔逆命〕拒绝食取经人，自沉流沙', fate: '逆', effect: { evil: 4 } },
    ] },
    2: { name: '碎琉璃盏', dark: '卷帘大将失手打碎琉璃盏，玉帝罚他每七日万箭穿心。第九次时他笑了："箭比禅好懂。"凌霄宝殿的卷帘大将，失手打碎了琉璃盏，玉帝大怒，罚他每七日万箭穿心，贬下凡间，在流沙河为妖。他在流沙河底，每七日受一次万箭穿心之苦，箭箭穿心，痛不欲生。第九次时，他忽然笑了："箭比禅好懂。"他看着自己身上的箭伤，忽然明白了：箭是实的，禅是虚的；箭能穿心，禅不能；箭能让人痛，禅不能。他在流沙河底，数着自己身上的箭伤，忽然哭了："卷帘大将？俺沙僧今天，才真的成了妖。可这妖，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅。骷髅在脖子上，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    3: { name: '流沙吞月', dark: '沙僧在流沙河底发现一弯"沉月"。月中有吴刚的斧声——他被罚的不只是穿心，是永不见月。流沙河的水浊浪滔天，沙僧在河底，发现一弯"沉月"——那是天上的月亮，沉在了流沙河底。月中有吴刚的斧声，一下一下，砍着桂花树。他看着那弯沉月，忽然哭了："吴刚，你被罚的不只是砍树，是永不见月。俺沙僧被罚的不只是穿心，是永不见天。咱们，都是一样的人。"他伸手摸了摸那弯沉月，月亮在他手中碎了，化作无数光点，融入他的体内。他站在流沙河底，感受着体内的月光，忽然笑了："沉月？俺沙僧今天，才真的见了月。可这月，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一弯沉月。沉月在体内，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    4: { name: '九世食师', dark: '流沙河底，沙僧数着颈上骷髅——九颗，九世取经人。第十世正在岸上走过。流沙河的水浊浪滔天，沙僧在河底，数着颈上的骷髅——九颗，九世取经人。每一颗骷髅，都有一个故事，都有一段取经路，都有一个未完成的心愿。他看着岸上走过的第十世取经人，忽然哭了："九世取经人，都死在了俺沙僧的手里。第十世，正在岸上走过。俺沙僧今天，是继续吃，还是放他过去？"他伸手摸了摸颈上的九颗骷髅，骷髅们齐齐发声："卷帘大将，你食了我们九世，第十世，你要护他。"沙僧怔住——他从没想过，骷髅们会这么说。他看着岸上的第十世取经人，忽然笑了："九世食师？俺沙僧今天，才真的懂了。九世的债，这一世，一起还。第十世，俺沙僧护你。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在岸上，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    5: { name: '骷髅伏虎', dark: '长安城外虎精扑来。沙僧骷髅串一甩，虎伏："你颈上九颗，有一颗是我的前世仇。"虎逃。长安城外，虎精扑来，张牙舞爪，要吃取经人。沙僧骷髅串一甩，九颗骷髅齐齐发声，虎精伏在地上："你颈上九颗，有一颗是我的前世仇。"虎逃，化作一阵风逃了——风里的黄风怪，正在岭上等他。沙僧看着虎精逃走的方向，忽然笑了："跑了？跑了和尚跑不了庙。虎精，你跑得了初一，跑不了十五。俺沙僧今天，先放你一马。等见了黄风怪，俺沙僧再跟你算账。"他想起五百年前，凌霄宝殿的卷帘大将，也是这样被天庭视为异端，也是这样被天庭写死。他想起流沙河，九世取经人，也是这样被他吃了，也是这样被他辜负。他睁开眼，骷髅串在脖子上发光，九颗骷髅齐齐发声，看穿了虎精的本相——一只被城隍印困住的妖虎，是天庭的棋子，是灵山的工具，是写死的剧本。他骷髅串一甩，九颗骷髅齐齐发声："黄风怪，你等着。俺沙僧今天，就来会会你！"他站在长安城外，骷髅串在脖子上发光，九颗骷髅齐齐发声，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。九世的债，这一世，一起还。' },
    6: { name: '双叉岭猎户', dark: '双叉岭前，刘伯钦拦路。他见沙僧骷髅串，举叉便刺："妖怪！"沙僧侧身躲过，骷髅串一甩，九颗骷髅齐齐发声："猎户，你杀过多少妖？"刘伯钦咬牙："九十九只！"骷髅们笑："那我们，是第一百只——也是第一只，不杀你的。"沙僧收串，刘伯钦怔住，钢叉落在地上。' },
    7: { name: '双叉岭骷髅', dark: '岭上魔影围沙僧。他摘下一颗骷髅："你们也是被食的？那我们同类。"魔影泣散。双叉岭的魔影，是历代取经人的"不甘"，围着沙僧，要借他的身再走一遭。沙僧摘下一颗骷髅，放在手心："你们也是被食的？那我们同类。"魔影怔住——它们从没想过，沙僧会这么说。它们看着沙僧手心的骷髅，忽然哭了："卷帘大将，我们也是被食的，被妖怪食的，被天庭食的，被命运食的。我们和你，是同类。"沙僧看着魔影，忽然笑了："同类？那我们一起，把这取经路，走完。九世的债，这一世，一起还。"魔影在风中泣散，留下一句话："卷帘大将，你终于，懂了。取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。"沙僧站在岭上，忽然叹了口气："同类？俺沙僧今天，才真的懂了。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在岸上，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    8: { name: '流沙受洗', dark: '观音在流沙河点化沙僧："你食九世取经人，第十世你要护。"沙僧把骷髅串扔进河："我护的不是他，是不再食师的自己。"流沙河的水浊浪滔天，观音菩萨在流沙河点化沙僧："你食九世取经人，第十世你要护。"沙僧看着观音菩萨，忽然哭了："观音菩萨，俺沙僧食了九世取经人，罪大恶极。第十世，俺沙僧一定护他。"他把骷髅串扔进河里："我护的不是他，是不再食师的自己。"骷髅串在河里沉了下去，又浮了上来，九颗骷髅齐齐发声："卷帘大将，你终于，懂了。九世的债，这一世，一起还。第十世，我们护你。"沙僧怔住——他从没想过，骷髅们会这么说。他看着河里的骷髅串，忽然笑了："流沙受洗？俺沙僧今天，才真的受了洗。可这洗，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在岸上，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    9: { name: '弃骷髅', dark: '沙僧把九颗骷髅扔进流沙河。第九颗浮上来，对他笑："第十世，别让他死。"流沙河的水浊浪滔天，沙僧把九颗骷髅扔进流沙河，要和过去告别。八颗骷髅沉了下去，第九颗浮了上来，对他笑："第十世，别让他死。"沙僧怔住——他从没想过，第九颗骷髅会这么说。他看着第九颗骷髅，忽然哭了："第九世，是俺沙僧食的最后一个取经人。他临死前，对俺沙僧笑了笑，说：第十世，别让他死。俺沙僧今天，才真的懂了。"他伸手捞起第九颗骷髅，挂回脖子上："第九世，俺沙僧记着你。第十世，俺沙僧一定护他，不让他死。九世的债，这一世，一起还。"第九颗骷髅在他脖子上发光，笑了："卷帘大将，你终于，懂了。"沙僧站在流沙河底，忽然叹了口气："弃骷髅？俺沙僧今天，才真的弃了骷髅。可这弃，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在岸上，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    10: { name: '骷髅示警', dark: '虎先锋拦路。沙僧骷髅串一甩，虎伏："你颈上九颗，有一颗是我的前世仇。"虎逃。黄风岭的虎先锋，横刀拦路，是黄风怪座下先锋。沙僧骷髅串一甩，九颗骷髅齐齐发声，虎先锋伏在地上："你颈上九颗，有一颗是我的前世仇。"虎逃，化作一阵风逃了——风里的黄风怪，正在岭上等他。沙僧看着虎先锋逃走的方向，忽然笑了："跑了？跑了和尚跑不了庙。虎先锋，你跑得了初一，跑不了十五。俺沙僧今天，先放你一马。等见了黄风怪，俺沙僧再跟你算账。"他骷髅串一甩，九颗骷髅齐齐发声："黄风怪，你等着。俺沙僧今天，就来会会你！"他站在黄风岭的入口，骷髅串在脖子上发光，九颗骷髅齐齐发声，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。九世的债，这一世，一起还。' },
    11: { name: '骷髅挡风', dark: '黄风卷沙。沙僧骷髅串挡在风前，风把骷髅吹得哗哗响："我们生前，也被风这样吹过。"黄风岭的黄风怪，吹起满山黄沙，遮天蔽日。沙僧骷髅串挡在风前，风把骷髅吹得哗哗响："我们生前，也被风这样吹过。"他站在风中，骷髅串挡在身前，纹丝不动。黄风怪在风眼中看着他，忽然怔住——它从没想过，有人能用骷髅串挡住三昧神风。沙僧看着风眼，忽然笑了："黄风怪，你吹的是风，不是沙。俺沙僧的骷髅串，比你的风还硬。你吹吧，吹累了，俺沙僧再跟你算账。"他骷髅串一甩，九颗骷髅齐齐发声："黄风怪，你等着。俺沙僧今天，就来会会你！三昧神风？俺沙僧今天，才真的不怕风了。风在骷髅串上打了个旋，消散了。怨也该散了。"' },
    12: { name: '骷髅吸风', dark: '三昧神风吹来。沙僧骷髅串张开，把风吸进骷髅："风里有怨，怨归我们。"黄风岭的三昧神风，迎面吹来，遮天蔽日。沙僧骷髅串张开，把风吸进骷髅："风里有怨，怨归我们。"他站在风中，骷髅串吸着三昧神风，九颗骷髅齐齐发光。黄风怪在风眼中看着他，忽然怔住——它从没想过，有人能用骷髅串吸走三昧神风。沙僧看着风眼，忽然笑了："黄风怪，你吹的是怨，不是风。俺沙僧的骷髅串，比你的怨还深。你吹吧，吹累了，俺沙僧再跟你算账。"他骷髅串一甩，九颗骷髅齐齐发声："黄风怪，你等着。俺沙僧今天，就来会会你！三昧神风？俺沙僧今天，才真的不怕风了。风被骷髅串吸走了，怨也被骷髅串吸走了。九世的债，这一世，一起还。"' },
    13: { name: '骷髅镇风', dark: '黄风大圣吹起神风。沙僧把骷髅串抛向风眼，九颗骷髅镇住风："风再大，也吹不散九世的债。"黄风岭的黄风大圣，立在风眼，金目赤红，三昧神风从它口中喷出。沙僧把骷髅串抛向风眼，九颗骷髅镇住风："风再大，也吹不散九世的债。"他站在风中，骷髅串镇住风眼，九颗骷髅齐齐发光。黄风大圣看着他，忽然怔住——它从没想过，有人能用骷髅串镇住三昧神风。沙僧看着黄风大圣，忽然笑了："黄风大圣，你吹的是怨，不是风。俺沙僧的骷髅串，比你的怨还深。你吹吧，吹累了，俺沙僧再跟你算账。"他骷髅串一甩，九颗骷髅齐齐发声："黄风大圣，你等着。俺沙僧今天，就来会会你！三昧神风？俺沙僧今天，才真的不怕风了。风被骷髅串镇住了，怨也被骷髅串镇住了。九世的债，这一世，一起还。"' },
    14: { name: '高老庄闻妖', dark: '高老庄庄主哭诉女儿被妖强占。沙僧骷髅串一甩，九颗骷髅齐齐发声："那妖……我们认得。前世，他是天蓬元帅。"庄主怔住。沙僧合掌："施主，他强占你女，是恶；但他护你庄园三年，是善。善恶本无界，只在一念间。"' },
    15: { name: '云栈洞探', dark: '云栈洞中，沙僧见猪八戒正对着镜子梳妆。他看见沙僧，不慌不忙："和尚，你是来降我的？"沙僧摇头："我是来问你，为何强占高家小姐。"猪八戒低下头："我前世是天蓬元帅，因情被贬。我以为，强占便是爱。"沙僧骷髅串发光："爱不是占有，是成全。我们九世取经人，都曾以为占有便是爱——结果，都死了。"' },
    16: { name: '八戒归降', dark: '猪八戒跪在取经人面前，痛哭流涕。沙僧在一旁沉默，骷髅串忽然发光——九颗骷髅里，有一颗是天蓬元帅的旧部。那颗骷髅开口："天蓬，你终于肯认错了。"猪八戒怔住，泪流满面："是我……是我对不起你们。"沙僧合掌："知错能改，善莫大焉。九世的债，这一世，一起还。"' },
    17: { name: '高老送别', dark: '高老庄庄主送众人出门，欲言又止。沙僧看出他心思："施主，你是舍不得那猪妖？"庄主叹气："那猪妖……虽能吃，却也护了我家庄园三年。"沙僧骷髅串一甩，九颗骷髅齐齐发声："护庄园三年，是善；强占民女，是恶。善恶分明，不必纠结。他护你庄园，你便祝他西行顺利；他强占你女，他已认错。往事如烟，不必再提。"庄主点头，目送众人西行。' },
    18: { name: '流沙收沙', dark: '流沙河浊浪翻涌。你项挂九颅跪在渡口，向取经人叩首："小僧，你若渡我上岸，我便不吃第十世。"流沙河的水浊浪滔天，沙僧项挂九颗骷髅，跪在渡口，向取经人叩首："小僧，你若渡我上岸，我便不吃第十世。"取经人看着他，忽然哭了："卷帘大将，你食了九世取经人，罪大恶极。第十世，你要护我？"沙僧叩首："小僧，俺沙僧食了九世取经人，罪大恶极。第十世，俺沙僧一定护你，不让你死。九世的债，这一世，一起还。"取经人合掌："卷帘大将，你终于，懂了。取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。"沙僧站起身，骷髅串在脖子上发光，九颗骷髅齐齐发声："卷帘大将，你终于，懂了。第十世，我们护你。"他站在流沙河的渡口，骷髅串在脖子上发光，九颗骷髅齐齐发声，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。九世的债，这一世，一起还。' },
    19: { name: '骷髅种树', dark: '沙僧把骷髅埋在人参果树下。树根吸了骷髅，结出的果不再是孩童脸，是笑脸。五庄观的人参果树，三千年一开花，三千年一结果，三千年才得熟。沙僧把骷髅埋在人参果树下，树根吸了骷髅，结出的果不再是孩童脸，是笑脸。他看着树上的笑脸人参果，忽然哭了："九世取经人，都死在了俺沙僧的手里。今天，俺沙僧把你们埋在人参果树下，让你们的骷髅，化作人参果的笑脸。九世的债，这一世，一起还。"镇元子从殿中走出，叹道："卷帘大将，你终于，懂了。这人参果，养的不是仙，是取经人的命。你把骷髅埋在树下，让它们化作笑脸，就是让它们，终于，笑了。"沙僧跪在地上，泪流满面。他一耙砸向人参果树的树根："九世取经人，俺沙僧今天，才真的懂了。人参果的笑脸，是你们的笑脸。九世的债，这一世，一起还。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在岸上，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    20: { name: '骷髅认亲', dark: '白骨精遇到沙僧，跪下："师父。"她是沙僧食过的第一世取经人的残骸。白虎岭的白骨精，三次变化，三次被悟空打杀。第三次，白骨精没有逃，反而向沙僧跪下："师父。"沙僧怔住——他从没想过，白骨精会叫他师父。他看着白骨精，忽然哭了："你是……你是俺沙僧食过的第一世取经人的残骸？"白骨精点头："师父，我是你食过的第一世取经人的残骸。我等了你九世，等你叫我一声师父。"沙僧跪在地上，泪流满面："第一世，是俺沙僧食的第一个取经人。他临死前，对俺沙僧笑了笑，说：卷帘大将，你终于，懂了。俺沙僧今天，才真的懂了。"白骨精在经声中化烟散去，留下一句话："师父，九世的债，这一世，一起还。"沙僧站在风中，忽然叹了口气："骷髅认亲？俺沙僧今天，才真的认了亲。可这认，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在岸上，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    21: { name: '流沙独行', dark: '沙僧被逐回流沙河。九颗骷髅对他说："你一个人，背不动取经人。"三打白骨后，取经人贬悟空，沙僧也被逐回流沙河。他回到流沙河，九颗骷髅对他说："你一个人，背不动取经人。"沙僧看着九颗骷髅，忽然哭了："九世取经人，都死在了俺沙僧的手里。第十世，俺沙僧想护他，可俺沙僧被逐了。俺沙僧一个人，背不动取经人。"九颗骷髅齐齐发声："卷帘大将，你终于，懂了。你一个人，背不动取经人。可你不是一个人，你有我们，有九世取经人，有第十世取经人。九世的债，这一世，一起还。"沙僧怔住——他从没想过，骷髅们会这么说。他看着九颗骷髅，忽然笑了："流沙独行？俺沙僧今天，才真的懂了。俺沙僧不是一个人，俺沙僧有九颗骷髅，有九世取经人，有第十世取经人。九世的债，这一世，一起还。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在岸上，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    22: { name: '卷帘斗狼', dark: '沙僧的骷髅串对奎木狼发光——九颗骷髅里有一颗是狼妖。沙僧笑了："你也有今天。"宝象国的黄袍怪，原是天上的奎木狼，下凡为妖，把取经人掳进波月洞，变作一只猛虎。沙僧从花果山请回悟空，一起去波月洞救取经人。沙僧的骷髅串对奎木狼发光——九颗骷髅里有一颗是狼妖。沙僧笑了："你也有今天。"奎木狼怔住——他从没想过，沙僧的骷髅串里，有一颗是狼妖。他看着沙僧，忽然哭了："卷帘大将，你终于，懂了。我是奎木狼，是天庭二十八宿之一。我下凡为妖，是为了情，不是为了恶。可我害了取经人，害了宝象国，害了很多人。我知罪。"沙僧跪在地上，泪流满面："奎木狼，你终于，懂了。情之一字，最难放下。可你为了情，害了很多人，这就是恶。九世的债，这一世，一起还。"奎木狼跪在地上，现出原形。天庭的使者从云中走出，把奎木狼带回天庭。沙僧看着奎木狼的背影，忽然笑了："卷帘斗狼？俺沙僧今天，才真的斗了狼。可这斗，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在波月洞，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    23: { name: '黑松林失', dark: '黑松林黑雾起，取经人被掳。沙僧骷髅串在雾里排成一列，为他指路："我们记着每一世被掳的路，这一世，跟牢了。"黑松林的黑雾起，遮天蔽日，取经人被掳，不知去向。沙僧骷髅串在雾里排成一列，为他指路："我们记着每一世被掳的路，这一世，跟牢了。"他看着雾里的骷髅串，忽然哭了："九世取经人，都死在了俺沙僧的手里。每一世，都被掳过，都被妖吃过，都死在了取经路上。这一世，俺沙僧一定护他，不让他死。九世的债，这一世，一起还。"他骷髅串一甩，十一颗骷髅齐齐发声，为他指路，穿过黑雾，找到取经人被掳的方向——那是碗子山波月洞的方向，是黄袍怪的方向，是奎木狼的方向。他站在黑松林的雾里，骷髅串在脖子上发光，十一颗骷髅齐齐发声，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。九世的债，这一世，一起还。他循着骷髅串的指引，穿过黑雾，向碗子山波月洞走去，去救取经人，去讨公道，去还九世的债。' },
    24: { name: '骷髅装妖', dark: '沙僧把金角银角装进自己的骷髅串。两颗新骷髅挂在胸前，比经书还亮。平顶山的金角大王、银角大王，手持紫金红葫芦、羊脂玉净瓶，拦住取经人的去路。沙僧把金角银角装进自己的骷髅串，两颗新骷髅挂在胸前，比经书还亮。他看着胸前的两颗新骷髅，忽然笑了："金角银角，你们是太上老君看金炉、银炉的童子，奉旨下凡为妖，被收回天。你们演的是戏，俺沙僧走的是取经路。你们演完了，该回天庭了。俺沙僧走累了，该继续西行。"他骷髅串一甩，十一颗骷髅齐齐发声："金角银角，你们终于，懂了。演戏演到俺沙僧头上了？今天，俺沙僧就替你们把戏，演完！"金角银角在骷髅串里跪着，现出原形。太上老君从云中走出，把金角银角带回天庭。沙僧看着太上老君的背影，忽然笑了："骷髅装妖？俺沙僧今天，才真的装了妖。可这装，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，十一颗骷髅，一个取经人。取经人在平顶山，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    25: { name: '流沙背尸', dark: '乌鸡国王托梦。沙僧下井背尸，骷髅串发光指引："尸比活人轻。"乌鸡国的国王，被妖道推入井中，三年不得超生。他托梦给取经人，诉冤情，求他救自己。沙僧下井背尸，骷髅串发光指引："尸比活人轻。"他背着尸身，一步一步爬出井，忽然明白了：取经之路，背的不是经，是千万取经人的冤。他把尸身背出井，悟空用还魂丹救活国王。国王跪在他面前："卷帘大将，你救的不是我，是乌鸡国。"沙僧摇头："不，俺沙僧救的，是取经人。"他看着国王的眼睛，看见了九世取经人的死。他忽然叹了口气："尸比活人轻，因为活人背着命。国王背着乌鸡国的命，俺沙僧背着取经人的命。咱们，都不轻。九世的债，这一世，一起还。"他站在乌鸡国的井边，骷髅串在脖子上发光，十一颗骷髅齐齐发声，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。九世的债，这一世，一起还。' },
    26: { name: '骷髅钓龙', dark: '沙僧用骷髅做饵钓鼍龙。鼍龙上钩："你这和尚，比龙还狠。"黑水河的鼍龙，原是西海龙王的外甥，因逆被贬，在黑水河为妖，化舟渡取经人过河，却在江心掀翻船只，要吃取经人。沙僧用骷髅做饵钓鼍龙，鼍龙上钩："你这和尚，比龙还狠。"他看着鼍龙，忽然笑了："鼍龙，你因逆被贬，可你知道吗？俺沙僧也因逆被贬。俺沙僧打碎了琉璃盏，被罚每七日万箭穿心，贬下凡间，在流沙河为妖。咱们，都是一样的人。"鼍龙怔住——他从没想过，沙僧也因逆被贬。他看着沙僧，忽然哭了："卷帘大将，你终于，懂了。逆不是罪，顺也不是德。你要做的，是自己的龙，不是天庭的狗。"沙僧跪在地上，泪流满面："鼍龙，你终于，懂了。九世的债，这一世，一起还。"他把鼍龙放回黑水河，鼍龙跪在水中，九片龙鳞同时发光——它们等这句话，等了千年。他泣道："卷帘大将，你比龙像龙。"沙僧站在黑水河的岸边，骷髅串在脖子上发光，十一颗骷髅齐齐发声，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。九世的债，这一世，一起还。' },
    27: { name: '骷髅饮火', dark: '沙僧的骷髅串吸收三昧真火。每颗骷髅都笑了——它们生前就被火烧过。号山枯松涧火云洞的红孩儿，手持火尖枪，口喷三昧真火，拦住取经人的去路。沙僧的骷髅串吸收三昧真火，每颗骷髅都笑了——它们生前就被火烧过。他站在火中，骷髅串吸着三昧真火，十一颗骷髅齐齐发光。红孩儿看着他，忽然怔住——他从没想过，有人能用骷髅串吸收三昧真火。沙僧看着红孩儿，忽然笑了："红孩儿，你烧的是火，不是猪。俺沙僧的骷髅串，比你的火还深。你烧吧，烧累了，俺沙僧再跟你算账。"他骷髅串一甩，十一颗骷髅齐齐发声："红孩儿，你等着。俺沙僧今天，就来会会你！三昧真火？俺沙僧今天，才真的不怕火了。火被骷髅串吸走了，怨也被骷髅串吸走了。九世的债，这一世，一起还。"红孩儿跪在地上，现出原形。观音菩萨从云中走出，把红孩儿带走。沙僧看着观音菩萨的背影，忽然笑了："骷髅饮火？俺沙僧今天，才真的饮了火。可这饮，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，十一颗骷髅，一个取经人。取经人在火云洞，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    28: { name: '黑水骷髅', dark: '黑水河黑水滔滔，鼍龙化舟渡取经人过河。沙僧骷髅串一甩，九颗骷髅齐齐发声："这水里有龙腥味——还是西海旁支的龙。"他用骷髅做饵，钓出鼍龙："你敢害俺师父？俺沙僧今天，用你第九颗龙鳞，凑满十颗！"鼍龙跪地求饶："卷帘大将饶命！我也是被天庭逼的！"沙僧收串："逼的？那俺沙僧今天，教你怎么反逼回去。"' },
    29: { name: '车迟国前', dark: '车迟国国王崇道灭佛，和尚被赶去做苦役。沙僧路过城门，见两个道士鞭打和尚。他骷髅串一甩，九颗骷髅齐齐发声："这三个杂毛，身上有虎腥味、鹿腥味、羊腥味——是虎力、鹿力、羊力三妖。"他用降妖宝杖砸开城门："三个杂毛，也敢在俺沙僧面前装神弄鬼？"道士们吓得跪地求饶。沙僧合掌："求雨？俺沙僧的骷髅串，能求三天三夜的雨！"' },
    30: { name: '三清观戏', dark: '三清观中，虎力、鹿力、羊力三妖化作三清，受香火供奉。沙僧夜探三清观，见供桌上的素斋——那是和尚们饿着肚子供的。他骷髅串一甩，九颗骷髅齐齐发声："三个杂毛，也配受香火？"三妖现原形，跪地求饶。沙僧合掌："求雨？俺沙僧的骷髅串，能求三天三夜的雨！你们求了半个时辰，滴雨未下，还有脸受香火？"' },
    31: { name: '高台求雨', dark: '车迟国高台求雨，虎力大仙登坛作法。沙僧在台下合掌，默念《心经》。虎力求了半个时辰，滴雨未下。沙僧登台，骷髅串一甩，天降甘霖。国王大惊："圣僧真神！"沙僧合掌："不是神，是心诚。你们求雨，求的是自己的面子；俺沙僧求雨，求的是百姓的活路。心不一样，雨自然不一样。"' },
    32: { name: '隔板猜物', dark: '车迟国隔板猜物，鹿力大仙与沙僧比试。柜中放的是山河社稷袄，乾坤地理裙。沙僧骷髅串一甩，九颗骷髅齐齐发声，嗅出柜中之物——"山河社稷袄，乾坤地理裙。"国王大惊。沙僧合掌："不是俺沙僧能猜，是这世上的物，都在经里。你们猜物，猜的是自己的贪欲；俺沙僧猜物，猜的是万物的本相。心不一样，猜的自然不一样。"' },
    33: { name: '云梯显圣', dark: '车迟国云梯显圣，羊力大仙与沙僧比试坐禅。云梯高百丈，沙僧合掌而上，心中默念《心经》。羊力在云端坐了三个时辰，终于撑不住落下。沙僧仍在云端，合掌不语。国王叹："圣僧真乃活佛！"沙僧睁眼："不是佛，是心定。你们坐禅，坐的是自己的面子；俺沙僧坐禅，坐的是万物的本相。心不一样，坐的自然不一样。"' },
    34: { name: '车迟除妖', dark: '车迟国三妖现原形，虎力、鹿力、羊力跪地求饶。沙僧降妖宝杖一压，压住三妖："你们崇道灭佛，害了多少和尚？"三妖泣道："我们也是被天庭利用，求卷帘大将饶命。"沙僧收杖："饶命可以，但你们要替那些被你们害死的和尚，念经超度。"三妖叩首，含泪念经。沙僧合掌："这才像话！以后再敢装神弄鬼，俺沙僧的骷髅串，凑满十颗！"' },
    35: { name: '骷髅指路', dark: '沙僧的骷髅串指向真葫芦。每颗骷髅都曾被葫芦装过——它们记得出口。金兜山的青牛精，手持金刚琢，套尽万物，拦住取经人的去路。他用假葫芦骗取经人，要把取经人装进葫芦里。沙僧的骷髅串指向真葫芦，每颗骷髅都曾被葫芦装过——它们记得出口。他看着骷髅串指向的方向，忽然笑了："青牛精，你用假葫芦骗俺师父，可你骗不了俺沙僧的骷髅串。每颗骷髅都曾被葫芦装过，它们记得出口。"青牛精怔住——他从没想过，有人能用骷髅串找到真葫芦。他看着沙僧，忽然哭了："卷帘大将，你终于，懂了。我是太上老君的坐骑，偷了金刚琢下凡。我知罪。我只是想尝尝，不被人骑的滋味。"沙僧跪在地上，泪流满面："青牛精，你终于，懂了。不被人骑的滋味，不是偷来的，是挣来的。你跟俺沙僧西行一路，便懂了。九世的债，这一世，一起还。"青牛精叩首，含泪随老君回天宫。沙僧看着青牛精的背影，忽然笑了："骷髅指路？俺沙僧今天，才真的指了路。可这指，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，十一颗骷髅，一个取经人。取经人在金兜山，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    36: { name: '金兜降牛', dark: '金兜山青牛精现原形，跪地求饶。沙僧降妖宝杖一压，压住青牛头："你是太上老君的坐骑，偷了金刚琢下凡。你可知罪？"青牛精泣道："我知罪。我只是想尝尝，不被人骑的滋味。"沙僧收杖："不被人骑的滋味，不是偷来的，是挣来的。你跟俺沙僧西行一路，便懂了。"青牛精叩首，含泪随老君回天宫。沙僧合掌："这才像话！以后再敢偷东西，俺沙僧的骷髅串，凑满十颗！"' },
    37: { name: '骷髅盛泉', dark: '沙僧用骷髅装落胎泉。泉水在骷髅眼里沸腾——"这泉洗的是罪，不是胎。"西梁女国的落胎泉，如意真仙守着，要取经人喝落胎泉的水，打掉腹中的胎气。沙僧用骷髅装落胎泉，泉水在骷髅眼里沸腾——"这泉洗的是罪，不是胎。"他看着骷髅眼里沸腾的泉水，忽然哭了："九世取经人，都死在了俺沙僧的手里。这泉洗的不是胎，是罪，是俺沙僧食了九世取经人的罪。"如意真仙怔住——他从没想过，沙僧会这么说。他看着沙僧，忽然叹了口气："卷帘大将，你终于，懂了。落胎泉的水，打掉的不是胎气，是执念。你打掉了对九世取经人的执念，就真的成了和尚。"沙僧跪在地上，泪流满面："如意真仙，你终于，懂了。九世的债，这一世，一起还。"他把骷髅里的落胎泉喝了，泉水在他体内沸腾，洗去了他的罪。他站在落胎泉边，骷髅串在脖子上发光，十一颗骷髅齐齐发声，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。九世的债，这一世，一起还。' },
    38: { name: '骷髅照镜', dark: '女儿国中沙僧的骷髅串发出警告。每颗骷髅都曾被女儿国的女王爱上——这是轮回。西梁女国的女王，倾国倾城，愿以一国之富，招取经人为王，她为王后。沙僧的骷髅串发出警告，每颗骷髅都曾被女儿国的女王爱上——这是轮回。他看着骷髅串发出的警告，忽然哭了："九世取经人，都死在了俺沙僧的手里。每颗骷髅都曾被女儿国的女王爱上，这是轮回，是九世的轮回。"女王怔住——她从没想过，沙僧的骷髅串里，有九世的轮回。她看着沙僧，忽然叹了口气："卷帘大将，你终于，懂了。女儿国的女王，爱上的不是取经人，是自己的执念。你打掉了对九世取经人的执念，就真的成了和尚。"沙僧跪在地上，泪流满面："女王，你终于，懂了。九世的债，这一世，一起还。"他看着女王的眼睛，忽然笑了："女王，俺沙僧是妖，不是人。你是女王，是凡人。我们，不一样。俺沙僧配不上你。"女王怔住——她从没想过，沙僧会这么说。她看着沙僧的眼睛，忽然笑了："卷帘大将，你终于，懂了。我嫁的不是取经人，不是妖，不是天蓬元帅。我嫁的是你，是卷帘大将，是你。可你说，你配不上凡人。那我问你，你配得上九世取经人吗？"沙僧跪在地上，泪流满面。他一耙砸向女儿国的宫殿："九世取经人？俺沙僧今天，才真的懂了。我配不上凡人，也配不上九世取经人。我配得上的，只有取经路，只有师父，只有灵山。俺沙僧今天，才真的成了和尚。可这和尚，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，十一颗骷髅，一个取经人。取经人在女儿国，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    39: { name: '蝎子精刺', dark: '毒敌山琵琶洞蝎子精掳取经人入洞，欲逼成亲。沙僧骷髅串一甩，九颗骷髅齐齐发声，嗅出蝎子精本相——她的毒针，是如来佛祖的指甲。他用降妖宝杖砸开琵琶洞："你这蝎子，偷了如来的指甲，也敢在俺沙僧面前装神弄鬼？"蝎子精冷笑："偷来的指甲，也是指甲。你这和尚，食过九世取经人，还有脸说我？"沙僧怔住——她说的，是实话。昴日星官收服蝎子精，沙僧叹："偷来的东西，终究不是自己的。九世的债，这一世，一起还。"' },
    40: { name: '骷髅挡针', dark: '沙僧用骷髅挡蝎子精的毒针。骷髅碎了，但毒被吸收了——"我们替师父挡过箭，也挡过针。"毒敌山琵琶洞的蝎子精，手持三股钢叉，尾后倒马毒桩，拦住取经人的去路。她一毒桩刺来，悟空伸手去挡，毒针刺中他的手掌，剧痛钻心。沙僧用骷髅挡蝎子精的毒针，骷髅碎了，但毒被吸收了——"我们替师父挡过箭，也挡过针。"他看着碎了的骷髅，忽然哭了："九世取经人，都死在了俺沙僧的手里。今天，俺沙僧用你们的骷髅，替师父挡了毒针。九世的债，这一世，一起还。"蝎子精怔住——她从没想过，沙僧会用骷髅挡毒针。她看着沙僧，忽然笑了："卷帘大将，你终于，懂了。我偷了如来的指甲，可偷得来如来的法？你用骷髅挡毒针，可挡得住九世的债？"沙僧跪在地上，泪流满面："蝎子精，你终于，懂了。偷来的东西，终究不是自己的。九世的债，这一世，一起还。"昴日星官从云中走出，双翅一展，蝎子精现了原形。沙僧看着蝎子精的尸体，忽然叹了口气："骷髅挡针？俺沙僧今天，才真的挡了针。可这挡，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，十颗骷髅，一个取经人。取经人在琵琶洞，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    41: { name: '火焰山前', dark: '火焰山烈焰冲天，八百里火焰，无春无秋，四季皆热。沙僧骷髅串一甩，九颗骷髅齐齐发声，嗅出火焰本相——这火，是当年孙悟空踢翻太上老君的炼丹炉，落下的火。他低头不语。取经人合掌："解铃还须系铃人。这火，还得俺老孙来灭。"悟空抬头："师父，俺老孙这就去借芭蕉扇！"他一个筋斗，翻向翠云山。沙僧合掌："这火，烤得俺沙僧的骷髅串都发烫了。"' },
    42: { name: '三调芭蕉', dark: '孙悟空三调芭蕉扇，与牛魔王、铁扇公主斗法。沙僧在一旁合掌念经，心中却忐忑——这一战，关乎取经成败。悟空终于借到芭蕉扇，扇灭八百里火焰。取经人合掌："火灭了，可心里的火，何时能灭？"悟空笑："师父，到了灵山，心里的火，自然就灭了。"沙僧叹："俺沙僧心里的火，是九世的罪火。到了灵山，不知能不能灭。"众人继续西行。' },
    43: { name: '祭赛国前', dark: '祭赛国金光寺塔顶舍利被盗，国王震怒，将众僧下狱。沙僧把骷髅串挂在塔尖，九颗骷髅在月光下泛着青光："舍利没了，还有我们守塔。"他夜探金光寺，骷髅串在塔顶排成一线，替他找到妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"沙僧合掌："舍利本在心中，不在塔上。但众生需要光，我便替他们把光找回来。九世的债，这一世，一起还。"' },
    44: { name: '碧波潭探', dark: '碧波潭底，万圣龙宫灯火通明。九头虫把舍利当夜明珠，挂在龙女床头。沙僧潜下潭底，骷髅串在水里排成一线，替他找到九头虫藏舍利的暗格。他抱起舍利，骷髅们挡住追兵："走！我们替你断后。"龙女抱着空床头喃喃："偷来的光，也是光。"沙僧回头："光，不是偷来的，是自己心里发出来的。"龙女怔住，舍利在他怀中发光。' },
    45: { name: '真假骷髅', dark: '六耳变沙僧。真沙僧骷髅串冷笑："你颈上挂的是假骷髅，俺的是真前世。"花果山的六耳猕猴，化作悟空的模样，打昏取经人，抢走行李，要自己去取经。他还化作沙僧的模样，要骗取经人。真沙僧骷髅串冷笑："你颈上挂的是假骷髅，俺的是真前世。"假沙僧怔住——他从没想过，有人能用骷髅串分辨真假。他看着真沙僧，忽然笑了："卷帘大将，你终于，懂了。我不是沙僧，我是六耳猕猴。我化作你的模样，是要骗取经人，要自己去取经。可你用骷髅串分辨真假，就说明你真的成了妖，真的成了沙僧，真的成了取经人的三徒弟。"真沙僧跪在地上，泪流满面："六耳猕猴，你终于，懂了。俺沙僧是妖，是沙僧，是取经人的三徒弟。俺沙僧脖子上有真骷髅，有九世取经人，有取经人的味。你没有，你是假的。今天，俺沙僧就替你，把假的，砸了！"假沙僧在风中散去，留下一句话："卷帘大将，你终于，成了真的沙僧。"真沙僧站在风中，忽然叹了口气："真的沙僧？俺沙僧今天，才真的成了沙僧。可这沙僧，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，十颗骷髅，一个取经人。取经人在花果山，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    46: { name: '骷髅镇焰', dark: '沙僧把骷髅埋在火焰山。骷髅吸了火，变成火骷髅——"我们也能烧。"火焰山烈焰冲天，八百里火焰，无春无秋，四季皆热。沙僧把骷髅埋在火焰山，骷髅吸了火，变成火骷髅——"我们也能烧。"他看着变成火骷髅的骷髅串，忽然哭了："九世取经人，都死在了俺沙僧的手里。今天，俺沙僧把你们埋在火焰山，让你们的骷髅，吸收三昧真火，变成火骷髅。九世的债，这一世，一起还。"铁扇公主怔住——她从没想过，沙僧会把骷髅埋在火焰山。她看着沙僧，忽然叹了口气："卷帘大将，你终于，懂了。火焰山的火，是孙悟空踢翻太上老君的炼丹炉落下的火。你把骷髅埋在火焰山，让它们吸收三昧真火，就是让它们，终于，烧了。"沙僧跪在地上，泪流满面："铁扇公主，你终于，懂了。九世的债，这一世，一起还。"他把变成火骷髅的骷髅串挂回脖子上，十颗火骷髅齐齐发光，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。九世的债，这一世，一起还。' },
    47: { name: '牛魔王战', dark: '牛魔王现出原形，一头大白牛，头如峻岭，眼若闪光。沙僧降妖宝杖一压，压住牛头："牛施主，你与悟空是结拜兄弟，何必相煎太急？"牛魔王怒吼："结拜兄弟？他欺我妻子，辱我孩儿，还配叫兄弟？"沙僧怔住——他说的，是实话。两妖大战三百回合，悟空终于降服牛魔王。沙僧叹："情之一字，最难放下。牛大哥，对不住了。九世的债，这一世，一起还。"' },
    48: { name: '罗刹女泪', dark: '铁扇公主交出芭蕉扇，泪流满面。沙僧骷髅串一甩，九颗骷髅齐齐发声，嗅出铁扇公主身上的桂花香味——那是嫦娥的味道。他低声："女菩萨，你与牛魔王的恩怨，到此为止吧。"铁扇公主泣道："卷帘大将，我与牛魔王夫妻一场，如今他被降服，我活着还有什么意思？"沙僧叹："活着，就是意思。你把芭蕉扇借给我们，扇灭火焰山，便是功德一件。"铁扇公主点头，含泪回翠云山。沙僧收起芭蕉扇，继续西行，心中暗想："九世的债，这一世，一起还。"' },
    49: { name: '火焰山过', dark: '孙悟空扇灭八百里火焰，火焰山从此四季如春。沙僧收起芭蕉扇，合掌："师父，这火，是俺老孙当年踢翻炼丹炉落下的，如今俺老孙亲手灭了，也算因果报应。"取经人合掌："因果报应，丝毫不爽。我们西行取经，便是要了这因果。"众人继续西行。沙僧回头望了一眼火焰山，心中暗想："俺沙僧的因果，何时能了？九世的债，这一世，一起还。"' },
    50: { name: '祭赛骷髅', dark: '祭赛国金光寺金光尽失。沙僧把骷髅串挂在塔尖，九颗骷髅在月光下泛着青光："舍利没了，还有我们守塔。"他朝碧波潭方向一指，"债，得去水下讨。"祭赛国金光寺塔顶舍利被盗，国王震怒，将满寺僧众下狱，严刑拷打。沙僧把骷髅串挂在塔尖，九颗骷髅在月光下泛着青光："舍利没了，还有我们守塔。"他看着塔底跪着的和尚，忽然哭了："九世取经人，都死在了俺沙僧的手里。今天，俺沙僧把你们的骷髅，挂在塔尖，替你们守塔。九世的债，这一世，一起还。"他朝碧波潭方向一指，"债，得去水下讨。"他夜探金光寺，骷髅串在塔顶排成一线，替他找到妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"沙僧合掌："舍利本在心中，不在塔上。但众生需要光，我便替他们把光找回来。九世的债，这一世，一起还。"他站在金光寺的塔尖，骷髅串在脖子上发光，九颗骷髅齐齐发声，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。九世的债，这一世，一起还。' },
    51: { name: '金光寺冤僧', dark: '金光寺舍利失窃，满寺僧众被冤下狱。沙僧把骷髅串留在寺中，九颗骷髅替受冤的和尚守夜："我们守过九世的光，今晚替你们守牢。"' },
    52: { name: '盗宝遭擒', dark: '碧波潭夺舍利。沙僧潜下潭底，骷髅串在水里排成一线，替他找到九头虫藏舍利的暗格。他抱起舍利，骷髅们挡住追兵："走！我们替你断后。"' },
    53: { name: '万圣盗草', dark: '万圣公主盗九叶灵芝给九头虫续命。沙僧骷髅串在水面上漂浮，骷髅们齐声说："偷来的命，养不活真心。"公主手一抖，灵芝落入水中，沙僧伸手接住，还给她："把真心还给他，比偷草有用。"' },
    54: { name: '祭赛国厄', dark: '九头虫九头齐出。沙僧骷髅串甩出，缠住它九颗头，九颗骷髅各叼一头："九个脑袋，九颗骨，正好。"九头虫翻腾，沙僧把舍利从它腹中扯出。' },
    55: { name: '木仙骷髅', dark: '荆棘岭树精吟诗。沙僧骷髅串在一旁，每颗骷髅都吐出一句更老的经文："我们比你们更会念——念了九世，还没念完。"树精们不寒而栗。' },
    56: { name: '小雷音骷髅', dark: '小雷音假佛坐殿。沙僧骷髅串在佛前散开，九颗骷髅对着假佛念起超度经："假佛，也配收超度？"假佛的金身裂开一道缝。小雷音寺的黄眉老佛，化作如来佛祖的模样，坐在雷音寺的大殿上，受香火供奉。沙僧骷髅串在佛前散开，九颗骷髅对着假佛念起超度经："假佛，也配收超度？"假佛的金身裂开一道缝。他看着裂开的金身，忽然笑了："黄眉老佛，你终于，懂了。真佛不在殿上，在难中。可你假佛坐殿，受香火供奉，害了多少和尚？今天，俺沙僧就替你，把假佛，砸了！"黄眉老佛怔住——他从没想过，沙僧会用骷髅串念超度经。他看着沙僧，忽然哭了："卷帘大将，你终于，懂了。我是弥勒佛的童子，偷了人种袋下凡。我知罪。我只是想尝尝，当佛的滋味。"沙僧跪在地上，泪流满面："黄眉老佛，你终于，懂了。当佛的滋味，不是偷来的，是修来的。你跟俺沙僧西行一路，便懂了。九世的债，这一世，一起还。"黄眉老佛叩首，含泪随弥勒佛回天庭。沙僧看着黄眉老佛的背影，忽然笑了："小雷音骷髅？俺沙僧今天，才真的念了超度经。可这念，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在小雷音寺，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    57: { name: '朱紫国医', dark: '朱紫国王悬丝诊脉。沙僧把骷髅串放在他枕下，国王听见九颗骷髅一起说："你的病，是忘了自己是谁。"国王惊醒，出了一身汗，病竟轻了。' },
    58: { name: '狮驼骷髅', dark: '狮驼岭三魔食城。沙僧撒骷髅成山："你们食城，我食你们的恐惧。"狮驼岭的青毛狮子怪、黄牙老象怪、大鹏金翅雕，三魔联手，食尽狮驼国一城百姓，连骨头都没剩下。沙僧撒骷髅成山，九颗骷髅化作九座骷髅山，挡住三魔的去路："你们食城，我食你们的恐惧。"三魔怔住——他们从没想过，有人能用骷髅成山。他们看着九座骷髅山，忽然哭了："卷帘大将，你终于，懂了。我们食城，食的是百姓的命。你食恐惧，食的是我们的罪。可你知道吗？我们食城，是因为我们也是被天庭食的。我们是天庭的坐骑，是天庭的棋子，是天庭的工具。我们食城，是为了反抗天庭，是为了自由，是为了自己。"沙僧跪在地上，泪流满面："三魔，你们终于，懂了。食城不是罪，反抗天庭也不是罪。可你们食了一城百姓，这就是罪。九世的债，这一世，一起还。"三魔跪在地上，现出原形。如来佛祖从云中走出，把三魔带回灵山。沙僧看着如来佛祖的背影，忽然笑了："狮驼骷髅？俺沙僧今天，才真的撒了骷髅成山。可这撒，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在狮驼国，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    59: { name: '祭赛金光', dark: '祭赛国金光寺塔顶舍利被盗，国王震怒，将众僧下狱。沙僧把骷髅串挂在塔尖，九颗骷髅在月光下泛着青光："舍利没了，还有我们守塔。"他夜探金光寺，骷髅串在塔顶排成一线，替他找到妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"沙僧合掌："舍利本在心中，不在塔上。但众生需要光，我便替他们把光找回来。九世的债，这一世，一起还。"' },
    60: { name: '灭法骷髅', dark: '灭法国要杀万名僧。沙僧把骷髅串摆成一道墙，挡在寺门前："要杀僧，先过这九世的骨。"国王看着骷髅墙，又看看沙僧的眼睛，放下了刀。灭法国的国王，前世是个和尚，被佛抛弃，转世为王，立志杀万名僧，以泄心头之恨。沙僧把骷髅串摆成一道墙，挡在寺门前："要杀僧，先过这九世的骨。"国王看着骷髅墙，又看看沙僧的眼睛，放下了刀。他看着沙僧，忽然哭了："卷帘大将，你终于，懂了。我杀了九千九百九十九个和尚，可我心里，还是个和尚。我杀的不是僧，是我自己。"沙僧跪在地上，泪流满面："国王，你终于，懂了。灭法国，从此改名为钦法国。杀僧，不如度僧。度僧，不如度己。你杀了九千九百九十九个和尚，可你杀的不是僧，是你自己。今天，俺沙僧替你，把骷髅墙，拆了！"国王叩首，灭法国从此改名为钦法国。沙僧看着国王的背影，忽然笑了："灭法骷髅？俺沙僧今天，才真的摆了骷髅墙。可这摆，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在灭法国，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    61: { name: '隐雾骷髅', dark: '隐雾山梅花计摄走取经人。沙僧骷髅串在雾里发亮，顺着取经人的气息排成一线："我们认得每一世你的味道。"他循着骷髅的光，从豹精洞里背出取经人。隐雾山的艾叶花皮豹子精，用分瓣梅花计，化作取经人的模样，要骗取经人入洞。沙僧骷髅串在雾里发亮，顺着取经人的气息排成一线："我们认得每一世你的味道。"他循着骷髅的光，从豹精洞里背出取经人。豹子精怔住——他从没想过，沙僧能用骷髅串找到取经人。他看着沙僧，忽然哭了："卷帘大将，你终于，懂了。我用分瓣梅花计，化作取经人的模样，要骗取经人入洞。可你用骷髅串找到取经人，就说明你真的成了妖，真的成了沙僧，真的成了取经人的三徒弟。"沙僧跪在地上，泪流满面："艾叶花皮豹子精，你终于，懂了。俺沙僧是妖，是沙僧，是取经人的三徒弟。俺沙僧脖子上有真骷髅，有九世取经人，有取经人的味。你没有，你是假的。今天，俺沙僧就替你，把假的，砸了！"豹子精在风中散去，留下一句话："卷帘大将，你终于，成了真的沙僧。"沙僧站在风中，忽然叹了口气："真的沙僧？俺沙僧今天，才真的成了沙僧。可这沙僧，当得真不容易。没有凌霄宝殿，没有琉璃盏，没有卷帘大将，只有一个妖，一条河，九颗骷髅，一个取经人。取经人在隐雾山，流沙河在脚下，凌霄宝殿在天上。俺沙僧今天，才真的懂了。"' },
    62: { name: '凤仙骷髅', dark: '凤仙郡三年不雨。沙僧把骷髅串挂在枯井边，骷髅们张开嘴接露水："我们替百姓接雨。"露水积了满串，他把水倒进凤仙郡的田里。' },
    63: { name: '玉华传枪', dark: '玉华州三王子拜师。沙僧用降妖宝杖教他们枪法："卷帘也能收徒了。"他舞动宝杖，杖影里闪过九颗骷髅："记住，兵器是死的，你的手是活的。"' },
    64: { name: '竹节山斗', dark: '竹节山九灵元圣九头齐咬。沙僧骷髅串甩出，九颗骷髅各咬住一颗狮头："九对九，谁也不吃亏。"九灵元圣甩不掉，嘶吼着退去。' },
    65: { name: '金平府灯', dark: '金平府三头犀牛偷灯油。沙僧骷髅串挂上灯柱，九颗骷髅把灯油吸得一滴不剩："油，我们替百姓存着。"他转身，把油全倒回灯碗。' },
    66: { name: '给孤园厄', dark: '给孤园天竺公主招亲。沙僧骷髅串在公主身上嗅到月宫桂花的味道——那是玉兔精。他低声提醒取经人："师父，公主是假。真的，在天上。"' },
    67: { name: '铜台府案', dark: '铜台府取经人被诬为盗。沙僧不辩解，只把骷髅串挂在牢门上，骷髅们替他说："我们食过九世，知道什么是真的冤。"官府连夜查案，冤情得雪。' },
    68: { name: '天竺国前', dark: '天竺国国都，繁华似锦。沙僧骷髅串一甩，九颗骷髅齐齐发声，嗅出公主本相——玉兔精假扮。他低声提醒取经人："师父，公主是假。真的，在天上。"取经人叹："真假难辨，正如取经之路。我们西行取经，取的不是经，是自己的心。"沙僧合掌："九世的债，这一世，一起还。"' },
    69: { name: '玉兔精现', dark: '天竺国公主抛绣球招亲，取经人被砸中。公主笑："取经人，你取的是经，还是自己？"取经人合十——这一问，比八十一难都重。沙僧骷髅串一甩，九颗骷髅齐齐发声，嗅出公主本相——玉兔精假扮。他低声提醒取经人："师父，公主是假。真的，在天上。"嫦娥收服玉兔精，沙僧叹："偷来的东西，终究不是自己的。九世的债，这一世，一起还。"' },
    70: { name: '铜台府案', dark: '铜台府寇员外斋僧被害，取经人被诬为盗。沙僧不辩解，只把骷髅串挂在牢门上，骷髅们替他说："我们食过九世，知道什么是真的冤。"官府连夜查案，冤情得雪。取经人合掌："沙僧，委屈你了。"沙僧合掌："师父，不委屈。九世的债，这一世，一起还。"众人继续西行。' },
    71: { name: '灵山前望', dark: '灵山在望，金光万道。沙僧骷髅串一甩，九颗骷髅齐齐发声，嗅出灵山的味道——那是超度的味道，苦的。他合掌："师父，到了灵山，我们就能取经了。"取经人叹："取经之路，九九八十一难，我们都走过来了。最后一难，又算得了什么？"沙僧回头望了一眼来时的路，心中暗想："取经之路，取的不是经，是自己的心。如今到了灵山，心，又在哪里？"他摸了摸颈间的骷髅串，忽然觉得这串，比降妖宝杖还重。' },
    72: { name: '凌云渡前', dark: '凌云渡前，弱水滔滔。接引佛祖撑船而来："取经人，上船吧。"取经人上船，船行至江心，忽然翻了——取经人落水，却见水中有一具死尸。沙僧也跳下水，却见水中也有一具死尸——那是他自己。他怔住——过了凌云渡，他就不再是他了。他摸了摸颈间的骷髅串，忽然觉得这串，比降妖宝杖还重。九颗骷髅在水中发光，替他说："九世的债，这一世，一起还。"' },
    73: { name: '化电归真', dark: '雷音门前，沙僧骷髅串被雷光照得通亮。九颗骷髅在雷光里化作细沙，散入风中："我们替你，把九世的风沙还了。"沙僧看着空荡荡的颈间，第一次没有低头。' },
    74: { name: '雷音寺前', dark: '雷音寺前，金光万道。沙僧骷髅串一甩，九颗骷髅齐齐发声，嗅出雷音寺的味道——那是超度的味道，苦的。他合掌："师父，到了雷音寺，我们就能取经了。"取经人叹："取经之路，九九八十一难，我们都走过来了。最后一难，又算得了什么？"沙僧回头望了一眼来时的路，心中暗想："取经之路，取的不是经，是自己的心。如今到了雷音寺，心，又在哪里？"他摸了摸颈间的骷髅串，忽然觉得这串，比降妖宝杖还重。' },
    75: { name: '如来佛祖', dark: '如来佛祖端坐莲台，金光万道。取经人合掌："弟子玄奘，奉东土大唐皇帝旨意，前来拜佛求经。"如来佛祖笑："玄奘，你取经十世，到底取的是什么？"取经人怔住——这一问，比八十一难都重。沙僧也怔住——他忽然明白，取经之路，取的不是经，是自己的心。如来佛祖点头："善哉善哉。你终于明白了。"沙僧摸了摸颈间的骷髅串，忽然觉得这串，比降妖宝杖还重。九颗骷髅在佛前发光，替他说："九世的债，这一世，一起还。"' },
    76: { name: '问佛骷髅', dark: '沙僧上灵山问佛："我食了九世取经人，为何还让我成佛？"佛不答。骷髅串替他答："因为他来问你，就是还没放下。"沙僧怔住，把骷髅串挂在佛前的树上："那这一世，我不背了。"' },
    77: { name: '灵山成正果', dark: '灵山册封，沙僧被封金身罗汉。他摸了摸颈间——那里空了。他低声说："九世的风沙，终于到了灵山。"他抬起头，第一次不再数罪。' },
    78: { name: '取经回东', dark: '取经人取到真经，辞别如来，回东土大唐。沙僧合掌："师父，我们终于取经成功了。"取经人叹："取经之路，九九八十一难，我们都走过来了。如今取经成功，却不知该喜还是该悲。"沙僧回头望了一眼灵山，心中暗想："取经之路，取的不是经，是自己的心。如今经取到了，心，又在哪里？"他摸了摸颈间——那里空了。九颗骷髅已经化作细沙，散入风中。他低声说："九世的风沙，终于到了灵山。"' },
    79: { name: '通天河遇', dark: '通天河前，弱水滔滔。老鼋游来："取经人，上船吧。"取经人上船，船行至江心，老鼋忽然问："取经人，我当年托你问如来佛祖，我何时能脱壳成人，你问了吗？"取经人怔住——他忘了。老鼋大怒，将船掀翻，众人落水，真经也被水浸湿。沙僧也落水，却见水中也有一具死尸——那是他自己。他怔住——过了凌云渡，他就不再是他了。他摸了摸颈间——那里空了。九颗骷髅已经化作细沙，散入风中。他低声说："九世的风沙，终于到了灵山。"' },
    80: { name: '真经晒干', dark: '众人落水，真经被水浸湿。沙僧合掌："师父，我们把真经晒干就是了。"众人将真经摊在石头上晒干，却发现最后一页被石头粘住，撕坏了一角。取经人叹："真经不全，如何是好？"沙僧合掌："师父，真经不全，正如人生不全。不全，才是真。"取经人点头："善哉善哉。不全，才是真。"沙僧摸了摸颈间——那里空了。九颗骷髅已经化作细沙，散入风中。他低声说："九世的风沙，终于到了灵山。"他抬头望了一眼天空，心中暗想："九世的债，这一世，终于还了。"' },
    81: { name: '无字碑终', intro: '自沉："他碎了骷髅，也碎了罪。流沙，从此是净土。"\n隐藏「卷帘归天」：卷帘影像替渡，真沙僧回天庭。' },
  },
  xiaobailong: {
    1: { options: [
      { key: '顺命', label: '〔顺命〕接受敖烈纵火被罚', fate: '渡', effect: { good: 6 } },
      { key: '逆命', label: '〔逆命〕拒绝化马，保留龙形', fate: '逆', effect: { evil: 4 } },
    ] },
    2: { name: '焚殿之罪', dark: '敖烈火烧殿上明珠，龙王上表天庭。他被吊在柱上三日，才知"龙子"不过是天庭的锁链。西海龙王三太子敖烈，因纵火烧了殿上明珠，被父王表奏天庭，告了忤逆。他被吊在柱上三日，受了三百锤，才知"龙子"不过是天庭的锁链。他看着自己身上的龙鳞，忽然哭了："龙子？俺白龙今天，才真的成了罪龙。可这罪，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个天庭。锁链在身上，西海在脚下，天庭在天上。俺白龙今天，才真的懂了。"观音菩萨路过，见他可怜，便向玉帝求情，免了他的死罪，贬他在鹰愁涧等待取经人，化作白马，驮他西行。他看着观音菩萨，忽然笑了："化作白马？俺白龙今天，才真的成了马。可这马，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在岸上，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    3: { name: '鹰愁涧困', dark: '小白龙被囚鹰愁涧。涧水倒流，他第一次知道"龙困于浅水"不是比喻。鹰愁涧的水浊浪滔天，小白龙被囚在涧底，涧水倒流，他第一次知道"龙困于浅水"不是比喻。他看着涧底的自己，忽然哭了："龙困于浅水？俺白龙今天，才真的懂了。龙困于浅水，不是比喻，是现实。俺白龙是西海龙王三太子，是龙，可现在，俺白龙被困在鹰愁涧，被困在浅水，被困在天庭的锁链里。"他伸手摸了摸自己的龙鳞，龙鳞已经褪了一半，露出下面的马皮。他忽然笑了："褪了龙鳞，露出马皮？俺白龙今天，才真的成了马。可这马，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在岸上，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"他在涧底等着，等着取经人，等着化作白马，等着驮他西行，等着有一天，能做回龙。' },
    4: { name: '索珠报仇', dark: '白龙寻回被偷的龙珠。盗珠人是他父亲西海龙王——"你的龙魂太烈，父王替你收着。"小白龙在鹰愁涧，寻回被偷的龙珠。盗珠人是他父亲西海龙王——"你的龙魂太烈，父王替你收着。"他看着父亲手中的龙珠，忽然哭了："父王，你偷了俺的龙珠，说是替俺收着。可你知道吗？没有龙珠，俺白龙就不是龙了，就是一条虫，就是一匹马，就是天庭的锁链。"西海龙王看着他，忽然叹了口气："敖烈，你终于，懂了。龙珠不是你的，是西海的，是天庭的，是龙族的锁链。你没有龙珠，就不是龙了，就自由了。"小白龙怔住——他从没想过，父亲会这么说。他看着父亲手中的龙珠，忽然笑了："没有龙珠，就自由了？父王，你说的对。俺白龙今天，才真的懂了。龙珠不是俺的，是西海的，是天庭的，是龙族的锁链。俺白龙没有龙珠，就不是龙了，就自由了。可这自由，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在岸上，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"他把龙珠还给父亲，转身跳进鹰愁涧，等着取经人，等着化作白马，等着驮他西行，等着有一天，能做回龙。' },
    5: { name: '龙涎伏虎', dark: '长安城外虎精扑来。白龙一口龙涎喷虎眼："这虎吃过九世取经人，龙族早想清它。"虎盲逃。长安城外，虎精扑来，张牙舞爪，要吃取经人。白龙一口龙涎喷虎眼："这虎吃过九世取经人，龙族早想清它。"虎盲逃，化作一阵风逃了——风里的黄风怪，正在岭上等他。白龙看着虎精逃走的方向，忽然笑了："跑了？跑了和尚跑不了庙。虎精，你跑得了初一，跑不了十五。俺白龙今天，先放你一马。等见了黄风怪，俺白龙再跟你算账。"他想起五百年前，西海的水军，也是这样被天庭视为异端，也是这样被天庭写死。他想起鹰愁涧，五百年的风吹雨打，不仅没压垮他，反而炼出了不屈的意志。他睁开眼，龙鳞金光万道，看穿了虎精的本相——一只被城隍印困住的妖虎，是天庭的棋子，是灵山的工具，是写死的剧本。他一声龙吟，震碎了虎精身上的城隍印："城隍印？灵山莲花？那俺白龙今天，替你把这印砸了！"虎精在地上打滚，现出原形，是一只普通的老虎，不是妖虎。白龙看着它，忽然叹了口气："普通老虎？那俺白龙今天，放你一马。记住，以后别再拦取经人的路。"老虎爬起来，落荒而逃。白龙站在长安城外，看着老虎逃走的方向，忽然笑了："龙族早想清它？那俺白龙今天，就清了它。"他继续西行，龙鳞在身上闪着，龙须一探一探，探着前方的路——那是取经路，是西行路，是他自己的路。' },
    6: { name: '双叉岭猎户', dark: '双叉岭前，刘伯钦拦路。他见白龙马相，举叉便刺："妖怪！"白龙侧身躲过，龙须一探，探入刘伯钦的记忆——他杀过九十九只虎，每只虎的眼里，都有龙族的影子。白龙低声："猎户，你杀过多少妖？"刘伯钦咬牙："九十九只！"白龙笑："那我，是第一百只——也是第一只，不杀你的。"他收龙须，刘伯钦怔住，钢叉落在地上。' },
    7: { name: '双叉龙影', dark: '岭上魔影缠白龙。他现龙形一绕："俺是龙，不是影。"魔影被龙气压散。双叉岭的魔影，是历代取经人的"不甘"，缠着白龙，要借他的身再走一遭。白龙现龙形一绕："俺是龙，不是影。"魔影被龙气压散。他看着散去的魔影，忽然笑了："俺是龙，不是影。可俺白龙现在，是马，不是龙了。俺白龙的龙形，只能在夜里，只能在没人的时候，才能现一现。"他伸手摸了摸自己的龙鳞，龙鳞已经褪了一半，露出下面的马皮。他忽然叹了口气："褪了龙鳞，露出马皮？俺白龙今天，才真的成了马。可这马，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在岸上，双叉岭在脚下，天庭在天上。俺白龙今天，才真的懂了。"他在双叉岭等着，等着取经人，等着驮他西行，等着有一天，能做回龙。' },
    8: { name: '鹰愁化马', dark: '观音点化白龙："你当马，驮他西行。"白龙流泪化马，但暗中咬断一根龙须——"我留了一截龙形，等我自己回来。"鹰愁涧的水浊浪滔天，观音菩萨点化白龙："你当马，驮他西行。"白龙流泪化马，但暗中咬断一根龙须——"我留了一截龙形，等我自己回来。"他看着自己化作的白马，忽然哭了："化作白马？俺白龙今天，才真的成了马。可这马，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在岸上，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"他伸手摸了摸自己咬断的龙须，龙须还在，还在发光，还在提醒他，他是龙，不是马。他忽然笑了："留了一截龙形？俺白龙今天，才真的留了希望。等俺白龙驮取经人到了灵山，等俺白龙取到了真经，等俺白龙成了正果，俺白龙就做回龙，就回西海，就见父王，就见龙族。可这希望，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在岸上，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"他在鹰愁涧等着，等着取经人，等着驮他西行，等着有一天，能做回龙。' },
    9: { name: '陡涧换马', dark: '观音点化，泣泪化马。（白龙原版专属，无替换）鹰愁涧的水浊浪滔天，观音菩萨点化白龙，要他化作白马，驮取经人西行。白龙泣泪化马，但暗中咬断一根龙须——"我留了一截龙形，等我自己回来。"他看着自己化作的白马，忽然哭了："化作白马？俺白龙今天，才真的成了马。可这马，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在岸上，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"他伸手摸了摸自己咬断的龙须，龙须还在，还在发光，还在提醒他，他是龙，不是马。他忽然笑了："留了一截龙形？俺白龙今天，才真的留了希望。等俺白龙驮取经人到了灵山，等俺白龙取到了真经，等俺白龙成了正果，俺白龙就做回龙，就回西海，就见父王，就见龙族。可这希望，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在岸上，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"他在鹰愁涧等着，等着取经人，等着驮他西行，等着有一天，能做回龙。' },
    10: { name: '龙须探路', dark: '虎先锋拦路。白龙龙须探入风沙："风里有虎，虎后有貂鼠。师父，这岭不好过。"黄风岭的虎先锋，横刀拦路，是黄风怪座下先锋。白龙龙须探入风沙："风里有虎，虎后有貂鼠。师父，这岭不好过。"他看着虎先锋，忽然笑了："虎先锋，你终于，懂了。你是黄风怪座下先锋，可你知道吗？黄风怪是灵山脚下得道的老鼠，因为偷了琉璃盏内的清油，怕金刚拿他，才走了。你跟了这样的主子，能有什么好下场？"虎先锋怔住——他从没想过，白龙会这么说。他看着白龙，忽然哭了："敖烈，你终于，懂了。我是虎先锋，是黄风怪座下先锋。可我跟了黄风怪三百年，他从来没把我当人看，只把我当狗看。我知罪。我只是想尝尝，被人当人看的滋味。"白龙跪在地上，泪流满面："虎先锋，你终于，懂了。被人当人看的滋味，不是偷来的，是挣来的。你跟俺白龙西行一路，便懂了。龙族的债，这一世，一起还。"虎先锋叩首，含泪随白龙西行。白龙看着虎先锋的背影，忽然笑了："龙须探路？俺白龙今天，才真的探了路。可这探，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在黄风岭，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    11: { name: '龙吟镇风', dark: '黄风卷沙。白龙一声龙吟，风沙被震散一瞬："龙吟能镇水，也能镇风。"黄风岭的黄风怪，吹起满山黄沙，遮天蔽日。白龙一声龙吟，风沙被震散一瞬："龙吟能镇水，也能镇风。"他站在风中，龙吟镇着风沙，纹丝不动。黄风怪在风眼中看着他，忽然怔住——它从没想过，有人能用龙吟镇住三昧神风。白龙看着风眼，忽然笑了："黄风怪，你吹的是风，不是沙。俺白龙的龙吟，比你的风还硬。你吹吧，吹累了，俺白龙再跟你算账。"他一声龙吟，风沙被震散，九片龙鳞齐齐发光，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。龙族的债，这一世，一起还。黄风怪跪在地上，现出原形。灵吉菩萨从云中走出，把黄风怪带走。白龙看着灵吉菩萨的背影，忽然笑了："龙吟镇风？俺白龙今天，才真的镇了风。可这镇，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在黄风岭，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    12: { name: '龙鳞挡风', dark: '三昧神风吹来。白龙龙鳞竖起，风在鳞上刮出火星："龙鳞不怕风，怕的是没人记得龙。"黄风岭的三昧神风，迎面吹来，遮天蔽日。白龙龙鳞竖起，风在鳞上刮出火星："龙鳞不怕风，怕的是没人记得龙。"他站在风中，龙鳞挡着三昧神风，九片龙鳞齐齐发光。黄风怪在风眼中看着他，忽然怔住——它从没想过，有人能用龙鳞挡住三昧神风。白龙看着风眼，忽然笑了："黄风怪，你吹的是怨，不是风。俺白龙的龙鳞，比你的怨还深。你吹吧，吹累了，俺白龙再跟你算账。"他一声龙吟，龙鳞挡着三昧神风，九片龙鳞齐齐发光，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。龙族的债，这一世，一起还。黄风怪跪在地上，现出原形。灵吉菩萨从云中走出，把黄风怪带走。白龙看着灵吉菩萨的背影，忽然笑了："龙鳞挡风？俺白龙今天，才真的挡了风。可这挡，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在黄风岭，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    13: { name: '龙马助战', dark: '黄风大圣吹起神风。白龙驮着取经人踏风而上："师父，风里走不快，我驮你。"黄风岭的黄风大圣，立在风眼，金目赤红，三昧神风从它口中喷出。白龙驮着取经人踏风而上："师父，风里走不快，我驮你。"他驮着取经人，踏风而上，九片龙鳞齐齐发光。黄风大圣看着他，忽然怔住——它从没想过，有人能驮着取经人踏风而上。白龙看着黄风大圣，忽然笑了："黄风大圣，你吹的是怨，不是风。俺白龙的龙鳞，比你的怨还深。你吹吧，吹累了，俺白龙再跟你算账。"他一声龙吟，驮着取经人踏风而上，九片龙鳞齐齐发光，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。龙族的债，这一世，一起还。黄风大圣跪在地上，现出原形。灵吉菩萨从云中走出，把黄风大圣带走。白龙看着灵吉菩萨的背影，忽然笑了："龙马助战？俺白龙今天，才真的助了战。可这助，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在黄风岭，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    14: { name: '高老庄闻妖', dark: '高老庄庄主哭诉女儿被妖强占。白龙龙须一探，探入庄中——那妖的气息里，有天蓬元帅的味道，也有嫦娥的桂花香。白龙低声："那妖……我认得。前世，他是天蓬元帅，因情被贬。"庄主怔住。白龙合掌："施主，他强占你女，是恶；但他护你庄园三年，是善。善恶本无界，只在一念间。"' },
    15: { name: '云栈洞探', dark: '云栈洞中，白龙见猪八戒正对着镜子梳妆。他看见白龙，不慌不忙："龙？你也是被贬的？"白龙点头："我烧了明珠，被罚当马。"猪八戒苦笑："我调戏嫦娥，被罚投猪胎。咱俩，都是天庭的弃子。"白龙低声："弃子又如何？弃子，也能走自己的路。"猪八戒怔住，缓缓点头。' },
    16: { name: '八戒归降', dark: '猪八戒跪在取经人面前，痛哭流涕。白龙在一旁沉默，龙须忽然发光——他探入猪八戒的记忆，看见天蓬元帅当年在天河饮酒，看见嫦娥在月中起舞，看见他被贬时的不甘。白龙低声："天蓬，你终于肯认错了。"猪八戒怔住，泪流满面："是我……是我对不起嫦娥，对不起天庭。"白龙合掌："知错能改，善莫大焉。龙族的债，这一世，一起还。"' },
    17: { name: '高老送别', dark: '高老庄庄主送众人出门，欲言又止。白龙看出他心思："施主，你是舍不得那猪妖？"庄主叹气："那猪妖……虽能吃，却也护了我家庄园三年。"白龙龙须一探，探入庄主的记忆——三年来，猪八戒夜夜巡逻，赶走山贼，护得高老庄平安。白龙低声："护庄园三年，是善；强占民女，是恶。善恶分明，不必纠结。他护你庄园，你便祝他西行顺利；他强占你女，他已认错。往事如烟，不必再提。"庄主点头，目送众人西行。' },
    18: { name: '流沙渡龙', dark: '流沙河沙僧拦路。白龙一声龙吟镇住浊浪："你颈上九颗，是九世取经人。我驮的这位，是第十世。"沙僧怔住，让开渡口。流沙河的水浊浪滔天，沙僧项挂九颗骷髅，跪在渡口，向取经人叩首。白龙一声龙吟镇住浊浪："你颈上九颗，是九世取经人。我驮的这位，是第十世。"沙僧怔住——他从没想过，白龙会这么说。他看着白龙，忽然哭了："敖烈，你终于，懂了。我食了九世取经人，罪大恶极。第十世，我一定护他，不让他死。九世的债，这一世，一起还。"白龙跪在地上，泪流满面："卷帘大将，你终于，懂了。九世的债，这一世，一起还。龙族的债，这一世，一起还。咱们，都是一样的人。"沙僧让开渡口，白龙驮着取经人，一步一步蹚过流沙河。他看着河底的自己，忽然笑了："流沙渡龙？俺白龙今天，才真的渡了龙。可这渡，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在流沙河，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    19: { name: '龙涎灌树', dark: '白龙吐龙涎浇人参果树。树活了，但结出的果是龙形——"龙族也被镇元子收过魂。"五庄观的人参果树，被悟空推倒，镇元子大怒，要取经人赔树。白龙吐龙涎浇人参果树，树活了，但结出的果是龙形——"龙族也被镇元子收过魂。"他看着树上的龙形人参果，忽然哭了："龙族也被镇元子收过魂？俺白龙今天，才真的懂了。镇元子是地仙之祖，是人参果树的主人，是龙族的克星。他收过龙族的魂，把龙族的魂，化作人参果的形。"镇元子从殿中走出，叹道："敖烈，你终于，懂了。这人参果，养的不是仙，是龙族的魂。你用龙涎浇树，让树活了，让龙族的魂，终于，笑了。"白龙跪在地上，泪流满面："镇元大仙，你终于，懂了。龙族的债，这一世，一起还。"他看着树上的龙形人参果，忽然笑了："龙涎灌树？俺白龙今天，才真的灌了树。可这灌，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在五庄观，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    20: { name: '龙泪化石', dark: '白龙看见白骨精，落下一滴龙泪。泪水滴在白骨上，骨化为石——"至少不再是白骨。"白虎岭的白骨精，三次变化，三次被悟空打杀。第三次，白骨精没有逃，反而向白龙跪下。白龙看见白骨精，落下一滴龙泪。泪水滴在白骨上，骨化为石——"至少不再是白骨。"他看着化为石的白骨精，忽然哭了："至少不再是白骨？俺白龙今天，才真的懂了。白骨精是白虎岭的白骨，是历代取经人的残骸，是九世的债。俺白龙的龙泪，滴在白骨上，骨化为石，至少不再是白骨，至少不再是债。"白骨精在石中发声："敖烈，你终于，懂了。我是白骨精，是白虎岭的白骨，是历代取经人的残骸。我等了你九世，等你叫我一声师父。今天，你用龙泪，把我化为石，至少不再是白骨，至少不再是债。九世的债，这一世，一起还。"白龙跪在地上，泪流满面："白骨精，你终于，懂了。龙族的债，这一世，一起还。"他看着化为石的白骨精，忽然笑了："龙泪化石？俺白龙今天，才真的化了石。可这化，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在白虎岭，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    21: { name: '马厩孤鸣', dark: '白龙被逐回马厩。他变回龙形，却发现龙鳞已褪——"我连马都不如了。"三打白骨后，取经人贬悟空，白龙也被逐回马厩。他变回龙形，却发现龙鳞已褪——"我连马都不如了。"他看着马厩里的自己，忽然哭了："我连马都不如了？俺白龙今天，才真的懂了。龙鳞已褪，龙形已散，龙族的魂，已经不在了。俺白龙现在，是马，不是龙了。俺白龙的龙形，只能在夜里，只能在没人的时候，才能现一现。"他伸手摸了摸自己的龙鳞，龙鳞已经褪了一半，露出下面的马皮。他忽然叹了口气："褪了龙鳞，露出马皮？俺白龙今天，才真的成了马。可这马，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在马厩，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"他在马厩里等着，等着取经人，等着驮他西行，等着有一天，能做回龙。' },
    22: { name: '龙子战狼', dark: '白龙现原形与奎木狼缠斗。狼啸震碎龙鳞，但龙吟更长——"龙族不惧天庭走狗。"宝象国的黄袍怪，原是天上的奎木狼，下凡为妖，把取经人掳进波月洞，变作一只猛虎。白龙现原形与奎木狼缠斗。狼啸震碎龙鳞，但龙吟更长——"龙族不惧天庭走狗。"他看着奎木狼，忽然笑了："奎木狼，你终于，懂了。你是天庭二十八宿之一，是天庭的走狗，是天庭的锁链。可你下凡为妖，是为了情，不是为了恶。你害了取经人，害了宝象国，害了很多人。你知罪吗？"奎木狼怔住——他从没想过，白龙会这么说。他看着白龙，忽然哭了："敖烈，你终于，懂了。我是奎木狼，是天庭二十八宿之一。我下凡为妖，是为了情，不是为了恶。可我害了取经人，害了宝象国，害了很多人。我知罪。我只是想尝尝，不被天庭当狗看的滋味。"白龙跪在地上，泪流满面："奎木狼，你终于，懂了。不被天庭当狗看的滋味，不是偷来的，是挣来的。你跟俺白龙西行一路，便懂了。龙族的债，这一世，一起还。"奎木狼叩首，含泪随天庭使者回天宫。白龙看着奎木狼的背影，忽然笑了："龙子战狼？俺白龙今天，才真的战了狼。可这战，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在宝象国，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    23: { name: '黑松林失', dark: '黑松林黑雾起，取经人被掳。白龙断尾救主，龙尾在雾里划出一道水痕："师父，我驮过你过河，也能驮你出林。"黑松林的黑雾起，遮天蔽日，取经人被掳，不知去向。白龙断尾救主，龙尾在雾里划出一道水痕："师父，我驮过你过河，也能驮你出林。"他看着雾里的水痕，忽然哭了："九世取经人，都死在了俺白龙的手里。每一世，都被掳过，都被妖吃过，都死在了取经路上。这一世，俺白龙一定护他，不让他死。龙族的债，这一世，一起还。"他一声龙吟，震散黑雾，九片龙鳞齐齐发光，为他指路，穿过黑雾，找到取经人被掳的方向——那是碗子山波月洞的方向，是黄袍怪的方向，是奎木狼的方向。他站在黑松林的雾里，九片龙鳞齐齐发光，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。龙族的债，这一世，一起还。他循着龙尾的水痕，穿过黑雾，向碗子山波月洞走去，去救取经人，去讨公道，去还龙族的债。他断了的龙尾，在雾里发光，提醒他，他是龙，不是马，他是西海龙王三太子，是龙族的魂，是取经人的护法。' },
    24: { name: '龙珠换宝', dark: '白龙用自己的龙珠换紫金葫芦。银角接过龙珠愣住——珠里有他母亲的脸。平顶山的金角大王、银角大王，手持紫金红葫芦、羊脂玉净瓶，拦住取经人的去路。白龙用自己的龙珠换紫金葫芦。银角接过龙珠愣住——珠里有他母亲的脸。他看着龙珠里的母亲，忽然哭了："母亲？俺银角今天，才真的懂了。我是太上老君看银炉的童子，奉旨下凡为妖，被收回天。我演的是戏，可我母亲，是真的。她在龙珠里，等了我三百年。"白龙跪在地上，泪流满面："银角大王，你终于，懂了。演戏演到俺白龙头上了？今天，俺白龙就替你把戏，演完！龙珠不是俺的，是西海的，是天庭的，是龙族的锁链。俺白龙没有龙珠，就不是龙了，就自由了。可这自由，当得真不容易。"金角银角跪在地上，现出原形。太上老君从云中走出，把金角银角带回天庭。白龙看着太上老君的背影，忽然笑了："龙珠换宝？俺白龙今天，才真的换了宝。可这换，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在平顶山，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    25: { name: '龙族背尸', dark: '乌鸡国王托梦。白龙驮着国王的尸身过河，龙吟低回："你背着一国的冤，我驮着一族的锁。咱俩，都别松。"乌鸡国的国王，被妖道推入井中，三年不得超生。他托梦给取经人，诉冤情，求他救自己。白龙驮着国王的尸身过河，龙吟低回："你背着一国的冤，我驮着一族的锁。咱俩，都别松。"他驮着国王的尸身，一步一步蹚过河，忽然明白了：取经之路，背的不是经，是千万取经人的冤。他把尸身背过河，悟空用还魂丹救活国王。国王跪在他面前："敖烈，你救的不是我，是乌鸡国。"白龙摇头："不，俺白龙救的，是取经人。"他看着国王的眼睛，看见了九世取经人的死。他忽然叹了口气："尸比活人轻，因为活人背着命。国王背着乌鸡国的命，俺白龙背着龙族的命。咱们，都不轻。龙族的债，这一世，一起还。"他站在乌鸡国的井边，九片龙鳞齐齐发光，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。龙族的债，这一世，一起还。' },
    26: { name: '龙族家事', dark: '白龙认出鼍龙是西海旁支。两龙在水中缠斗，白龙低语："你爹的事，我帮你翻案。"黑水河的鼍龙，原是西海龙王的外甥，因逆被贬，在黑水河为妖，化舟渡取经人过河，却在江心掀翻船只，要吃取经人。白龙认出鼍龙是西海旁支。两龙在水中缠斗，白龙低语："你爹的事，我帮你翻案。"鼍龙怔住——他从没想过，白龙会这么说。他看着白龙，忽然哭了："敖烈，你终于，懂了。我是鼍龙，是西海龙王的外甥。我因逆被贬，在黑水河为妖。我害了取经人，害了很多人。我知罪。我只是想尝尝，不被天庭当狗看的滋味。"白龙跪在地上，泪流满面："鼍龙，你终于，懂了。不被天庭当狗看的滋味，不是偷来的，是挣来的。你跟俺白龙西行一路，便懂了。你爹的事，我帮你翻案。龙族的债，这一世，一起还。"鼍龙叩首，含泪随西海龙王回龙宫。白龙看着鼍龙的背影，忽然笑了："龙族家事？俺白龙今天，才真的理了家事。可这理，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在黑水河，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    27: { name: '龙涎灭火', dark: '白龙吐龙涎浇灭三昧真火。红孩儿愣住："龙族的口水比火厉害？"号山枯松涧火云洞的红孩儿，手持火尖枪，口喷三昧真火，拦住取经人的去路。白龙吐龙涎浇灭三昧真火。红孩儿愣住："龙族的口水比火厉害？"他看着红孩儿，忽然笑了："红孩儿，你终于，懂了。你是牛魔王和铁扇公主的儿子，是圣婴大王，是三昧真火的主人。可你知道吗？三昧真火，是太上老君炼丹炉里的火，是天庭的火，是龙族的克星。俺白龙的龙涎，比你的火厉害，因为龙族的水，专克火族的山。"红孩儿怔住——他从没想过，白龙会这么说。他看着白龙，忽然哭了："敖烈，你终于，懂了。我是红孩儿，是圣婴大王，是三昧真火的主人。可我害了取经人，害了很多人。我知罪。我只是想尝尝，被人当人看的滋味。"白龙跪在地上，泪流满面："红孩儿，你终于，懂了。被人当人看的滋味，不是偷来的，是挣来的。你跟俺白龙西行一路，便懂了。龙族的债，这一世，一起还。"红孩儿叩首，含泪随观音菩萨回南海。白龙看着观音菩萨的背影，忽然笑了："龙涎灭火？俺白龙今天，才真的灭了火。可这灭，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在火云洞，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    28: { name: '黑水擒龙', dark: '黑水河黑水滔滔，鼍龙化舟渡取经人过河。白龙龙须一探，探入鼍龙的记忆——西海旁支，因"逆"被贬。他一声龙吟镇住鼍龙："你敢害俺师父？俺白龙今天，敲你九个龙鳞！"鼍龙跪地求饶："敖烈饶命！我也是被天庭逼的！"白龙收声："逼的？那俺白龙今天，教你怎么反逼回去。"' },
    29: { name: '车迟国前', dark: '车迟国国王崇道灭佛，和尚被赶去做苦役。白龙路过城门，见两个道士鞭打和尚。他龙须一探，探入道士的记忆——虎力、鹿力、羊力三妖。他一声龙吟震开城门："三个杂毛，也敢在俺白龙面前装神弄鬼？"道士们吓得跪地求饶。白龙低声："求雨？俺白龙一个龙吟，就能下三天三夜的雨！"' },
    30: { name: '三清观戏', dark: '三清观中，虎力、鹿力、羊力三妖化作三清，受香火供奉。白龙夜探三清观，见供桌上的素斋——那是和尚们饿着肚子供的。他一声龙吟震烂三清像："三个杂毛，也配受香火？"三妖现原形，跪地求饶。白龙低声："求雨？俺白龙一个龙吟，就能下三天三夜的雨！你们求了半个时辰，滴雨未下，还有脸受香火？"' },
    31: { name: '高台求雨', dark: '车迟国高台求雨，虎力大仙登坛作法。白龙在台下合掌，默念《心经》。虎力求了半个时辰，滴雨未下。白龙登台，一声龙吟，天降甘霖。国王大惊："圣僧真神！"白龙低声："不是神，是心诚。你们求雨，求的是自己的面子；俺白龙求雨，求的是百姓的活路。心不一样，雨自然不一样。"' },
    32: { name: '隔板猜物', dark: '车迟国隔板猜物，鹿力大仙与白龙比试。柜中放的是山河社稷袄，乾坤地理裙。白龙龙须一探，探入柜中，嗅出柜中之物——"山河社稷袄，乾坤地理裙。"国王大惊。白龙低声："不是俺白龙能猜，是这世上的物，都在经里。你们猜物，猜的是自己的贪欲；俺白龙猜物，猜的是万物的本相。心不一样，猜的自然不一样。"' },
    33: { name: '云梯显圣', dark: '车迟国云梯显圣，羊力大仙与白龙比试坐禅。云梯高百丈，白龙合掌而上，心中默念《心经》。羊力在云端坐了三个时辰，终于撑不住落下。白龙仍在云端，合掌不语。国王叹："圣僧真乃活佛！"白龙睁眼："不是佛，是心定。你们坐禅，坐的是自己的面子；俺白龙坐禅，坐的是万物的本相。心不一样，坐的自然不一样。"' },
    34: { name: '车迟除妖', dark: '车迟国三妖现原形，虎力、鹿力、羊力跪地求饶。白龙龙尾一摆，卷住三妖："你们崇道灭佛，害了多少和尚？"三妖泣道："我们也是被天庭利用，求敖烈饶命。"白龙收尾："饶命可以，但你们要替那些被你们害死的和尚，念经超度。"三妖叩首，含泪念经。白龙低声："这才像话！以后再敢装神弄鬼，俺白龙的龙尾，卷碎你们的狗头！"' },
    35: { name: '龙鳞挡琢', dark: '金刚琢套向白龙。龙鳞碎了九片，但琢子也裂了——"龙族九死一生的硬度。"金兜山的青牛精，手持金刚琢，套尽万物，拦住取经人的去路。金刚琢套向白龙。龙鳞碎了九片，但琢子也裂了——"龙族九死一生的硬度。"他看着碎了的龙鳞，忽然哭了："龙鳞碎了九片？俺白龙今天，才真的懂了。龙鳞是龙族的魂，是龙族的命，是龙族的锁链。龙鳞碎了，龙族的魂，就碎了。可琢子也裂了，说明龙族的硬度，比金刚琢还硬。"青牛精怔住——他从没想过，有人能用龙鳞挡金刚琢。他看着白龙，忽然叹了口气："敖烈，你终于，懂了。金刚琢是太上老君的法宝，是套尽万物的锁链。可你的龙鳞，比金刚琢还硬，因为你的龙鳞，是龙族九死一生的硬度。"白龙跪在地上，泪流满面："青牛精，你终于，懂了。龙族的债，这一世，一起还。"他看着碎了的龙鳞，忽然笑了："龙鳞挡琢？俺白龙今天，才真的挡了琢。可这挡，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在金兜山，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    36: { name: '金兜降牛', dark: '金兜山青牛精现原形，跪地求饶。白龙龙尾一摆，卷住青牛头："你是太上老君的坐骑，偷了金刚琢下凡。你可知罪？"青牛精泣道："我知罪。我只是想尝尝，不被人骑的滋味。"白龙收尾："不被人骑的滋味，不是偷来的，是挣来的。你跟俺白龙西行一路，便懂了。"青牛精叩首，含泪随老君回天宫。白龙低声："这才像话！以后再敢偷东西，俺白龙的龙尾，卷碎你的牛头！"' },
    37: { name: '龙涎入河', dark: '女儿国子母河水涨。白龙把龙涎滴入河中，水退了一尺："这河水孕命，龙涎镇水。"他驮着取经人，一步一步蹚过河去。西梁女国的子母河，水涨三尺，要取经人喝子母河的水，打掉腹中的胎气。白龙把龙涎滴入河中，水退了一尺："这河水孕命，龙涎镇水。"他驮着取经人，一步一步蹚过河去。他看着河底的自己，忽然笑了："这河水孕命，龙涎镇水？俺白龙今天，才真的懂了。子母河的水，孕的是命，是胎气，是取经人的执念。俺白龙的龙涎，镇的是水，是命，是取经人的执念。可这镇，当得真不容易。"如意真仙怔住——他从没想过，白龙会这么说。他看着白龙，忽然叹了口气："敖烈，你终于，懂了。子母河的水，打掉的不是胎气，是执念。你打掉了对龙族的执念，就真的成了和尚。"白龙跪在地上，泪流满面："如意真仙，你终于，懂了。龙族的债，这一世，一起还。"他驮着取经人，一步一步蹚过河去，九片龙鳞齐齐发光，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。龙族的债，这一世，一起还。' },
    38: { name: '龙子拒婚', dark: '女王对白龙说："你不是马，是龙。龙也该有伴侣。"白龙摇头："我的伴侣是自由。"西梁女国的女王，倾国倾城，愿以一国之富，招白龙为王，她为王后。女王对白龙说："你不是马，是龙。龙也该有伴侣。"白龙摇头："我的伴侣是自由。"他看着女王的眼睛，忽然哭了："我的伴侣是自由？俺白龙今天，才真的懂了。自由不是伴侣，是龙族的魂，是龙族的命，是龙族的锁链。俺白龙的伴侣，不是女王，不是龙族，不是天庭，是自由。可这自由，当得真不容易。"女王怔住——她从没想过，白龙会这么说。她看着白龙，忽然叹了口气："敖烈，你终于，懂了。自由不是伴侣，是龙族的魂。你打掉了对女王的执念，就真的成了和尚。"白龙跪在地上，泪流满面："女王，你终于，懂了。龙族的债，这一世，一起还。"他看着女王的眼睛，忽然笑了："女王，俺白龙是龙，不是马。你是女王，是凡人。我们，不一样。俺白龙配不上你。"女王怔住——她从没想过，白龙会这么说。她看着白龙的眼睛，忽然笑了："敖烈，你终于，懂了。我嫁的不是取经人，不是龙，不是天蓬元帅。我嫁的是你，是敖烈，是你。可你说，你配不上凡人。那我问你，你配得上龙族吗？"白龙跪在地上，泪流满面。他一声龙吟，震碎了女儿国的宫殿："龙族？俺白龙今天，才真的懂了。我配不上凡人，也配不上龙族。我配得上的，只有取经路，只有师父，只有灵山。俺白龙今天，才真的成了和尚。可这和尚，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在女儿国，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    39: { name: '蝎子精刺', dark: '毒敌山琵琶洞蝎子精掳取经人入洞，欲逼成亲。白龙龙须一探，探入蝎子精的记忆——她的毒针，是如来佛祖的指甲。他一声龙吟震开琵琶洞："你这蝎子，偷了如来的指甲，也敢在俺白龙面前装神弄鬼？"蝎子精冷笑："偷来的指甲，也是指甲。你这龙，烧了明珠，还有脸说我？"白龙怔住——她说的，是实话。昴日星官收服蝎子精，白龙叹："偷来的东西，终究不是自己的。龙族的债，这一世，一起还。"' },
    40: { name: '龙鳞抗毒', dark: '白龙用龙鳞挡毒针。龙鳞被毒蚀穿，但白龙发现毒里有龙族气息——"这蝎子是龙族变异。"毒敌山琵琶洞的蝎子精，手持三股钢叉，尾后倒马毒桩，拦住取经人的去路。她一毒桩刺来，白龙用龙鳞挡毒针。龙鳞被毒蚀穿，但白龙发现毒里有龙族气息——"这蝎子是龙族变异。"他看着被毒蚀穿的龙鳞，忽然哭了："这蝎子是龙族变异？俺白龙今天，才真的懂了。蝎子精是龙族变异，是龙族的魂，是龙族的命，是龙族的锁链。她的毒针，是龙族的毒，是龙族的魂，是龙族的命。"蝎子精怔住——她从没想过，白龙会这么说。她看着白龙，忽然叹了口气："敖烈，你终于，懂了。我是蝎子精，是龙族变异，是龙族的魂。我偷了如来的指甲，可偷得来如来的法？你用龙鳞挡毒针，可挡得住龙族的魂？"白龙跪在地上，泪流满面："蝎子精，你终于，懂了。偷来的东西，终究不是自己的。龙族的债，这一世，一起还。"昴日星官从云中走出，双翅一展，蝎子精现了原形。白龙看着蝎子精的尸体，忽然叹了口气："龙鳞抗毒？俺白龙今天，才真的抗了毒。可这抗，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在琵琶洞，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    41: { name: '火焰山前', dark: '火焰山烈焰冲天，八百里火焰，无春无秋，四季皆热。白龙龙须一探，探入火焰的记忆——这火，是当年孙悟空踢翻太上老君的炼丹炉，落下的火。他低头不语。取经人合掌："解铃还须系铃人。这火，还得俺老孙来灭。"悟空抬头："师父，俺老孙这就去借芭蕉扇！"他一个筋斗，翻向翠云山。白龙低声："这火，烤得俺白龙的龙鳞都发烫了。"' },
    42: { name: '三调芭蕉', dark: '孙悟空三调芭蕉扇，与牛魔王、铁扇公主斗法。白龙在一旁合掌念经，心中却忐忑——这一战，关乎取经成败。悟空终于借到芭蕉扇，扇灭八百里火焰。取经人合掌："火灭了，可心里的火，何时能灭？"悟空笑："师父，到了灵山，心里的火，自然就灭了。"白龙叹："俺白龙心里的火，是龙族的罪火。到了灵山，不知能不能灭。"众人继续西行。' },
    43: { name: '祭赛国前', dark: '祭赛国金光寺塔顶舍利被盗，国王震怒，将众僧下狱。白龙潜入碧波潭方向的水道，龙须探出舍利的去向——那是碧波潭万圣龙王与九头虫所为。他夜探金光寺，龙须在塔顶排成一线，替他找到妖雾痕迹。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"白龙低声："舍利本在心中，不在塔上。但众生需要光，我便替他们把光找回来。龙族的债，这一世，一起还。"' },
    44: { name: '碧波潭探', dark: '碧波潭底，万圣龙宫灯火通明。九头虫把舍利当夜明珠，挂在龙女床头。白龙潜入龙宫，龙须在水里排成一线，替他找到九头虫藏舍利的暗格。他抱起舍利，龙须挡住追兵："走！我替你断后。"龙女抱着空床头喃喃："偷来的光，也是光。"白龙回头："光，不是偷来的，是自己心里发出来的。"龙女怔住，舍利在他怀中发光。' },
    45: { name: '真假龙形', dark: '六耳变白龙。真白龙龙须一探："你没龙须，假龙。"花果山的六耳猕猴，化作悟空的模样，打昏取经人，抢走行李，要自己去取经。他还化作白龙的模样，要骗取经人。真白龙龙须一探："你没龙须，假龙。"假白龙怔住——他从没想过，白龙会用龙须分辨真假。他看着真白龙，忽然笑了："敖烈，你终于，懂了。我不是白龙，我是六耳猕猴。我化作你的模样，是要骗取经人，要自己去取经。可你用龙须分辨真假，就说明你真的成了龙，真的成了白龙，真的成了取经人的坐骑。"真白龙跪在地上，泪流满面："六耳猕猴，你终于，懂了。俺白龙是龙，是白龙，是取经人的坐骑。俺白龙有龙须，有龙族的魂，有取经人的味。你没有，你是假的。今天，俺白龙就替你，把假的，砸了！"假白龙在风中散去，留下一句话："敖烈，你终于，成了真的白龙。"真白龙站在风中，忽然叹了口气："真的白龙？俺白龙今天，才真的成了白龙。可这白龙，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在花果山，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    46: { name: '龙涎化云', dark: '火焰山前，白龙吐尽龙涎，化作雨云罩住火头："龙族的水，专克火族的山。"火势渐小，他驮着取经人冲过火焰山。火焰山烈焰冲天，八百里火焰，无春无秋，四季皆热。白龙吐尽龙涎，化作雨云罩住火头："龙族的水，专克火族的山。"火势渐小，他驮着取经人冲过火焰山。他看着火焰山的火，忽然哭了："龙族的水，专克火族的山？俺白龙今天，才真的懂了。火焰山的火，是孙悟空踢翻太上老君的炼丹炉落下的火，是天庭的火，是龙族的克星。俺白龙的龙涎，比火焰山的火厉害，因为龙族的水，专克火族的山。"铁扇公主怔住——她从没想过，白龙会这么说。她看着白龙，忽然叹了口气："敖烈，你终于，懂了。火焰山的火，是孙悟空踢翻太上老君的炼丹炉落下的火。你用龙涎化云，罩住火头，就是让火焰山的火，终于，灭了。"白龙跪在地上，泪流满面："铁扇公主，你终于，懂了。龙族的债，这一世，一起还。"他驮着取经人，一步一步冲过火焰山，九片龙鳞齐齐发光，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。龙族的债，这一世，一起还。' },
    47: { name: '牛魔王战', dark: '牛魔王现出原形，一头大白牛，头如峻岭，眼若闪光。白龙龙尾一摆，卷住牛头："牛施主，你与悟空是结拜兄弟，何必相煎太急？"牛魔王怒吼："结拜兄弟？他欺我妻子，辱我孩儿，还配叫兄弟？"白龙怔住——他说的，是实话。两妖大战三百回合，悟空终于降服牛魔王。白龙叹："情之一字，最难放下。牛大哥，对不住了。龙族的债，这一世，一起还。"' },
    48: { name: '罗刹女泪', dark: '铁扇公主交出芭蕉扇，泪流满面。白龙龙须一探，探入铁扇公主的记忆——她身上有桂花香味，那是嫦娥的味道。他低声："女菩萨，你与牛魔王的恩怨，到此为止吧。"铁扇公主泣道："敖烈，我与牛魔王夫妻一场，如今他被降服，我活着还有什么意思？"白龙叹："活着，就是意思。你把芭蕉扇借给我们，扇灭火焰山，便是功德一件。"铁扇公主点头，含泪回翠云山。白龙收起芭蕉扇，继续西行，心中暗想："龙族的债，这一世，一起还。"' },
    49: { name: '火焰山过', dark: '孙悟空扇灭八百里火焰，火焰山从此四季如春。白龙收起芭蕉扇，低声："师父，这火，是俺老孙当年踢翻炼丹炉落下的，如今俺老孙亲手灭了，也算因果报应。"取经人合掌："因果报应，丝毫不爽。我们西行取经，便是要了这因果。"众人继续西行。白龙回头望了一眼火焰山，心中暗想："俺白龙的因果，何时能了？龙族的债，这一世，一起还。"' },
    50: { name: '龙隐祭赛', dark: '祭赛国金光寺金光尽失。白龙潜入碧波潭方向的水道，龙须探出舍利的去向："光沉在水底。师父，我入水替你们找。"祭赛国金光寺塔顶舍利被盗，国王震怒，将满寺僧众下狱，严刑拷打。白龙潜入碧波潭方向的水道，龙须探出舍利的去向："光沉在水底。师父，我入水替你们找。"他看着水底的龙宫，忽然哭了："光沉在水底？俺白龙今天，才真的懂了。舍利是祭赛国的镇宝，是金光寺的光，是百姓的命。可舍利沉在水底，沉在碧波潭，沉在万圣龙王的龙宫里。俺白龙是龙，是西海龙王三太子，是龙族的魂。俺白龙入水，替你们找舍利，替你们找光，替你们找命。"他潜入碧波潭，龙须在水中排成一线，替他找到妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"白龙低声："舍利本在心中，不在塔上。但众生需要光，我便替他们把光找回来。龙族的债，这一世，一起还。"他站在碧波潭的水底，九片龙鳞齐齐发光，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。龙族的债，这一世，一起还。' },
    51: { name: '金光寺冤僧', dark: '金光寺舍利失窃，满寺僧众被冤下狱。白龙潜入碧波潭，龙须探出舍利沉在潭底龙宫："光在水底。师父，我入水讨光。"祭赛国金光寺塔顶舍利被盗，国王震怒，将满寺僧众下狱，严刑拷打。白龙潜入碧波潭，龙须探出舍利沉在潭底龙宫："光在水底。师父，我入水讨光。"他看着水底的龙宫，忽然哭了："光在水底？俺白龙今天，才真的懂了。舍利是祭赛国的镇宝，是金光寺的光，是百姓的命。可舍利沉在水底，沉在碧波潭，沉在万圣龙王的龙宫里。俺白龙是龙，是西海龙王三太子，是龙族的魂。俺白龙入水，替你们讨舍利，替你们讨光，替你们讨命。"他潜入碧波潭，龙须在水中排成一线，替他找到妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"白龙低声："舍利本在心中，不在塔上。但众生需要光，我便替他们把光找回来。龙族的债，这一世，一起还。"他站在碧波潭的水底，九片龙鳞齐齐发光，为他指路。他忽然明白了：取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。龙族的债，这一世，一起还。他循着龙须的指引，穿过水底的黑雾，向万圣龙王的龙宫走去，去讨舍利，去讨公道，去还龙族的债。' },
    52: { name: '碧波潭探', dark: '碧波潭底，白龙遇到西海旧部。旧部龙兵认出他："敖烈，你被贬成马。"白龙点头："可我的龙形还在。"他带着旧部，一起探向九头虫的龙宫。' },
    53: { name: '万圣盗草', dark: '万圣公主盗九叶灵芝给九头虫续命。白龙游过她身边，低声："我也偷过——偷过父亲的明珠，换来一条锁链。"公主怔住。白龙把灵芝推回她手中："真心，不用偷。"' },
    54: { name: '龙鹏之争', dark: '大鹏是凤凰之子，白龙是龙王之子。两族世仇在此一战。白龙输了翅膀，赢了尊严——他用龙尾卷住舍利，护在身下："光，不能丢。"' },
    55: { name: '龙潜木仙', dark: '荆棘岭树精吟诗。白龙在林中盘踞，龙吟低鸣："你们扎根千年，我们困在潭里千年。论被困，谁也不比谁少。"树精们沉默了。' },
    56: { name: '龙啸小雷音', dark: '小雷音假佛坐殿。白龙一声龙啸，殿瓦簌簌落下："假佛的殿，经不起龙吟。"他驮着取经人，头也不回地绕过假殿。小雷音寺的黄眉老佛，化作如来佛祖的模样，坐在雷音寺的大殿上，受香火供奉。白龙一声龙啸，殿瓦簌簌落下："假佛的殿，经不起龙吟。"他驮着取经人，头也不回地绕过假殿。他看着假殿的殿瓦，忽然笑了："假佛的殿，经不起龙吟？俺白龙今天，才真的懂了。真佛不在殿上，在难中。可你假佛坐殿，受香火供奉，害了多少和尚？今天，俺白龙就替你，把假佛，砸了！"黄眉老佛怔住——他从没想过，白龙会用龙吟震殿。他看着白龙，忽然哭了："敖烈，你终于，懂了。我是弥勒佛的童子，偷了人种袋下凡。我知罪。我只是想尝尝，当佛的滋味。"白龙跪在地上，泪流满面："黄眉老佛，你终于，懂了。当佛的滋味，不是偷来的，是修来的。你跟俺白龙西行一路，便懂了。龙族的债，这一世，一起还。"黄眉老佛叩首，含泪随弥勒佛回天庭。白龙看着黄眉老佛的背影，忽然笑了："龙啸小雷音？俺白龙今天，才真的啸了小雷音。可这啸，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在小雷音寺，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    57: { name: '朱紫国医', dark: '朱紫国王悬丝诊脉。白龙把龙涎滴进药汤："龙涎能续命。"国王喝下，病气去了三分。白龙低声："你病的是心，龙涎治不了心。"' },
    58: { name: '狮驼龙啸', dark: '狮驼岭三魔食城。白龙一声龙啸震城："食城？先过龙吟。"狮驼岭的青毛狮子怪、黄牙老象怪、大鹏金翅雕，三魔联手，食尽狮驼国一城百姓，连骨头都没剩下。白龙一声龙啸震城："食城？先过龙吟。"三魔怔住——他们从没想过，有人能用龙吟震城。他们看着白龙，忽然哭了："敖烈，你终于，懂了。我们食城，食的是百姓的命。你龙吟震城，震的是我们的罪。可你知道吗？我们食城，是因为我们也是被天庭食的。我们是天庭的坐骑，是天庭的棋子，是天庭的工具。我们食城，是为了反抗天庭，是为了自由，是为了自己。"白龙跪在地上，泪流满面："三魔，你们终于，懂了。食城不是罪，反抗天庭也不是罪。可你们食了一城百姓，这就是罪。龙族的债，这一世，一起还。"三魔跪在地上，现出原形。如来佛祖从云中走出，把三魔带回灵山。白龙看着如来佛祖的背影，忽然笑了："狮驼龙啸？俺白龙今天，才真的啸了狮驼。可这啸，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在狮驼国，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    59: { name: '祭赛金光', dark: '祭赛国金光寺塔顶舍利被盗，国王震怒，将众僧下狱。白龙潜入碧波潭方向的水道，龙须探出舍利的去向——那是碧波潭万圣龙王与九头虫所为。他夜探金光寺，龙须在塔顶排成一线，替他找到妖雾痕迹。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"白龙低声："舍利本在心中，不在塔上。但众生需要光，我便替他们把光找回来。龙族的债，这一世，一起还。"他潜入碧波潭，龙须在水中划出一道光痕——"光，不能丢。"' },
    60: { name: '灭法剃王', dark: '灭法国要杀万名僧。白龙驮着取经人夜入王宫，龙吟惊醒了满朝："龙来了！"国王吓得剃了头，从此再不敢杀僧。白龙在宫外低声："吓人，比杀人好。"灭法国的国王，前世是个和尚，被佛抛弃，转世为王，立志杀万名僧，以泄心头之恨。白龙驮着取经人夜入王宫，龙吟惊醒了满朝："龙来了！"国王吓得剃了头，从此再不敢杀僧。白龙在宫外低声："吓人，比杀人好。"他看着国王剃了的头，忽然笑了："吓人，比杀人好？俺白龙今天，才真的懂了。国王杀了九千九百九十九个和尚，可他心里，还是个和尚。他杀的不是僧，是他自己。俺白龙的龙吟，吓的不是国王，是国王心里的和尚。"国王怔住——他从没想过，白龙会这么说。他看着白龙，忽然哭了："敖烈，你终于，懂了。我杀了九千九百九十九个和尚，可我心里，还是个和尚。我杀的不是僧，是我自己。"白龙跪在地上，泪流满面："国王，你终于，懂了。灭法国，从此改名为钦法国。杀僧，不如度僧。度僧，不如度己。你杀了九千九百九十九个和尚，可你杀的不是僧，是你自己。今天，俺白龙替你，把龙吟，收了！"国王叩首，灭法国从此改名为钦法国。白龙看着国王的背影，忽然笑了："灭法剃王？俺白龙今天，才真的剃了王。可这剃，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在灭法国，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    61: { name: '隐雾梅花', dark: '隐雾山梅花计摄走取经人。白龙用龙须探雾，龙须沾了豹精的腥味："雾里藏豹，花里藏刀。"他驮着取经人冲散雾帐，豹精被龙尾抽翻。隐雾山的艾叶花皮豹子精，用分瓣梅花计，化作取经人的模样，要骗取经人入洞。白龙用龙须探雾，龙须沾了豹精的腥味："雾里藏豹，花里藏刀。"他驮着取经人冲散雾帐，豹精被龙尾抽翻。他看着豹精，忽然笑了："雾里藏豹，花里藏刀？俺白龙今天，才真的懂了。你用分瓣梅花计，化作取经人的模样，要骗取经人入洞。可你知道吗？取经人的模样，是九世取经人的模样，是龙族的模样，是天庭的模样。你化作取经人的模样，就是化作龙族的模样，就是化作天庭的模样。你骗的不是取经人，是你自己。"豹精怔住——他从没想过，白龙会这么说。他看着白龙，忽然哭了："敖烈，你终于，懂了。我是艾叶花皮豹子精，是隐雾山的妖。我用分瓣梅花计，化作取经人的模样，要骗取经人入洞。可我骗的不是取经人，是我自己。我知罪。我只是想尝尝，被人当人看的滋味。"白龙跪在地上，泪流满面："艾叶花皮豹子精，你终于，懂了。被人当人看的滋味，不是偷来的，是挣来的。你跟俺白龙西行一路，便懂了。龙族的债，这一世，一起还。"豹精叩首，含泪随白龙西行。白龙看着豹精的背影，忽然笑了："隐雾梅花？俺白龙今天，才真的探了雾。可这探，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在隐雾山，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    62: { name: '凤仙求雨', dark: '凤仙郡三年不雨。白龙腾云布雨，龙尾卷起东海之水："龙族求雨，不用咒。"他连下三天雨，凤仙郡枯田转绿。凤仙郡三年不雨，枯田千里，百姓流离失所，饿殍遍野。白龙腾云布雨，龙尾卷起东海之水："龙族求雨，不用咒。"他连下三天雨，凤仙郡枯田转绿，百姓欢呼雀跃，跪地叩首。他看着雨中的百姓，忽然哭了："龙族求雨，不用咒？俺白龙今天，才真的懂了。龙族是司雨的神，是百姓的命，是天庭的工具。可俺白龙现在，是马，不是龙了。俺白龙的龙形，只能在夜里，只能在没人的时候，才能现一现。今天，俺白龙现了龙形，布了雨，救了百姓，可俺白龙知道，这不是俺白龙的功劳，是龙族的功劳，是东海的功劳，是天庭的功劳。"他想起五百年前，西海的水军，也是这样布雨，也是这样救百姓，也是这样被天庭视为异端，也是这样被天庭写死。他想起鹰愁涧，五百年的风吹雨打，不仅没压垮他，反而炼出了不屈的意志。他睁开眼，龙鳞金光万道，看穿了凤仙郡的本相——不是三年不雨，是天庭的惩罚，是百姓的劫，是写死的剧本。他一声龙吟，震碎了凤仙郡的天："天庭的惩罚？百姓的劫？那俺白龙今天，替你们把这天砸了！"雨下了三天，凤仙郡枯田转绿，百姓欢呼雀跃。白龙站在云端，看着雨中的百姓，忽然笑了："龙族求雨，不用咒？那俺白龙今天，就求了雨。"他继续西行，龙鳞在身上闪着，龙须一探一探，探着前方的路——那是取经路，是西行路，是他自己的路。' },
    63: { name: '玉华传艺', dark: '玉华州三王子拜师。白龙现出龙形，教他们水性："我不会棒法，但我教你们——水要顺流，也要逆流。"三王子看着龙，愣了很久。' },
    64: { name: '竹节山斗', dark: '竹节山九灵元圣九头齐咬。白龙龙尾一摆，卷住九颗狮头："九颗头，一条命。"九灵元圣被龙尾勒得直吼，白龙松尾："你主人骑你，我不欺你。"' },
    65: { name: '金平府灯', dark: '金平府三头犀牛偷灯油。白龙龙吟震灯，灯油倒流回灯碗："灯油是百姓点的，你们偷灯油，跟偷民心一样。"犀牛精被龙吟镇住，不敢再动。' },
    66: { name: '给孤园厄', dark: '给孤园天竺公主招亲。白龙龙须探出公主身上有月宫桂花的味道——玉兔精假扮。他低声提醒取经人："师父，那是玉兔。龙族认得月宫的味道。"给孤园天竺公主招亲，取经人被砸中，要招他为驸马。白龙龙须探出公主身上有月宫桂花的味道——玉兔精假扮。他低声提醒取经人："师父，那是玉兔。龙族认得月宫的味道。"取经人怔住——他从没想过，公主是玉兔精假扮。他看着白龙，忽然哭了："敖烈，你终于，懂了。我是取经人，是金蝉子转世，是十世修行的好人。可我差点，就被玉兔精骗了，差点，就成了天竺国的驸马，差点，就忘了取经的路。"白龙跪在地上，泪流满面："师父，你终于，懂了。取经之路，取的不是经，是自己的心。心若不定，经念得再多，也是枉然。玉兔精假扮公主，骗的不是你，是你自己的心。你差点，就被自己的心骗了。龙族的债，这一世，一起还。"嫦娥收服玉兔精，白龙叹："偷来的东西，终究不是自己的。龙族的债，这一世，一起还。"他看着嫦娥的背影，忽然笑了："给孤园厄？俺白龙今天，才真的解了厄。可这解，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在天竺国，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    67: { name: '铜台府案', dark: '铜台府取经人被诬为盗。白龙驮着取经人夜巡，龙吟惊醒县衙："冤案不雪，龙不走。"县令连夜重审，冤情得雪。铜台府寇员外斋僧被害，取经人被诬为盗，下狱严刑拷打。白龙驮着取经人夜巡，龙吟惊醒县衙："冤案不雪，龙不走。"县令连夜重审，冤情得雪。他看着县令重审的样子，忽然笑了："冤案不雪，龙不走？俺白龙今天，才真的懂了。寇员外斋僧被害，取经人被诬为盗，下狱严刑拷打。可取经人是金蝉子转世，是十世修行的好人，怎么会是盗？县令连夜重审，冤情得雪，说明冤案，终究会雪。龙族的债，这一世，一起还。"县令怔住——他从没想过，白龙会这么说。他看着白龙，忽然哭了："敖烈，你终于，懂了。我是铜台府的县令，是寇员外的朋友，是取经人的审判官。可我差点，就判了取经人死刑，差点，就成了冤案的帮凶，差点，就忘了为官的路。"白龙跪在地上，泪流满面："县令，你终于，懂了。为官之路，为的不是官，是百姓的心。心若不正，官当得再大，也是枉然。取经人被诬为盗，诬的不是他，是你自己的心。你差点，就被自己的心诬了。龙族的债，这一世，一起还。"取经人合掌："白龙，委屈你了。"白龙低声："师父，不委屈。龙族的债，这一世，一起还。"众人继续西行。他看着铜台府的背影，忽然笑了："铜台府案？俺白龙今天，才真的解了案。可这解，当得真不容易。没有西海，没有明珠，没有龙子，只有一条龙，一根锁链，一个取经人。取经人在铜台府，鹰愁涧在脚下，天庭在天上。俺白龙今天，才真的懂了。"' },
    68: { name: '天竺国前', dark: '天竺国国都，繁华似锦。白龙龙须一探，探入公主的记忆——玉兔精假扮。他低声提醒取经人："师父，那是玉兔。龙族认得月宫的味道。"取经人叹："真假难辨，正如取经之路。我们西行取经，取的不是经，是自己的心。"白龙低声："龙族的债，这一世，一起还。"' },
    69: { name: '玉兔精现', dark: '天竺国公主抛绣球招亲，取经人被砸中。公主笑："取经人，你取的是经，还是自己？"取经人合十——这一问，比八十一难都重。白龙龙须一探，探入公主的记忆——玉兔精假扮。他低声提醒取经人："师父，那是玉兔。龙族认得月宫的味道。"嫦娥收服玉兔精，白龙叹："偷来的东西，终究不是自己的。龙族的债，这一世，一起还。"' },
    70: { name: '铜台府案', dark: '铜台府寇员外斋僧被害，取经人被诬为盗。白龙驮着取经人夜巡，龙吟惊醒县衙："冤案不雪，龙不走。"县令连夜重审，冤情得雪。取经人合掌："白龙，委屈你了。"白龙低声："师父，不委屈。龙族的债，这一世，一起还。"众人继续西行。' },
    71: { name: '灵山前望', dark: '灵山在望，金光万道。白龙龙须一探，探入灵山的记忆——那是超度的味道，苦的。他低声："师父，到了灵山，我们就能取经了。"取经人叹："取经之路，九九八十一难，我们都走过来了。最后一难，又算得了什么？"白龙回头望了一眼来时的路，心中暗想："取经之路，取的不是经，是自己的心。如今到了灵山，心，又在哪里？"他摸了摸自己的龙鳞，忽然觉得这鳞，比缰绳还重。' },
    72: { name: '凌云渡前', dark: '凌云渡前，弱水滔滔。接引佛祖撑船而来："取经人，上船吧。"取经人上船，船行至江心，忽然翻了——取经人落水，却见水中有一具死尸。白龙也跳下水，却见水中也有一具死尸——那是他自己。他怔住——过了凌云渡，他就不再是他了。他摸了摸自己的龙鳞，忽然觉得这鳞，比缰绳还重。龙须在水中发光，替他说："龙族的债，这一世，一起还。"' },
    73: { name: '化电归真', dark: '雷音门前，白龙看着自己龙鳞上滚过的电光："我烧过明珠，被雷劈过。这电，认得我。"他抖落满身电光，化作一泓清水："干净了，才配进灵山。"' },
    74: { name: '雷音寺前', dark: '雷音寺前，金光万道。白龙龙须一探，探入雷音寺的记忆——那是超度的味道，苦的。他低声："师父，到了雷音寺，我们就能取经了。"取经人叹："取经之路，九九八十一难，我们都走过来了。最后一难，又算得了什么？"白龙回头望了一眼来时的路，心中暗想："取经之路，取的不是经，是自己的心。如今到了雷音寺，心，又在哪里？"他摸了摸自己的龙鳞，忽然觉得这鳞，比缰绳还重。' },
    75: { name: '如来佛祖', dark: '如来佛祖端坐莲台，金光万道。取经人合掌："弟子玄奘，奉东土大唐皇帝旨意，前来拜佛求经。"如来佛祖笑："玄奘，你取经十世，到底取的是什么？"取经人怔住——这一问，比八十一难都重。白龙也怔住——他忽然明白，取经之路，取的不是经，是自己的心。如来佛祖点头："善哉善哉。你终于明白了。"白龙摸了摸自己的龙鳞，忽然觉得这鳞，比缰绳还重。龙须在佛前发光，替他说："龙族的债，这一世，一起还。"' },
    76: { name: '问佛龙吟', dark: '白龙上灵山，在佛前跪下："佛，我烧了明珠，被罚当马。我认了。可我想问——龙，能不能不做马？"佛不答。白龙站起身："你不答，我自己答。取完经，我做回龙。"' },
    77: { name: '灵山成正果', dark: '灵山册封，白龙被封八部天龙。他低头看了看自己——不再有缰绳。他抬起头："我当马当了十四年，今天，做回龙。"龙吟响彻灵山。' },
    78: { name: '取经回东', dark: '取经人取到真经，辞别如来，回东土大唐。白龙低声："师父，我们终于取经成功了。"取经人叹："取经之路，九九八十一难，我们都走过来了。如今取经成功，却不知该喜还是该悲。"白龙回头望了一眼灵山，心中暗想："取经之路，取的不是经，是自己的心。如今经取到了，心，又在哪里？"他摸了摸自己的龙鳞——不再有缰绳。他抬起头："我当马当了十四年，今天，做回龙。"龙吟响彻灵山。' },
    79: { name: '通天河遇', dark: '通天河前，弱水滔滔。老鼋游来："取经人，上船吧。"取经人上船，船行至江心，老鼋忽然问："取经人，我当年托你问如来佛祖，我何时能脱壳成人，你问了吗？"取经人怔住——他忘了。老鼋大怒，将船掀翻，众人落水，真经也被水浸湿。白龙也落水，却见水中也有一具死尸——那是他自己。他怔住——过了凌云渡，他就不再是他了。他摸了摸自己的龙鳞——不再有缰绳。他抬起头："我当马当了十四年，今天，做回龙。"龙吟响彻灵山。' },
    80: { name: '真经晒干', dark: '众人落水，真经被水浸湿。白龙低声："师父，我们把真经晒干就是了。"众人将真经摊在石头上晒干，却发现最后一页被石头粘住，撕坏了一角。取经人叹："真经不全，如何是好？"白龙低声："师父，真经不全，正如人生不全。不全，才是真。"取经人点头："善哉善哉。不全，才是真。"白龙摸了摸自己的龙鳞——不再有缰绳。他抬起头："我当马当了十四年，今天，做回龙。"龙吟响彻灵山。他抬头望了一眼天空，心中暗想："龙族的债，这一世，终于还了。"' },
    81: { name: '无字碑终', intro: '自沉："他碎了龙须，也碎了锁链。马厩，从此是龙宫。"\n隐藏「龙归沧海」：龙须替渡，真白龙归西海。' },
  },
  tangseng: {
    2: { name: '金蝉蒙冤', dark: '你投生状元府，出生便被刘洪追杀。你怀里还揣着灵山发还的"转生批文"——上面写"第十世，取经，必死"。你在襁褓中第一次睁眼，看见的不是母亲的脸，是刘洪手中的刀。你忽然明白：取经之路，从出生那一刻起，就已经开始了。九世的死，换不来一世的生——这一世，你要自己活。' },
    3: { name: '江流漂孤', dark: '你被装进木盆漂江。盆底刻字："此子当祭江神"。你第一次懂：取经人，本就是给龙王的祭品。木盆在江水中颠簸，你听见江底传来九世取经人的哭声——他们都在这里，被江神吞噬，连骨头都没剩下。你伸手摸了摸盆底的刻字，忽然笑了："祭江神？那我倒要看看，江神敢不敢收我。"这一世，你不是祭品，你是取经人。' },
    4: { name: '金山寺养', dark: '法明和尚养你长大，却从不许你诵《楞严》。他说："那经里，写着你自己的死期。"你在金山寺长到十八岁，每天扫地、挑水、念经——唯独不诵《楞严》。你问法明和尚为什么，他总是叹气："金蝉，有些经，不是给活人念的。"你不懂，但你听话。直到有一天，你在藏经阁的角落里，发现了一本泛黄的《楞严经》——扉页上写着你的名字，和一个死期。' },
    5: { name: '出城逢虎', dark: '长安城外虎精拦路。你双手合十："阿弥陀佛。"虎竟伏地——它认得你身上的金蝉气。猎户伯钦说："这虎，吃过九世你。"' },
    6: { name: '双叉岭前', dark: '双叉岭前，你遇刘伯钦。他留你歇宿，夜里却听见他在磨刀。你问他磨什么刀，他笑："杀虎的刀。"你却看见刀上刻着"取经人"三字——这刀，杀过九世你。你合掌："施主，刀磨得再快，也磨不掉命。"刘伯钦怔住，刀落在地上。' },
    7: { name: '双叉岭上', dark: '岭上魔影是历代取经人的"不甘"。它们围着你转，想借你的身再走一遭。你念经超度，它们却哭："我们不想成佛，只想回家。"' },
    8: { name: '五行山遇', dark: '五行山下压着悟空。你揭去符咒，他第一句话："你也是被压的。"你默然——你被压在"命"里。五行山的符咒在你手中化为灰烬，悟空从山下跃出，抖落满身的石屑。他看着你，忽然笑了："和尚，你揭的不是符咒，是你自己的命。"你怔住——他说的，是实话。你被压在"取经必死"的命里，已经九世了。这一世，你要自己揭去符咒。' },
    9: { name: '收心猿', dark: '你收悟空为徒。他杀人你念咒，他不杀人你也念咒——咒不是管他，是管你自己的害怕。悟空第一次杀人时，你念了三遍紧箍咒，他在地上打滚，疼得龇牙咧嘴。你看着他，忽然觉得自己比他还疼——你怕的不是他杀人，是他杀红了眼，连你也杀。你念咒，不是管他，是管你自己的害怕。悟空后来不杀人了，你也不念咒了——但你知道，那害怕，还在。' },
    10: { name: '虎先锋拦路', dark: '虎先锋横刀拦路。你叹："连虎都来拦取经人，这经到底碍着谁了？"虎先锋一愣——它从没想过这个问题。黄风岭的虎先锋，手持赤铜刀，拦住了取经人的去路。你坐在马上，看着它，忽然叹了口气："连虎都来拦取经人，这经到底碍着谁了？"虎先锋愣住了——它从没想过这个问题。它只是奉命拦路，从没想过为什么。你合掌："虎先锋，你拦的不是取经人，是你自己的命。"虎先锋怔住，赤铜刀落在地上。' },
    11: { name: '黄风卷沙', dark: '黄风怪吹起满山黄沙。你眼前浮现灵山账簿：每一卷经，都标着"值几世命"。你闭眼："我不看了。"黄风岭的黄沙遮天蔽日，你在风中艰难前行，眼前忽然浮现灵山的账簿——每一卷经，都标着"值几世命"。《心经》值一世，《金刚经》值三世，《楞严经》值九世。你看着账簿，忽然觉得自己不是在取经，是在买经——用命买。你闭上眼睛："我不看了。经是死的，命是活的。这一世，我要用活的命，取死的经。"' },
    12: { name: '三昧神风', dark: '三昧神风吹得你睁不开眼。风里有貂鼠的怨："我守了一辈子酥陀，连尝一口都不配。"你合掌："那你尝一口我的经。"黄风岭的三昧神风，迎面吹来，遮天蔽日。你在风中艰难前行，风里传来貂鼠的怨声："我守了一辈子酥陀，连尝一口都不配。"你合掌，迎着风走上前："那你尝一口我的经。"风眼里的貂鼠怔住——它守了千年酥陀，从没想过尝一口经。它只是奉命看守，从没想过为什么。你合掌："貂鼠，你守的不是酥陀，是你自己的命。经不是给活人念的，是给死人念的。这一世，我要用活的命，取死的经。"风眼里的怨，散了一瞬。你继续前行，袈裟在风中猎猎作响，九世的死，换不来一世的生——这一世，你要自己活。',
         // 取经人只走袈裟单一路线：layer12 本难原掉八戒基座(bj_robe_base)，覆盖为袈裟基座，避免 armor 位混乱
         treasure: { id: 'ts_robe_base', type: 'armor', hp: 90, dr: 0.05, mdef: 0.05, note: '袈裟胚·取经人专属基座（覆盖八戒基座）' } },
    13: { name: '黄风大圣', dark: '黄风大圣立在风眼，金目赤红。你合掌问它："你守酥陀千年，可曾尝过一口？"它怔住——风眼里的怨，散了一瞬。黄风岭的风眼之中，黄风大圣手持三股钢叉，金目赤红，三昧神风从它口中喷出。你合掌，迎着风走上前："黄风大圣，你守酥陀千年，可曾尝过一口？"黄风大圣怔住了——它守了千年酥陀，从没想过尝一口。它只是奉命看守，从没想过为什么。风眼里的怨，散了一瞬。你合掌："黄风大圣，你守的不是酥陀，是你自己的命。"' },
    14: { name: '高老庄遇', dark: '高老庄庄主哭诉女儿被妖强占。你问那妖可曾伤人，庄主摇头："不曾伤人，只是能吃。"你合掌："能吃不是罪，强占才是。"你决定先去看看那妖——也许，他不是妖，是个被误解的人。' },
    15: { name: '云栈洞探', dark: '云栈洞中，你见那妖正对着镜子梳妆。他看见你，不慌不忙："和尚，你是来降我的？"你摇头："我是来问你，为何强占高家小姐。"他低下头："我前世是天蓬元帅，因情被贬。我以为，强占便是爱。"你合掌："爱不是占有，是成全。"' },
    16: { name: '八戒归降', dark: '猪八戒跪在你面前，痛哭流涕："师父，我老猪知错了，愿随师父西行，戴罪立功。"你扶起他，叹道："知错能改，善莫大焉。只是，你这一路，要戒的不是八样，是一样——情。"猪八戒怔住，缓缓点头。' },
    17: { name: '高老送别', dark: '高老庄庄主送你出门，欲言又止。你问他有何话说，他叹道："长老，那猪妖……虽能吃，却也护了我家庄园三年。"你合掌："施主，善恶本无界，只在一念间。他护你庄园，便是善；强占你女，便是恶。如今他已归正，往事便如烟吧。"庄主点头，目送你西行。' },
    18: { name: '流沙收沙', dark: '沙僧颈挂九颗骷髅，向你跪下："师父，我是你前九世。"你伸手："第十世，我们一起不死了。"流沙河的水浊浪滔天，沙僧从水中跃出，颈挂九颗骷髅，每一颗都闪着幽幽的青光。他向你跪下，声音沙哑："师父，我是你前九世。"你看着他颈上的九颗骷髅，忽然觉得那不是骷髅，是九世的你。你伸手扶起他："第十世，我们一起不死了。"沙僧怔住，九颗骷髅同时发光——它们等这句话，等了九世。' },
    19: { name: '五庄偷果', dark: '镇元子的人参果根缠取经人尸骨。你止住八戒："别吃。我们吃的，是自己的前辈。"五庄观的人参果树，三千年一开花，三千年一结果，三千年才得熟。你在树下抬头，忽然看见树根缠着累累白骨——那是历代取经人的尸骨。八戒伸手要摘人参果，你一把止住他："别吃。我们吃的，是自己的前辈。"八戒怔住，手停在半空。镇元子从殿中走出，叹道："金蝉，你终于看见了。这人参果，养的不是仙，是取经人的命。"' },
    20: { name: '三戏白骨', dark: '白骨精求你超度。你念经时她化烟散去，留下一句："金蝉，你每世都念错经——因为经是写来骗你的。"白虎岭的白骨精，三次变化，三次被悟空打杀。你第三次念紧箍咒时，白骨精却没有逃，反而向你跪下："金蝉，求你超度我。"你合掌念经，她在经声中化烟散去，留下一句话："金蝉，你每世都念错经——因为经是写来骗你的。"你怔住，经声戛然而止。悟空看着你："师父，她说什么？"你摇头："没什么。"但你知道，她说的，是实话。' },
    21: { name: '贬退心猿', dark: '你亲手写下贬书，赶走悟空。他跪在门口："师父，俺老孙杀的是妖。"你背过身："妖也有心，你杀红了眼。"他走了，你摸着空空的袖口——那里曾藏着他的救命毫毛。你忽然明白：贬他，贬的是你自己的怕。' },
    22: { name: '黄袍掳唐', dark: '黄袍怪把你变虎。你趴在地上才懂：天庭眼里的"取经人"，本就是"畜"。宝象国的黄袍怪，原是天上的奎木狼，下凡为妖，把你掳进波月洞，变作一只猛虎。你趴在地上，看着自己的虎爪，忽然懂了——天庭眼里的"取经人"，本就是"畜"。他们让你取经，不是为了传法，是为了驯服你。你趴在地上，发出一声虎啸——那不是虎啸，是金蝉的怒吼。宝象国的文武百官看着笼中的猛虎，无人知道，那笼中关的，不是虎，是取经人。' },
    23: { name: '黑松林失', dark: '黑松林黑雾起，你被掳。你在雾里听见妖怪的脚步声，却听不见自己的心跳："原来取经人丢了，连个找的人都没有。"你闭上眼，等下一世的转生批文。' },
    24: { name: '平顶逢魔', dark: '金角银角奉旨"被收"。你看出他们法宝上的"道具"二字，苦笑："连妖，都是演的。"平顶山的金角大王、银角大王，手持紫金红葫芦、羊脂玉净瓶，拦住取经人的去路。你看着他们手中的法宝，忽然苦笑——法宝上刻着"道具"二字，那是天庭的标记。金角银角，本是太上老君看金炉、银炉的童子，奉旨下凡为妖，"被收"回天。你合掌："连妖，都是演的。那取经，是不是也是演的？"金角银角怔住，紫金红葫芦落在地上。' },
    25: { name: '乌鸡井冤', dark: '乌鸡国王托梦诉冤。你下井背尸，尸身重如山——那是千万取经人叠成的"国"。乌鸡国的国王，被妖道推入井中，三年不得超生。他托梦给你，诉冤情，求你救他。你下井背尸，尸身重如山——那不是一个国王的尸身，是千万取经人叠成的"国"。你背着尸身，一步一步爬出井，忽然明白：取经之路，背的不是经，是千万取经人的冤。你把尸身背出井，悟空用还魂丹救活国王。国王跪在你面前："圣僧，你救的不是我，是乌鸡国。"你摇头："不，我救的，是取经人。"' },
    26: { name: '黑水鼍龙', dark: '鼍龙是西海旁支，因"逆"被贬。你渡他："逆不丢人，丢人的是顺了还装善。"黑水河的鼍龙，原是西海龙王的外甥，因"逆"被贬，在黑水河为妖，化舟渡你过河，却在江心掀翻船只，要吃你。你在水中看着他，忽然笑了："鼍龙，你因逆被贬，可你知道吗？我也是因逆被贬。"鼍龙怔住——他从没想过，取经人也是逆的。你合掌："逆不丢人，丢人的是顺了还装善。"鼍龙跪在水中，九片龙鳞同时发光——它们等这句话，等了千年。' },
    27: { name: '火云真火', dark: '红孩儿的三昧真火，烧出你袈裟下的金蝉本相。你悟："火不是劫，是照见。"号山枯松涧火云洞的红孩儿，手持火尖枪，口喷三昧真火，拦住取经人的去路。你在火中艰难前行，袈裟被烧得焦黑，露出下面的金蝉本相——金光万道，瑞气千条。你看着自己的金蝉本相，忽然悟了："火不是劫，是照见。"三昧真火烧的不是你的身，是你的壳。壳烧尽了，本相就露出来了。红孩儿看着火中的金蝉，怔住了——他从没想过，取经人不是人，是金蝉。' },
    28: { name: '黑水河渡', dark: '黑水河黑水滔滔，鼍龙化舟渡你过河。你在舟中见水底沉尸累累——那是历代取经人的尸骨。你合掌："他们没过去的河，我替他们过。"鼍龙在水底笑："你过了河，也成不了佛——佛，不过河。"' },
    29: { name: '车迟国前', dark: '车迟国国王崇道灭佛，和尚被赶去做苦役。你路过城门，见两个道士鞭打和尚。你合掌："施主，佛道本一家，何必相煎？"道士冷笑："佛？佛能求雨吗？"你抬头，见天上云聚——"能。"你低声说。道士怔住。' },
    30: { name: '三清观戏', dark: '三清观中，虎力、鹿力、羊力三妖化作三清，受香火供奉。你夜探三清观，见供桌上的素斋——那是和尚们饿着肚子供的。你合掌："三清在上，弟子有一问：佛道相争，争的是香火，还是人心？"三清像不答。你叹："不答，便是答了。"' },
    31: { name: '高台求雨', dark: '车迟国高台求雨，虎力大仙登坛作法。你在台下合掌，默念《心经》。虎力求了半个时辰，滴雨未下。你登台，只念了一句"阿弥陀佛"，天降甘霖。国王大惊："圣僧真神！"你合掌："不是神，是心诚。"' },
    32: { name: '隔板猜物', dark: '车迟国隔板猜物，鹿力大仙与你比试。柜中放的是山河社稷袄，乾坤地理裙。你合掌，默念《心经》，心中浮现柜中之物——"山河社稷袄，乾坤地理裙。"国王大惊。你叹："不是我能猜，是这世上的物，都在经里。"' },
    33: { name: '云梯显圣', dark: '车迟国云梯显圣，羊力大仙与你比试坐禅。云梯高百丈，你合掌而上，心中默念《心经》。羊力在云端坐了三个时辰，终于撑不住落下。你仍在云端，合掌不语。国王叹："圣僧真乃活佛！"你睁眼："不是佛，是心定。"' },
    34: { name: '车迟除妖', dark: '车迟国三妖现原形，虎力、鹿力、羊力跪地求饶。你合掌："你们崇道灭佛，害了多少和尚？"三妖泣道："我们也是被天庭利用，求圣僧饶命。"你叹："饶命可以，但你们要替那些被你们害死的和尚，念经超度。"三妖叩首，含泪念经。' },
    35: { name: '金兜遇琢', dark: '金刚琢套尽万物。你合十："套我吧。金蝉本就该被收。"青牛精却手抖——他套不住"已空"的人。金兜山的青牛精，手持金刚琢，套尽万物，拦住取经人的去路。你看着他手中的金刚琢，忽然合十："套我吧。金蝉本就该被收。"青牛精举起金刚琢，向你套来——却在半空中停住了。他手抖，因为他套不住"已空"的人。你看着他，忽然笑了："青牛，你套尽万物，可套得住空？"青牛精怔住，金刚琢落在地上。太上老君从云中走出，叹道："金蝉，你终于空了。"' },
    36: { name: '金兜降牛', dark: '金兜山青牛精现原形，跪地求饶。你合掌："你是太上老君的坐骑，偷了金刚琢下凡。你可知罪？"青牛精泣道："我知罪。我只是想尝尝，不被人骑的滋味。"你叹："不被人骑的滋味，不是偷来的，是挣来的。你跟我西行一路，便懂了。"青牛精叩首，含泪随老君回天宫。' },
    37: { name: '女儿国留', dark: '女王要你留下。你第一次动摇："取经，是为了谁？"紫金钵在怀中发烫——它在替你回答。西梁女国的女王，倾国倾城，愿以一国之富，招你为王，她为王后。你坐在龙椅上，看着女王的眼睛，第一次动摇了："取经，是为了谁？"紫金钵在怀中发烫——它在替你回答。你伸手摸了摸怀中的紫金钵，忽然想起九世取经人的死。你合掌："女王，贫僧已许身佛门，不敢再恋红尘。"女王落泪："御弟哥哥，你当真要走？"你点头，却不敢看她的眼睛——你怕一看，就走不了了。' },
    38: { name: '女王招亲', dark: '女王与你并肩看花，说："你取经回来，还来吗？"你合十，却答不出"不来了"。御花园的花开得正好，你忽然希望这朵花，能开到你回来那天。' },
    39: { name: '蝎子精刺', dark: '毒敌山琵琶洞蝎子精掳你入洞，欲逼你成亲。你合掌："女菩萨，贫僧是出家人，不敢破戒。"蝎子精冷笑："出家人？你在女儿国，可不是这么说的。"你默然——她刺中的，不是你的身，是你的心。你闭目念经，蝎子精却被昴日星官收服。你叹："心若不定，经念得再多，也是枉然。"' },
    40: { name: '蝎子倒马', dark: '蝎子精倒马毒桩刺你。你见她毒针是如来指甲——佛也怕人看清，故长毒。毒敌山琵琶洞的蝎子精，手持三股钢叉，尾后倒马毒桩，拦住取经人的去路。她一毒桩刺来，你伸手去挡，毒针刺中你的手掌，剧痛钻心。你看着她尾后的毒针，忽然怔住——那毒针，是如来佛祖的指甲。蝎子精冷笑："金蝉，你看见了？这毒针，是如来的指甲。佛也怕人看清，故长毒。"你合掌："蝎子精，你偷了如来的指甲，可偷得来如来的法？"蝎子精怔住，三股钢叉落在地上。昴日星官从云中走出，双翅一展，蝎子精现了原形。' },
    41: { name: '火焰山前', dark: '火焰山烈焰冲天，八百里火焰，无春无秋，四季皆热。你合掌："这火，是当年俺老孙踢翻太上老君的炼丹炉，落下的火。"悟空在一旁低头不语。你叹："解铃还须系铃人。这火，还得俺老孙来灭。"悟空抬头："师父，俺老孙这就去借芭蕉扇！"' },
    42: { name: '三调芭蕉', dark: '孙悟空三调芭蕉扇，与牛魔王、铁扇公主斗法。你在一旁合掌念经，心中却忐忑——这一战，关乎取经成败。悟空终于借到芭蕉扇，扇灭八百里火焰。你叹："火灭了，可心里的火，何时能灭？"悟空笑："师父，到了灵山，心里的火，自然就灭了。"' },
    43: { name: '祭赛国前', dark: '祭赛国金光寺塔顶舍利被盗，国王震怒，将众僧下狱。你夜探金光寺，见塔顶留有妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"你合掌："舍利本在心中，不在塔上。但众生需要光，我便替他们把光找回来。"' },
    44: { name: '碧波潭探', dark: '碧波潭底，万圣龙宫灯火通明。九头虫把舍利当夜明珠，挂在龙女床头。你潜潭暗查，见龙女抱着舍利喃喃："偷来的光，也是光。"——她不知道，偷来的光，照不亮自己。你合掌："光，不是偷来的，是自己心里发出来的。"龙女怔住，舍利在她怀中发光。' },
    45: { name: '真假美猴', dark: '六耳猕猴打翻你。你分不清哪个是悟空——正如分不清"取经"哪句是真。花果山的六耳猕猴，化作悟空的模样，打昏你，抢走行李，要自己去取经。你醒来时，看见两个悟空站在你面前——一个是真的，一个是假的。你分不清哪个是悟空，正如分不清"取经"哪句是真。两个悟空打到天庭，天庭分不清；打到观音，观音分不清；打到地府，地府分不清；打到灵山，如来佛祖才分清。你看着真悟空打死假悟空，忽然明白：取经之路，打的不是妖，是自己的心魔。六耳猕猴，不是别人，是悟空的心魔。' },
    46: { name: '火焰借扇', dark: '铁扇公主不借扇。你叹："牛魔一家的火，比灵山的灯真。"火焰山的铁扇公主，手持芭蕉扇，一扇息火，二扇生风，三扇下雨。你向她借扇，她却不借——因为悟空降了她的儿子红孩儿。你坐在翠云山上，看着铁扇公主的背影，忽然叹道："牛魔一家的火，比灵山的灯真。"铁扇公主怔住，回头看你："金蝉，你说什么？"你合掌："女菩萨，你恨悟空降了红孩儿，可你知道吗？红孩儿在观音身边，比在你身边好。"铁扇公主落泪，芭蕉扇落在地上。' },
    47: { name: '牛魔王战', dark: '牛魔王现出原形，一头大白牛，头如峻岭，眼若闪光。你合掌："牛施主，你与悟空是结拜兄弟，何必相煎太急？"牛魔王怒吼："结拜兄弟？他欺我妻子，辱我孩儿，还配叫兄弟？"你默然——这一战，不是妖与佛的战，是情与义的战。悟空终于降服牛魔王，你叹："情之一字，最难放下。"' },
    48: { name: '罗刹女泪', dark: '铁扇公主交出芭蕉扇，泪流满面。你合掌："女菩萨，你与牛魔王的恩怨，到此为止吧。"铁扇公主泣道："圣僧，我与牛魔王夫妻一场，如今他被降服，我活着还有什么意思？"你叹："活着，就是意思。你把芭蕉扇借给我们，扇灭火焰山，便是功德一件。"铁扇公主点头，含泪回翠云山。' },
    49: { name: '火焰山过', dark: '孙悟空扇灭八百里火焰，火焰山从此四季如春。你合掌："火灭了，我们可以继续西行了。"悟空笑："师父，这火，是俺老孙当年踢翻炼丹炉落下的，如今俺老孙亲手灭了，也算因果报应。"你叹："因果报应，丝毫不爽。我们西行取经，便是要了这因果。"众人继续西行。' },
    50: { name: '祭赛失舍', dark: '祭赛国舍利被窃，和尚蒙冤。你知舍利本就在每僧心中，不在塔上。祭赛国金光寺塔顶舍利被盗，国王震怒，将满寺僧众下狱，严刑拷打。你夜探金光寺，见塔顶留有妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"你合掌："舍利本在心中，不在塔上。但众生需要光，我便替他们把光找回来。"你望向西方，妖雾正浓——那是碧波潭的方向。你决定，明天就去碧波潭，把舍利找回来。' },
    51: { name: '金光寺冤僧', dark: '祭赛国金光寺舍利失窃，满寺僧众被冤下狱。你为僧申冤，寺僧眼中却没有谢意——他们求的不是公道，是有人替他们把"光"找回来。你忽然明白：金光寺的光，从来不在塔尖，在每个人心里。' },
    52: { name: '碧波潭探', dark: '碧波潭底，万圣龙宫灯火通明。九头虫把舍利当夜明珠，挂在龙女床头。你潜潭暗查，见龙女抱着舍利喃喃："偷来的光，也是光。"——她不知道，偷来的光，照不亮自己。' },
    53: { name: '万圣盗草', dark: '万圣公主盗了王母的九叶灵芝草，只为给九头虫续命。她捧着灵芝，像捧着一生一次的真心。你点破她："他若真心待你，何须你偷天宫的草？"公主怔住——她偷了一辈子，第一次被人问"值不值"。' },
    54: { name: '九头虫·碧波潭', dark: '碧波潭底，九头虫九头齐出，舍利在他腹中发光。你战他，他九个头同时冷笑："我偷的是舍利？不，我偷的是——你们和尚跪了千年，也没能跪来的光。"' },
    55: { name: '木仙谈诗', dark: '荆棘岭树精拉你吟诗。你念到"心似菩提树"，树精们忽然沉默。你抬头，见它们根下缠着历代取经人的尸骨——"诗，原来写的是这个。"' },
    56: { name: '小雷音诈', dark: '小雷音寺假佛坐殿。你跪下又起身："真佛不坐殿，坐的是难。"小雷音寺的黄眉老佛，化作如来佛祖的模样，坐在雷音寺的大殿上，受香火供奉。你走进大殿，看见"如来佛祖"端坐莲台，金光万道，瑞气千条。你跪下，却忽然起身——你看见了"如来佛祖"座下的金铙，那是弥勒佛的法宝。你合掌："真佛不坐殿，坐的是难。"黄眉老佛怔住，金铙从莲台下落下，现出原形。弥勒佛从云中走出，叹道："金蝉，你终于看见了。真佛不在殿上，在难中。"' },
    57: { name: '朱紫医王', dark: '朱紫国王悬丝诊脉，说病根在心。你切脉，切出他心底的娘娘——"陛下，你的病，是丢了心上人。"国王老泪纵横。你写下一张药方，方子上只有两个字：放下。' },
    58: { name: '狮驼城陷', dark: '狮驼岭三魔食尽一城。你站城头："取经路，原是尸路。"狮驼岭的青毛狮子怪、黄牙老象怪、大鹏金翅雕，三魔联手，食尽狮驼国一城百姓，连骨头都没剩下。你站在狮驼国的城头上，看着满城的尸骨，忽然明白了——取经路，原是尸路。九世取经人，都死在这条路上，连骨头都没剩下。你合掌："三魔，你们食尽一城，可食得来世？"三魔怔住，大鹏金翅雕落在你面前："金蝉，你看见了？这狮驼国，原是灵山的脚下。灵山食的，是千万城。"你抬头望向西方，灵山就在那里——金光万道，瑞气千条。你忽然明白：取经之路，取的不是经，是自己的心。' },
    59: { name: '祭赛金光', dark: '祭赛国金光寺塔顶舍利被盗，国王震怒，将众僧下狱。你夜探金光寺，见塔顶留有妖雾痕迹——那是碧波潭万圣龙王与九头虫所为。寺中老僧泣诉："舍利乃国之镇宝，失则国亡。"你望向西方，妖雾正浓。你合掌："舍利本在心中，不在塔上。但众生需要光，我便替他们把光找回来。"' },
    60: { name: '灭法剃王', dark: '灭法国要杀万名僧。你自投："杀我一个，抵万僧。"国王却放下刀——他也是被"命"压的人。灭法国的国王，前世是个和尚，被佛抛弃，转世为王，立志杀万名僧，以泄心头之恨。你走进灭法国，看见满城的和尚都被赶尽杀绝，连寺庙都被拆了。你合掌，走向王宫："杀我一个，抵万僧。"国王举起刀，却在半空中停住了——他看见了你眼中的慈悲，那是他前世的自己。国王放下刀，跪在你面前："圣僧，我杀了九千九百九十九个和尚，只差一个，就满万了。可我下不了手。"你合掌："陛下，杀的不是僧，是你自己的心。"国王落泪，灭法国从此改名为钦法国。' },
    61: { name: '隐雾梅花', dark: '隐雾山妖用你影分身。你笑："我本无相，分什么身。"隐雾山的艾叶花皮豹子精，用分瓣梅花计，化作你的模样，要骗你入洞。你看着眼前的"自己"，忽然笑了："我本无相，分什么身。"豹子精怔住——它从没想过，取经人会这么说。你合掌："豹子精，你化作我的模样，可化作我的心？"豹子精跪下，分瓣梅花计散了。悟空从洞中跃出，一棒打死豹子精。你看着豹子精的尸体，忽然叹道："它不是想吃我，是想成为我。可它不知道，成为我，比死还难。"' },
    62: { name: '凤仙求雨', dark: '凤仙郡三年不雨。你登上祈雨台，跪了三天三夜。第四天，玉帝仍不下雨。你站起身："我不求了。"你解下袈裟，拧出最后一滴水，浇在干裂的土地上——"求不来雨，就求自己。"' },
    63: { name: '玉华收徒', dark: '玉华州三王子拜你为师。你知他们拜的不是取经人，是"成佛的捷径"。你教他们第一课："捷径，是最长的路。"三王子不解。你合十："等我走到灵山，你们就懂了。"' },
    64: { name: '竹节九狮', dark: '九灵元圣衔你入洞，九颗狮头九双空眼——它不恨你，只是"天尊的坐骑，习惯了衔东西"。你合十："你衔了千年，可衔出过一口自己的愿？"九头齐怔，缓缓松口——它第一次，自己做了主。' },
    65: { name: '金平犀灯', dark: '三犀牛假佛收灯油，因真佛"收得太贵"。你看着跪拜的香客，取下自己的佛珠放进灯碗："真佛不收油，收的是人心。这一盏，我替他们点了。"灯油晃了晃，三犀牛却收了手——假佛也怕，照见自己的空。' },
    66: { name: '给孤招婚', dark: '天竺公主抛绣球招亲，你被砸中。公主笑："取经人，你取的是经，还是自己？"你合十——这一问，比八十一难都重。天竺国的公主，在彩楼上抛绣球招亲，绣球不偏不倚，正砸在你头上。你抬头，看见公主在彩楼上笑："取经人，你取的是经，还是自己？"你合十——这一问，比八十一难都重。你想起九世取经人的死，想起女儿国的女王，想起自己心中的动摇。你合掌："公主，贫僧取的是经，也是自己。经在西天，自己在心中。"公主怔住，绣球从你头上落下。悟空火眼金睛看穿公主本相——玉兔精假扮。他一棒砸开宫殿："你这玉兔，偷了嫦娥的灵药，也敢在俺老孙面前装神弄鬼？"玉兔精冷笑："偷来的灵药，也是灵药。你这猴子，偷了蟠桃，还有脸说我？"悟空怔住——她说的，是实话。嫦娥收服玉兔精，你叹："偷来的东西，终究不是自己的。"' },
    67: { name: '铜台辨冤', dark: '铜台府寇员外斋僧被害，你被诬为盗。你不辩——辩了，便是信了"取经人必善"的谎；不辩，才是真信自己。铜台府的寇员外，斋僧万员，却在一夜之间被人杀害，家财被劫。你和徒弟们被诬为盗，打入死牢。你坐在牢中，不辩——辩了，便是信了"取经人必善"的谎；不辩，才是真信自己。悟空不辩，只挨了一夜板子。天明他站起来："俺老孙当年被压五行山，都没喊过冤。这板子，权当替师父挨的。"你合掌："悟空，委屈你了。"悟空笑："师父，不委屈。俺老孙的命，都是师父给的。"后来，寇员外的妻子诬告你，你仍不辩。直到地藏王菩萨显灵，还你清白。你走出死牢，看着铜台府的百姓，忽然叹道："清者自清，浊者自浊。辩与不辩，都在心中。"众人继续西行。' },
    68: { name: '天竺国前', dark: '天竺国国都，繁华似锦。你合掌："到了天竺，离灵山就不远了。"悟空笑："师父，天竺国的公主，可是玉兔精假扮的。"你叹："真假难辨，正如取经之路。我们西行取经，取的不是经，是自己的心。"众人继续前行，心中却忐忑——这最后一难，关乎取经成败。' },
    69: { name: '玉兔精现', dark: '天竺国公主抛绣球招亲，你被砸中。公主笑："取经人，你取的是经，还是自己？"你合十——这一问，比八十一难都重。悟空火眼金睛看穿公主本相——玉兔精假扮。他一棒砸开宫殿："你这玉兔，偷了嫦娥的灵药，也敢在俺老孙面前装神弄鬼？"玉兔精冷笑："偷来的灵药，也是灵药。你这猴子，偷了蟠桃，还有脸说我？"悟空怔住——她说的，是实话。嫦娥收服玉兔精，你叹："偷来的东西，终究不是自己的。"' },
    70: { name: '铜台府案', dark: '铜台府寇员外斋僧被害，你被诬为盗。你不辩——辩了，便是信了"取经人必善"的谎；不辩，才是真信自己。悟空不辩，只挨了一夜板子。天明他站起来："俺老孙当年被压五行山，都没喊过冤。这板子，权当替师父挨的。"你合掌："悟空，委屈你了。"悟空笑："师父，不委屈。俺老孙的命，都是师父给的。"众人继续西行。' },
    71: { name: '灵山前望', dark: '灵山在望，金光万道。你合掌："到了灵山，我们就能取经了。"悟空笑："师父，灵山的经，可不是那么好取的。"你叹："取经之路，九九八十一难，我们都走过来了。最后一难，又算得了什么？"众人继续前行，心中却忐忑——这最后一难，关乎取经成败。你回头望了一眼来时的路，心中暗想："取经之路，取的不是经，是自己的心。"' },
    72: { name: '凌云渡前', dark: '凌云渡前，弱水滔滔。你合掌："过了凌云渡，就是灵山了。"悟空笑："师父，凌云渡的弱水，可是连鹅毛都浮不起来的。"你叹："取经之路，九九八十一难，我们都走过来了。凌云渡，又算得了什么？"接引佛祖撑船而来："取经人，上船吧。"你上船，船行至江心，忽然翻了——你落水，却见水中有一具死尸。悟空笑："师父，那死尸，是你自己。"你怔住——过了凌云渡，你就不再是你了。' },
    73: { name: '化电归真', dark: '雷音门前最后一考："做经，还是做自己？"你伸手去接经卷，指尖触到的却是自己的心跳——经是死的，心跳是活的。你缩手。' },
    74: { name: '雷音寺前', dark: '雷音寺前，金光万道。你合掌："到了雷音寺，我们就能取经了。"悟空笑："师父，雷音寺的经，可不是那么好取的。"你叹："取经之路，九九八十一难，我们都走过来了。最后一难，又算得了什么？"众人继续前行，心中却忐忑——这最后一难，关乎取经成败。你回头望了一眼来时的路，心中暗想："取经之路，取的不是经，是自己的心。"' },
    75: { name: '如来佛祖', dark: '如来佛祖端坐莲台，金光万道。你合掌："弟子玄奘，奉东土大唐皇帝旨意，前来拜佛求经。"如来佛祖笑："玄奘，你取经十世，到底取的是什么？"你怔住——这一问，比八十一难都重。你抬头，见佛座下压着十卷经——每一卷，都是一世取经人的名字。你忽然明白："我取的，从来不是经，是我自己。"如来佛祖点头："善哉善哉。你终于明白了。"' },
    76: { name: '问佛根源', dark: '你跪灵山，问佛："弟子取经十世，到底取的是什么？"佛不答。你抬头，见佛座下压着十卷经——每一卷，都是一世取经人的名字。你忽然明白："我取的，从来不是经，是我自己。"' },
    77: { name: '灵山无字', dark: '灵山不见佛影，只有一块无字碑。碑上说：来者皆被写进经，有人把经当牢。你面前，是历代取经人的"合体"——大圣残躯。你合十："我不进经。我要出去。"' },
    78: { name: '取经回东', dark: '你取到真经，辞别如来，回东土大唐。悟空笑："师父，我们终于取经成功了。"你叹："取经之路，九九八十一难，我们都走过来了。如今取经成功，却不知该喜还是该悲。"众人继续前行，心中却忐忑——取经成功，意味着分离。你回头望了一眼灵山，心中暗想："取经之路，取的不是经，是自己的心。如今经取到了，心，又在哪里？"' },
    79: { name: '通天河遇', dark: '通天河前，弱水滔滔。你合掌："过了通天河，就是东土大唐了。"悟空笑："师父，通天河的老鼋，可是当年驮我们过河的。"老鼋游来："取经人，上船吧。"你上船，船行至江心，老鼋忽然问："取经人，我当年托你问如来佛祖，我何时能脱壳成人，你问了吗？"你怔住——你忘了。老鼋大怒，将船掀翻，众人落水，真经也被水浸湿。你叹："九九八十一难，还差一难。如今这一难，终于来了。"' },
    80: { name: '真经晒干', dark: '众人落水，真经被水浸湿。你合掌："真经被水浸湿，如何是好？"悟空笑："师父，我们把真经晒干就是了。"众人将真经摊在石头上晒干，却发现最后一页被石头粘住，撕坏了一角。你叹："真经不全，如何是好？"悟空笑："师父，真经不全，正如人生不全。不全，才是真。"你点头："善哉善哉。不全，才是真。"众人继续前行，回东土大唐。' },
    81: { name: '无字碑终', dark: '你立无字碑，自沉："他碎了紫金钵，也碎了\'取经命数\'。金蝉，从此是传说。"',
         intro: '取经人专属终章。选择"这一世，你替自己活过"。',
         options: [
           { key: '逆', label: '碎钵自渡', fate: '逆', ending: '真·金蝉结局（弃经金蝉觉醒，解锁取经人终极隐藏职）' },
           { key: '渡', label: '留经善名', fate: '渡', ending: '善之结局（金蝉成佛）' },
           { key: '隐', label: '携碑隐世', fate: '隐', ending: '隐世结局（取经人暗线激活）' }
         ] },
  },
};
